/* ⛔ GENERATED by kit/build.mjs from i18n/fr.json, the changelog and the kit. Do not edit. */
(window.FREALLY_I18N = window.FREALLY_I18N || {})["fr"] = {"hero.headline":"<span class=\"hl-muted\">Du MIDI fidèle à l’artiste,</span> <span class=\"hl-bright\">dans votre DAW.</span>","index.0e16857e":"Batteries, mélodies, contre-mélodies, 808, accords et arrangements complets — générés dans le style d’artistes précis, en MIDI original, <strong>dans la tonalité et le tempo de votre propre projet</strong>. Gratuit, hors ligne et 100 % sans IA.","hero.chipStandalone":"Autonome","hero.chipWeb":"Web","hero.chipLinux":"Linux (éditeur en cours)","index.a9e41a1f":"État — c’est un plug-in maintenant","index.4c860bcf":"Freally MIDI Master a commencé comme application de bureau ; <strong>v0.2.0</strong> était cette version. Depuis le <strong>29 juillet 2026, l’application de bureau est retirée</strong> — elle n’est plus compilée ni publiée. Ce qui est déjà installé continue de fonctionner ; simplement, plus aucune mise à jour n’arrive.","index.986fa10d":"C’est maintenant un <strong>plug-in CLAP, dont VST3 et AU sont projetés</strong> — non pas pour le format, mais parce qu’un plug-in reçoit le tempo, la métrique et la tête de lecture de l’hôte. Un motif généré atterrit dans le morceau que vous écrivez vraiment, au lieu du tempo auquel l’artiste se trouve écrit.","index.e46c4677":"Il se charge et génère dans <strong>Ableton Live&nbsp;12</strong> (VST3) et <strong>FL&nbsp;Studio</strong> (CLAP). Reaper, Bitwig et Logic ne sont pas encore testés. La version autonome exécute le même plug-in dans sa propre fenêtre, sans aucune DAW.","see.title":"À quoi il ressemble","see.intro":"Le plugin en marche : une mélodie générée avec le clavier d’où vous la jouez, et un arrangement complet sur une ligne de temps.","features.0cdb36f4":"Freally MIDI Master avec une mélodie trap générée : les pads de batterie en haut, le piano roll et sa piste de vélocité, les quatre clips Re-Dream en dessous, et le clavier à l’écran tout en bas.","features.1ef3563d":"Une mélodie trap générée, sa piste de vélocité, les quatre Re-Dreams qui en découlent, et le clavier depuis lequel vous pouvez la jouer.","features.dacd8e46":"Mode Morceau : un arrangement de 56 mesures sur une frise, avec des sections INTRO, COUPLET, REFRAIN et OUTRO et un clip modifiable par partie — batterie, accords, mélodie et contre-mélodie — chacun portant son propre jeton MIDI et Audio.","features.6fe61d69":"Mode Morceau : un arrangement entier sur une frise modifiable, un clip par partie, chacun avec son propre MIDI et son audio à faire glisser.","home.inside.title":"Ce qu'il contient","index.92530b36":"Des artistes, pas des genres","index.420c17ef":"La plupart des générateurs pensent en genres. « Trap » n’est pas « Metro Boomin », et aucun outil grand public n’a jamais entendu parler d’OsamaSon. Tapez un nom et vous obtenez des motifs qui portent les signatures réelles de cet artiste.","index.e6a1356b":"Il suit votre DAW","index.bab9531a":"Le plug-in lit le tempo et la métrique de l’hôte à chaque bloc : un trap écrit à 140 sort à 92 dans un projet à 92&nbsp;BPM. Fixez un tempo et c’est le vôtre qui gagne.","index.4a2c8227":"Cinq générateurs, plus le mode Morceau","index.bd395814":"Batterie, mélodie, contre-mélodie, ligne de basse et accords — plus le mode Morceau, qui n’est pas un sixième générateur mais un arrangement qui remplit les cinq.","index.04c8fb28":"Chaque artiste a ses humeurs","index.efa5276f":"Choisissez une humeur et restez-y, ou laissez sur <em>Indifférent</em> et chaque pression parcourt l’éventail de cet artiste. Un artiste écrit plus d’un type de disque, et aucune graine ne pourrait passer de l’un à l’autre.","index.276d670e":"Construisez votre propre style","index.84153fc4":"Partez de n’importe quel artiste, ajustez ce qui vous importe, enregistrez-le — il figure dans le répertoire à côté de ceux livrés et fonctionne exactement pareil, parce que c’est la même chose. Étoilez les prises qui vous plaisent et il ajuste un style dessus.","index.5a9ab055":"Les notes arrivent sur la piste","index.06309989":"Aucun fichier à faire glisser, aucun dossier à chercher. Le plug-in émet du MIDI là où vous l’avez inséré, dans le temps de l’hôte lui-même.","index.191153d2":"Reproductible par graine","index.3bb0362b":"Chaque génération a une graine. Copiez-la, collez-la, retrouvez exactement le même beat — sur n’importe quelle machine, n’importe quel jour. Le déterminisme est imposé par la suite de tests.","index.f52c92c0":"Pas d’IA, pas de compte, pas de cloud","index.21393e5c":"Aucun modèle, aucune donnée d’entraînement, aucune inférence et aucun appel réseau pendant la génération. Aucune connexion et aucune télémétrie. Tout se passe sur votre machine — y compris « entraînez votre propre style », qui mesure les prises que vous avez gardées et réécrit les chiffres plutôt que d’apprendre quoi que ce soit. Une compilation qui aurait une IA ou un client HTTP quelque part dans ses dépendances échoue.","index.7f44a4fa":"La route vers la 1.0","index.99276787":"Chaque version apporte une capacité entière. Rien ne sort à moitié fait.","ladder.rung.v0.3.0":"Le virage vers le plugin. CLAP, avec VST3 et AU projetés depuis lui. Se charge dans Ableton et FL Studio.","ladder.rung.v0.4.0":"Annulation illimitée. Chaque changement de session, une frappe en arrière — sans limite de profondeur.","ladder.rung.v0.5.0":"Il produit un son. Un échantillonneur derrière les générateurs, vos propres one-shots sur n’importe quelle partie, et un transport qui joue dans le plug-in.","ladder.rung.v0.5.5":"Il joue d’un instrument. Un synthétiseur derrière chaque partie, une bibliothèque d’usine de 2 729 088 sons que vous pouvez parcourir par instrument et par genre, un créateur de packs d’échantillons, et un clavier jouable à tout moment.","ladder.rung.v0.5.7":"Une bibliothèque vaste et ultra-réaliste. Vingt-quatre nouveaux moteurs de synthèse et 750 nouveaux instruments — 975 en tout, du piano de concert aux sections d’archets en passant par des circuits analogiques modélisés — chacun mesuré face à l’objet réel dont il porte le nom. 1 614 600 sons, et toujours pas un seul fichier sur votre disque.","ladder.rung.v0.6.0":"Votre bibliothèque d’échantillons. Une arborescence de dossiers avec écoute, favoris étoilés, glisser-vers-pad et lecture inversée — et déposez un fichier MIDI, il devine quelles parties s’y trouvent.","ladder.rung.v0.7.0":"L’arrangement, comme dans une DAW. Des clips dessinés à partir de leurs propres notes, zoom, sélection multiple, rognage et clonage — et faites glisser le morceau entier, une piste par partie.","ladder.rung.v0.8.0":"67 genres, 2 000 artistes. Le répertoire complet — l’underground à côté du mainstream — chacun un modèle de style écrit à la main. Les 67 genres sont écrits, ainsi que 1 250 artistes et producteurs ; le reste est encodé depuis la recherche, un volume à la fois.","ladder.rung.v0.9.0":"Finitions et consolidation. Chaque état dessiné et chaque cas limite traité : accessibilité, HiDPI, résistance aux plantages, démarrage à froid en moins de trois secondes.","ladder.rung.v1.0.0-beta":"Fonctionnalités complètes. Tout ce que promet la 1.0, plus les salles de collaboration et Freally MixSir, le compagnon mobile. Toujours pas de téléchargement — c’est la version qui se fait tester à la main.","ladder.rung.v1.0.0RC":"Version candidate. Re-Dream arrive — chaque génération arrive en quatre, la prise que vous avez plus trois rêvées après elle, écoutées dans la piste avant que l’une ne remplace la partie. Ensuite la passe de test manuelle, menée de bout en bout sur du matériel réel dans une vraie DAW.","ladder.rung.v1.0.0":"Les téléchargements ouvrent. Les cinq générateurs plus le mode Morceau, les salles de collaboration et MixSir, tous les formats, sur les trois plateformes. La première version installable par tout le monde — après une passe d’optimisation, une passe de simplification, une revue de code et une revue de sécurité, avec les deux exécuteurs d’intégration continue auto-hébergés au vert.","index.daba7f83":"<strong>Il n’y a encore rien à télécharger.</strong> <strong>La v1.0.0RC est la prochaine</strong>, et elle est testée à la main en ce moment — chaque hôte, chaque OS, et tout ce qu’aucune suite de tests ne peut juger. Un plug-in qui fonctionne à moitié dans la session de quelqu’un est pire qu’un plug-in absent ; il sort donc quand cette matrice est au vert, et pas avant.","honest.title":"Ce que la plupart des sites relèguent tout en bas","index.25a8716e":"Le moteur est à base de règles, pas entraîné","index.644f2e23":"Il n’y a <strong>aucune IA dans ce produit</strong>. Aucun modèle, aucune donnée d’entraînement, aucune inférence, aucun appel réseau pendant la génération. Le moteur est du code procédural déterministe qui lit des paramètres de style écrits à la main, issus de recherches publiées. C’est une architecture juridique autant que technique : rien ici n’est du MIDI copié, de l’audio échantillonné ou la transcription du disque de quiconque, et aucune fonction ne recrée un morceau précis. Les noms d’artistes sont uniquement des références descriptives de style.","index.2419a115.t":"La musique que vous faites avec est la vôtre","index.2419a115.b":"Sans redevance et sans obligation d’attribution. Freally MIDI Master lui-même est propriétaire, Tous droits réservés, et son code source est privé — vous ne pouvez pas le redistribuer. Il n’est <em>pas</em> open source.","honest.names.title":"Les noms décrivent des styles","index.7e9d277b":"Les noms d’artistes et de producteurs dans Freally MIDI Master sont des références descriptives à un style musical, rien de plus. Aucune affiliation, approbation ou paternité n’est implicite ni revendiquée. Chaque motif est généré procéduralement à partir de paramètres de style écrits à la main — aucun MIDI, aucun audio, aucune donnée n’est copié d’un enregistrement. Toutes les marques et tous les noms appartiennent à leurs détenteurs respectifs. <a href=\"legal/disclaimer.md\">Lire l’avertissement complet</a>.","index.cf01481f":"Confidentialité","index.a4c6de24":"Aucun compte. Aucune télémétrie. Rien sur vous, vos projets ou vos productions n’est jamais transmis. Génération, lecture, import et export sont entièrement locaux.","index.6a3c2dd2.t":"Le plug-in n’établit aucune connexion sortante","index.6a3c2dd2.b":"Les deux qui existaient — une vérification de mise à jour au lancement et un rapport de plantage optionnel — appartenaient à l’application de bureau et ont été retirées avec elle. Un plug-in est installé et mis à jour par celui qui installe les plug-ins. Imposé par deux garde-fous de compilation plutôt que promis : <strong>aucun client HTTP n’est compilé dans le plug-in</strong> — toujours vrai, car le service de collaboration est atteint par un programme distinct, jamais par le plug-in que charge votre DAW — et l’interface elle-même est pilotée par une génération à chaque commit et échoue si elle tente une seule requête hors de la machine. Les rapports de plantage sont écrits sur votre propre disque et ne sont jamais envoyés ailleurs.","index.1497b93b.t":"L’application web est livrée par le réseau ; ce que vous créez, non","index.1497b93b.b":"Une page doit être téléchargée — l’application elle-même et les données de style à partir desquelles elle génère. C’est tout. La génération tourne sur votre machine, dans votre navigateur ; vos beats, vos graines et tout ce que vous importez y restent et ne sont jamais envoyés. Après une seule visite, l’onglet fonctionne réseau coupé, ce qui est plus proche du hors-ligne que ce que la plupart des logiciels arrivent à faire.","index.40df2f36.t":"La collaboration est la seule exception, et seulement si vous l’utilisez","index.40df2f36.b":"Les salles relient votre machine directement aux personnes que vous invitez. Si vous enregistrez quelqu’un comme contact, un petit service peut vous dire quand il est en ligne — et on ne lui dit rien d’exploitable : une clé qui change toutes les quelques minutes, et une adresse chiffrée avec un secret que vous seuls deux détenez. Il ne peut pas la lire, ne peut pas lister qui est là, et ne peut pas déduire qui connaît qui. Désactivez-le, ou n’enregistrez jamais de contact, et vous collez un code à la place — ce qui est de toute façon le fonctionnement des salles.","index.b5d5c2d0.t":"Une chose à venir, dite maintenant plutôt qu’au moment de la sortie","index.b5d5c2d0.b":"La fonction de collaboration — les salles, en développement et installées par rien aujourd’hui — doit apprendre l’adresse publique de votre machine avant que deux personnes puissent se connecter directement, et c’est à cela que sert un serveur STUN. Quand elle arrivera, ouvrir ou rejoindre une salle contactera un tel serveur ; cette version nomme Cloudflare et Google. Un tel serveur apprend seulement qu’une adresse utilise une application WebRTC — pas avec qui vous parlez, ni ce que vous envoyez — et rien n’est contacté avant que vous ouvriez ou rejoigniez une salle. La phrase ci-dessus reste vraie pour le plug-in tel qu’il est livré aujourd’hui.","site.tagline":"Du MIDI fidèle à l’artiste, généré sur la piste sur laquelle vous travaillez déjà.","footer.licence":"Propriétaire — Tous droits réservés. © Mike Weaver. Utilisation gratuite aujourd'hui ; les versions futures pourraient être vendues. Ce n'est pas un logiciel libre.","footer.yours":"La musique que vous faites avec est la vôtre, sans redevance et sans obligation d’attribution.","features.512c7b09":"Le générateur MIDI le plus complet jamais construit — et il ne coûte rien.","features.d19d4e76":"2 413 styles d’artistes et de producteurs. 1 648 instruments. Plus de 96 millions de prises distinctes par partie. Transformez n’importe quel fichier audio en MIDI. Re-rêvez n’importe quelle idée en quatre. Arrangez un morceau entier. <strong>Chaque fonction, pour tout le monde, gratuite aujourd’hui.</strong>","features.5e30071b":"Chaque chiffre ici est compté sur le produit livré et sa suite de tests. Rien n’est estimé, et rien n’est arrondi vers le haut.","featuresPage.numbers.models":"modèles de style","featuresPage.numbers.artists":"artistes","featuresPage.numbers.producers":"producteurs","featuresPage.numbers.instruments":"instruments","featuresPage.numbers.takes":"prises par partie","featuresPage.numbers.languages":"langues","featuresPage.numbers.ai":"modèles d'IA","featuresPage.numbers.price":"prix aujourd'hui","features.2fb7a96e":"C’est gratuit aujourd’hui. Tout.","features.6b604c8e":"Chaque fonction, pour tout le monde. Pas de palier payant, pas de clé de licence, pas d’achat intégré, pas d’abonnement, pas d’essai qui expire, pas de version « Pro » qui retient les bonnes parties en otage. C’est écrit dans le contrat de licence de cette version : <em>« Le logiciel est fourni gratuitement, dans son intégralité. »</em> <strong>Et la musique que vous faites avec est la vôtre</strong>, sans redevance et sans obligation d’attribution.","features.a5a8c798":"Fonctions phares","features.65a59ac5":"Cherchez un nom, pas un genre","features.177ce0e6":"2 413 artistes, producteurs et genres dans un seul champ — à travers les alias et malgré les fautes de frappe. Avant d’appuyer sur quoi que ce soit, il vous dit ce que cette sélection <em>fait</em> : son époque, sa plage de tempo, la tonalité vers laquelle elle penche, ses humeurs nommées, et quelles parties elle écrit et lesquelles non. Un artiste qui n’écrit pas de contre-mélodies le dit, au lieu de répondre à cet onglet par du silence.","features.c7e63f3a":"Re-Dream — la même idée, autrement","features.b9301e2e":"Relancer vous donne une autre idée. Un <strong>Re-Dream</strong> vous donne la même, autrement. Chaque génération arrive en quatre — la prise que vous avez, plus trois rêvées après elle — et vous écoutez chacune <em>dans votre piste</em>, contre votre batterie et votre 808. Un Re-Dream partage <strong>79 %</strong> des attaques de son original là où trois graines neuves en partagent 35 %. C’est un garde-fou dans la suite de tests, pas une affirmation. Cela marche aussi sur un fichier : choisissez un <code>.mid</code> dans le navigateur et le rack se remplit à partir de là plutôt que d’une génération.","features.a4d9cbed":"N’importe quel fichier audio devient du MIDI","features.5a6369dd":"Faites glisser <em>n’importe quel</em> échantillon — WAV, AIFF, FLAC, MP3, M4A, OGG — sur un générateur et il revient en notes. Attaques, tempo, longueur propre de la boucle, hauteur et contenu percussif, tout est mesuré. Et chaque partie vous dit <em>pourquoi</em> elle a été routée là, de sorte qu’une mauvaise supposition est un clic à rediriger plutôt qu’une découverte tardive.","features.fdfc6809":"Cinq générateurs et un morceau entier","features.fbe4c84f":"Batterie · Mélodie · Contre-mélodie · Ligne de basse · Accords — plus le mode Morceau, qui tire une des formes <em>propres</em> à l’artiste et la dessine sur une frise que vous pouvez modifier. Redimensionnez, clonez, verrouillez ce qui vous plaît, relancez une section sans toucher au reste.","features.d4dc7d3d":"C’est aussi un instrument","features.5c924fb6":"Un synthétiseur polyphonique avec <strong>1 648 instruments répartis sur 69 genres</strong>, et chaque générateur mélodique joue le sien — quatre voix à la fois, pas une seule partagée. Rien n’est une bibliothèque d’échantillons : chaque son est une adresse de cinq entiers, donc l’ensemble tient en quelques nombres dans votre fichier de projet.","features.3f42ac73":"Et vous pouvez le jouer","features.b9fcfc0e":"Un clavier à l’écran, les touches de votre ordinateur en second, et votre propre contrôleur MIDI avec filtre de canal, transposition, octave, plage de pitch bend et courbe de vélocité. Appuyez sur enregistrer et ce que vous jouez atterrit dans le clip de la partie — une note tenue par-dessus la fin de la boucle reste <em>une</em> note, et enregistrer à nouveau superpose plutôt que remplace. La molette de pitch plie <strong>tous</strong> les instruments, y compris ceux modélisés physiquement : les partiels d’une cloche et la corde d’une guitare suivent, tandis que ce qui ne suit pas une note — le corps d’un violon, les formants d’une voix — reste à sa place.","features.f3789702":"5 085 boucles MIDI, écrites par le même moteur","features.68dac5bc":"Packs d’usine : mélodies, lignes de basse, accords, contre-mélodies, boucles de batterie et de percussions, par genre. Parcourez-les avec ↑/↓ et chacune se joue dès que vous arrivez dessus. Faites-en glisser une sur un générateur et elle y atterrit, répartie sur les bonnes parties ; faites-la glisser dehors et elle part vers votre DAW comme clip. Neuf mégaoctets de <em>notes</em> — pas un gigaoctet d’enregistrements d’autrui, parce que nos propres générateurs et nos propres modèles ont écrit chacune d’elles.","features.99073b05":"Il ne vous donnera pas le refrain de quelqu’un d’autre","features.77e297a3":"Chaque mélodie est comparée à une table de contours bien connus <em>avant que vous ne l’entendiez</em>, et une prise qui correspond est jetée et tirée à nouveau. La table contient des empreintes à sens unique et aucune donnée de note — transposer un refrain ne le masque pas, et rien de ce qu’a écrit quelqu’un d’autre ne se trouve dans le produit.","features.05de2492":"Verrouillez, relancez, récupérez","features.8347a3e6":"Verrouillez ce qui vous plaît et relancez le reste — une piste verrouillée revient note pour note, autant de fois que vous appuyez sur Générer. Chaque génération a une graine : copiez-la, collez-la, récupérez-la. Et une annulation illimitée sur tout, parce qu’une entrée d’annulation est faite des réglages et non des notes.","features.5ec34078":"Pas d’IA. Pas un seul modèle.","features.f28580e7":"Ce n’est pas une limite — c’est le choix de conception. Des règles, des mesures et de l’aléatoire à graine de bout en bout, avec un garde-fou de compilation qui refuse toute dépendance susceptible d’introduire un modèle. Cela vous donne reproductibilité, explicabilité et une provenance défendable : rien n’a été entraîné sur les enregistrements de quiconque, parce que rien n’a été entraîné du tout.","features.79dacbd4":"Face aux grands générateurs MIDI","features.c9427ee1":"Compilé depuis le descriptif publié de chaque produit.","featuresPage.compare.feature":"Fonctionnalité","features.3e8248e3":"Prix","features.97ef455a":"Gratuit aujourd’hui","features.dc9d4584":"Payant","features.8fde48f3":"Abonnement","features.a036b01a":"Styles d’artistes / producteurs nommés","featuresPage.compare.legend.yes":"complet","featuresPage.compare.legend.no":"non proposé","features.a52b7c6e":"genres seulement","featuresPage.compare.legend.partly":"partiel","features.37d67e95":"répertoire sous licence","features.88048f2f":"Batterie <em>et</em> mélodie, basse, accords, contre-mélodie","features.a69f56a4":"les cinq","features.0f8398e4":"batterie seulement","features.5916033f":"Arrangement complet sur une frise modifiable","features.73ab2ff8":"<strong>Fichier audio → MIDI</strong>, n’importe quel échantillon","features.400bace7":"détection","features.11963ece":"Fichier MIDI → réparti en cinq parties, chacune avec sa raison","features.cc1b6bf2":"<strong>Re-Dream</strong> — la même idée, autrement","features.b21d091f":"morphing","features.75f1827c":"Graines reproductibles — collez-la, récupérez-la","features.215a67ab":"Synthé intégré que vous pouvez aussi simplement jouer","features.891ee051":"Vos propres échantillons sur n’importe quelle piste","features.1cc2b417":"Filtrage des refrains — refuse la mélodie d’autrui","features.ddfa7bdc":"Verrouillez ce qui vous plaît, relancez le reste","features.2cb5ea83":"Entraînez un style sur les prises que <em>vous</em> avez étoilées","features.dce5f5da":"pas de ML","features.5a67578e":"Fonctionne entièrement hors ligne, sans compte, sans télémétrie","features.b3f15e02":"dans le cloud","features.ceec1655":"<strong>Aucune IA/ML nulle part</strong> — des règles vérifiables","features.b72eae1f":"vérifié à chaque push","features.716f8c55":"Salles de collaboration en direct","features.f75444a3":"18 langues","features.a2295f23":"Annulation illimitée sur tout","features.036b5f21.t":"La version en une phrase","features.036b5f21.b":"Tous les autres produits de ce tableau vous demandent de l’argent pour faire une partie de ce que celui-ci fait. Celui-ci ne demande rien et fait tout.","features.3f4902cc":"Comparatif compilé depuis le descriptif public de chaque produit ; les produits changent, et les corrections sont bienvenues.","features.d452e239":"Pourquoi c’est construit comme ça","features.87e13091":"Reproductible","features.75b8dd39":"La même graine donne les mêmes notes, aujourd’hui et dans cinq ans. Rien d’entraîné ne peut le promettre.","features.20690c04":"Explicable","features.8d02c9f7":"Chaque génération peut vous dire quel paramètre l’a produite, parce qu’il y a un paramètre et non un poids.","features.4fd9fc99":"Une provenance défendable","features.489d6eaf":"Rien n’a été entraîné sur les enregistrements de quiconque, parce que rien n’a été entraîné du tout. Le corpus de recherche n’a jamais fourni que des distributions — jamais de données de notes, jamais d’audio.","features.0f211ed0":"Ça reste sur votre machine","features.94aff5cf":"Pas de compte, pas de connexion, pas de télémétrie, pas d’aller-retour vers le cloud. Ça marche en avion. Vos échantillons, votre MIDI, votre jeu et vos projets ne quittent jamais votre disque — <strong>pas un seul octet d’échantillon ne passe par le réseau</strong>, même dans une salle de collaboration.","features.e6a1356b":"Il suit votre DAW","features.e3a8277a":"Le plug-in lit le tempo et la métrique de l’hôte à chaque bloc, de sorte qu’un motif est généré <em>pour votre morceau</em> — un trap écrit à 140 sort à 92 dans un projet à 92 BPM. Fixez vous-même un tempo et c’est le vôtre qui gagne.","features.7142b88f.t":"À propos de ces 96 millions","features.7142b88f.b":"C’est mesuré, pas du marketing. La suite de tests rend 200 graines par modèle et mesure <strong>199 Re-Dreams distincts sur 200 tirages</strong> à partir d’une seule prise. Aucun des deux nombres ne s’épuise à 200 échantillons, donc les deux sont des <em>planchers</em> : ≥200 générations × ≥199 Re-Dreams ≈ 40 000 prises par modèle et par partie, et 40 000 × 2 413 modèles font plus de 96 millions — <em>par partie</em>, avant que les quatre parties mélodiques ne se combinent. Nous annonçons un plancher et jamais un total, délibérément : un total serait un plafond que le code ne peut pas prouver, et transformerait une inspiration qui ne s’épuise pas en un catalogue dont on peut imaginer la fin.","features.21cc118f":"Ce qui reste à venir","features.0b765e69":"Dit clairement, parce qu’une liste de fonctions qui cache ses manques ne vaut pas la lecture.","featuresPage.limits.title":"Pas encore terminé","features.3311e0fb":"<strong>Le glisser-déposer sortant sous macOS et Linux</strong> est écrit et activé mais n’a pas encore été déposé dans une vraie DAW. Sous Windows, si. L’export fonctionne partout de toute façon.","features.7a359bb4":"<strong>Raccourcis globaux, partage d’écran et caméra</strong> dans les salles de collaboration.","features.fa2456cd":"<strong>La v1.0.0RC arrive bientôt, et les téléchargements avec elle.</strong> D’ici là, la réponse honnête à « où est-ce que je le trouve ? » est <em>pas encore</em>.","documentation.ca365831":"Tout ce que fait le plug-in, et comment il décide quoi jouer.","documentation.e4253178":"Formats et hôtes","documentation.e3843261":"Installation","documentation.61c43d0a":"Le cycle de base","documentation.40f89a05":"Le répertoire","documentation.ba8c0def":"Humeurs","documentation.197723c7":"Votre propre style, et son entraînement","documentation.bd31a893":"Les pads de batterie","documentation.f3aaedd4":"Le navigateur d’échantillons","documentation.4a0779eb":"Déposer un fichier MIDI","documentation.ec0e4ac2":"Les générateurs","documentation.c1e2865a":"Mode Morceau","documentation.04770da9":"L’instrument","documentation.c20403bd":"L’audio exporté","documentation.a70dab9e":"L’envoyer dans votre DAW","documentation.905e63d9":"Tempo, tonalité et synchronisation automatique","documentation.05bb0a4d":"Graines et reproductibilité","documentation.e709e76f":"Préréglages","documentation.9e2759d7":"La bibliothèque de motifs","documentation.874a5339":"Vos prises, et verrouiller une piste de batterie","documentation.b7a3d0f4":"État de la session","documentation.26669547":"Raccourcis clavier","documentation.148f83d6":"La version autonome","documentation.0d1db92c":"Confidentialité et réseau","documentation.9091f25a":"Les questions qu’on pose vraiment","documentation.70252a52":"Signaler un bug","documentation.fef8e889":"Licence","documentation.1f0efc8f":"Freally MIDI Master est un plug-in <strong>CLAP</strong>. VST3 et AU en sont projetés plutôt qu’implémentés séparément, ce qui permet de le charger dans les hôtes qui ne parlent pas CLAP.","documentation.3960ec4c":"Hôte","documentation.041a5dec":"Format","documentation.bae7d5be":"État","documentation.2a47e9fb":"Ableton Live 12","documentation.20a69fa8":"VST3","documentation.c21b9338":"Se charge et génère","documentation.3e592955":"FL Studio","documentation.51df4626":"CLAP","documentation.54e5b246":"Reaper · Bitwig · Logic","documentation.7fa841a9":"CLAP / VST3 / AU","documentation.864e8b1c":"Pas encore testé","documentation.6141642e":"Sans DAW","documentation.1d10323c":"Autonome","documentation.fdd933a8":"Fonctionne dans sa propre fenêtre","documentation.7d883e08":"Le plug-in écrit des notes sur la piste où vous l’avez inséré <strong>et produit lui-même le son</strong> — la batterie via son kit, et chaque partie mélodique via son propre instrument. Vous n’avez rien à router pour l’entendre.","documentation.a8d36300":"<strong>Les téléchargements ouvrent à la 1.0.</strong> Il n’y a ni installateur, ni bêta, ni version de prévisualisation d’ici là — un plug-in qui fonctionne à moitié dans la session de quelqu’un est pire qu’un plug-in absent ; il sort donc quand la matrice de QA est au vert sur chaque hôte et chaque OS.","documentation.c5ebdb97":"Où se trouvent les formats, une fois la 1.0 sortie :","documentation.de8aa862":"OS","documentation.26d9c28d":"Windows","documentation.e59a23ba":"<code>%COMMONPROGRAMFILES%\\CLAP</code>","documentation.72e6c218":"<code>%COMMONPROGRAMFILES%\\VST3</code>","documentation.cd6fdcbf":"macOS","documentation.75bb9363":"<code>~/Library/Audio/Plug-Ins/CLAP</code>","documentation.9e8fc2e4":"<code>~/Library/Audio/Plug-Ins/VST3</code>","documentation.83ad8510":"Linux","documentation.f81f810e":"<code>~/.clap</code>","documentation.48df6728":"<code>~/.vst3</code>","documentation.fdbefea1":"<strong>Choisissez quelqu’un.</strong> Tapez un nom dans le champ du répertoire — artistes et genres confondus.","documentation.98f5460e":"<strong>Générez.</strong> Le motif est construit pour le tempo et la tonalité de votre projet.","documentation.e1f3b866":"<strong>Écoutez.</strong> Lancez la lecture dans votre DAW — les notes sont déjà sur la piste.","documentation.d9b0f0a8":"<strong>Relancez ou gardez.</strong> Chaque génération porte une graine que vous pouvez recopier.","documentation.f8d5c8c2":"La plupart des générateurs MIDI pensent en <em>genres</em>. « Trap » n’est pas « Metro Boomin », et aucun outil grand public n’a jamais entendu parler d’OsamaSon. Freally MIDI Master pense en <strong>artistes</strong> — chacun est un ensemble de paramètres de style écrits à la main qui décrivent la grammaire des roulements de charley, le comportement des glissés de 808, le swing, le registre et l’agencement des sections.","documentation.4f2277e8":"Vous les trouvez avec <strong>un seul champ à saisie semi-automatique</strong>. Commencez à taper et la liste se resserre au fil de la frappe — à travers le répertoire grand public, le répertoire underground, les alias et les fautes de frappe. Arrêtez-vous à mi-chemin et cliquez ailleurs : il prend la meilleure correspondance, si bien que vous ne pouvez jamais vous retrouver sans rien de choisi. Appuyez plutôt sur la flèche et il vous montre tout.","documentation.a84eb15c":"Le même champ liste <strong>artistes et genres ensemble</strong>, chaque ligne indiquant ce qu’elle est, si bien que vous n’avez jamais à savoir d’avance si « UK Drill » est une personne ou un style. Choisissez-en un et ses détails apparaissent juste en dessous — l’époque, les genres dans lesquels il évolue, la <strong>plage de tempo</strong> et la tonalité vers lesquelles il penche, ses humeurs par leur nom, et <strong>quelles parties il écrit et lesquelles non</strong> — <strong>avant</strong> que vous n’appuyiez sur Générer. <strong>Les genres sont un filtre de navigation, pas l’unité de génération</strong> — même si un genre est lui-même un vrai modèle de style et génère à part entière.","documentation.2e81e526":"Cette dernière ligne compte plus qu’il n’y paraît. Un artiste qui n’écrit pas de contre-mélodies répond à cet onglet par du <em>silence</em>, à juste titre — il n’en écrit pas, donc rien n’est inventé à sa place. Avant que le panneau ne le dise, le seul moyen de le savoir était d’appuyer sur Générer et de fixer un piano roll vide.","documentation.c67e0e46":"Les noms d’artistes sont <strong>uniquement des références descriptives de style</strong>. Rien dans le jeu de données n’est du MIDI copié, de l’audio échantillonné ou la transcription du disque de quiconque.","documentation.b0e455fd":"Un artiste n’est pas un seul son. À côté de l’artiste se trouve une <strong>humeur</strong> — pour le trap, <em>dark</em>, <em>bounce</em>, <em>melodic</em> et <em>minimal</em> ; pour le boom bap, <em>dusty</em>, <em>jazzy</em> et <em>hard</em> ; pour le phonk, <em>cowbell</em>, <em>memphis</em> et <em>brazilian</em>. Laissez-la sur <strong>Indifférent</strong> et chaque pression parcourt l’éventail de cet artiste ; fixez-en une et restez-y.","documentation.c4de4112":"Une humeur, c’est <strong>le même auteur qui écrit un autre type de disque</strong>, et c’est ainsi que les producteurs décrivent leur propre catalogue. Elle s’applique avant que le moindre générateur ne tourne, donc chaque partie la respecte — il est impossible que la batterie soit dans une humeur et la mélodie dans une autre.","documentation.4e322996":"<strong>Un artiste ne propose que les humeurs qu’il pratique réellement.</strong> Les humeurs se transmettent le long de la même lignée que tout le reste, donc il n’existe aucun chemin par lequel l’humeur d’un artiste pourrait être proposée sur un autre. Demandez-en une qu’un style n’a pas et il le dit nommément plutôt que de générer discrètement autre chose.","documentation.8b53323c":"<strong>Flux original</strong> se trouve en haut du panneau gauche, au-dessus de tout. Partez de n’importe quel artiste ou genre, ajustez la plage de tempo, le swing, la densité de charley, la densité mélodique et les gammes, puis enregistrez-le sous votre propre nom. Il apparaît dans le répertoire marqué <strong>À vous</strong> et génère, verrouille, relance et exporte exactement comme un artiste livré — parce que c’est le même genre de chose, dans le même format.","documentation.63fa26a1":"Il <strong>hérite de tout ce que vous n’avez pas modifié</strong>, y compris les améliorations que l’artiste dont il est issu recevra dans une version ultérieure. Un nouveau style s’ouvre initialisé à partir du beat à l’écran plutôt que d’un formulaire vierge.","documentation.22b5f3cc":"Étoilez au fur et à mesure les prises qui vous plaisent. À trente prises gardées, <strong>Entraîner</strong> ajuste un style sur elles — combien d’attaques par mesure, quel registre, quelle forme a prise la ligne — et réécrit ces plages comme un modèle de style ordinaire. Vos propres fichiers <code>.mid</code> peuvent aussi servir de matériau d’entraînement.","documentation.421a3d31":"<strong>« Entraîné » veut dire ajusté, et il n’y a aucun apprentissage automatique là-dedans.</strong> Rien n’est appris de la musique de quiconque, rien ne quitte votre machine, et un ajustement qui ne ferait que se répéter est refusé avec une raison plutôt qu’enregistré. Le plancher de trente existe pour qu’un style encode votre goût plutôt que l’avis d’une seule graine.","documentation.70a577ec":"<strong>Vos échantillons ne sont copiés que si vous le demandez.</strong> Un style peut garder les one-shots que vous avez assignés, pour qu’ils jouent encore après que vous avez déplacé ou supprimé les originaux. Cela signifie une seconde copie sur votre disque ; l’éditeur vous indique donc combien de fichiers et combien de mégaoctets avant que quoi que ce soit ne se passe — et la case est décochée. Enregistrer un style ne copie rien de lui-même.","documentation.5d689d19":"Huit pads s’alignent en haut de la scène, au-dessus du piano roll. Chacun est une piste de batterie : son nom, ce qui s’y trouve en ce moment, et un point qui indique si vous l’entendez — <strong>vert pour audible, rouge pour coupé</strong>.","documentation.86cb89b2":"Appuyez sur un pad pour le couper ou le réactiver. Appuyez sur <strong>Lecture</strong> en haut au centre pour entendre ce seul son. <strong>Faites glisser un échantillon dessus</strong> depuis le navigateur pour y mettre votre propre one-shot, ou double-cliquez pour choisir un fichier. Le bouton aléatoire relance ce pad depuis le dossier que vous parcourez, et le ✕ remet le son intégré.","documentation.aaa1fd33":"Le <strong>nom de piste de chaque pad est lui-même un sélecteur</strong> — remplacez n’importe lequel des huit par l’une des trente-sept pistes du plug-in. Deux pads peuvent partager une piste, pour superposer une caisse claire ; un troisième est refusé. Votre disposition est mémorisée <strong>par artiste</strong>, si bien que revenir à un style que vous avez construit restaure les pads exactement comme vous les avez laissés, avec les échantillons que vous aviez assignés.","documentation.d25c3d2f":"<strong>Il s’ouvre sur Catégories</strong> — une ligne par emplacement, chacune indiquant ce qu’elle contient, et vous y entrez. Instruments et les quatre Extensions d’usine sont les étagères de la bibliothèque intégrée ; Packs de batterie contient les onze kits livrés et leurs 407 one-shots ; Packs d’usine contient les 5 085 boucles MIDI, par pack. En dessous se trouvent <strong>+ Ajouter un dossier</strong> et les dossiers que vous avez ajoutés, par nom.","documentation.40db79d3":"<strong>Le nombre sur une ligne correspond à toute l’étagère</strong>, pas à ce qui a survécu aux filtres ; il ne bouge donc pas quand vous appuyez sur une pastille. Les lignes sont classées par ordre alphabétique dans celle des dix-huit langues que vous utilisez. Un dossier dont le disque est débranché garde sa place et est marqué <em>Indisponible</em> en toutes lettres plutôt que par une seule couleur, et il reste supprimable — un producteur qui a débranché son disque d’échantillons n’a pas quitté la bibliothèque.","documentation.21e024db":"À l’intérieur d’un emplacement, les flèches au-dessus de la liste parcourent les dossiers et le fil d’Ariane saute directement à un niveau. Votre bibliothèque revient la prochaine fois que vous ouvrez l’application, avec ou sans projet.","documentation.6324e27a":"<strong>Les touches fléchées le parcourent.</strong> <kbd>↑</kbd> et <kbd>↓</kbd> passent d’une ligne à l’autre. Sur un dossier, <kbd>→</kbd> l’ouvre et <kbd>←</kbd> le ferme — et sur un dossier déjà fermé, <kbd>←</kbd> ferme la branche qui le contient, ce qui permet de remonter. Sur un <em>fichier</em>, ces deux mêmes touches le lisent <strong>à l’endroit et à l’envers</strong>. L’écoute ne démarre ni n’arrête jamais le transport.","documentation.33491a5d":"<strong>Étoilez n’importe quoi</strong> — un échantillon, un one-shot ou un fichier MIDI. L’étoile se trouve à gauche du nom : un simple contour tant que vous n’avez pas appuyé, puis jaune plein. Les fichiers étoilés se rassemblent dans une liste sous l’arborescence, et cliquer sur l’un d’eux ouvre chaque dossier entre la racine et ce fichier pour le révéler. Si son dossier ne fait plus partie de ceux que vous avez ajoutés, il ouvre plutôt l’emplacement du fichier dans l’<strong>Explorateur Windows ou le Finder</strong> — un favori reste donc accessible, où que votre bibliothèque ait déménagé. Retirer l’étoile l’oublie.","documentation.0a36b11f":"Le navigateur peut occuper <strong>tout le panneau</strong> quand vous avez besoin de profondeur, puis le rendre. Audio et MIDI sont séparés exprès : un <code>.mid</code> n’a pas de forme d’onde à dessiner et ne peut pas être déposé sur un pad de batterie, et le pad le refuse avant que vous ne le lâchiez plutôt que d’échouer ensuite.","documentation.5811086b":"<strong>Il tient une vraie bibliothèque.</strong> Un dossier de deux mille fichiers s’ouvre aussi vite qu’un dossier de quatre, parce que seules les lignes réellement visibles sont dessinées — faites défiler et le reste arrive à mesure que vous l’atteignez. <strong>Tapez dans le champ de filtre</strong> et l’arborescence se réduit à ce qui correspond, en gardant les dossiers qui y mènent ; tapez le nom d’un dossier et vous obtenez tout ce qu’il contient. La ligne sous le champ indique <em>quels dossiers ont été parcourus</em>, et elle dit vrai : le plug-in lit un dossier à la fois, donc le filtre atteint ceux que vous avez ouverts et pas plus loin. Un champ qui laisserait entendre le contraire mentirait sur ce qu’il a regardé.","documentation.0c96cd67":"<strong>Débranchez le disque où se trouve un dossier de la bibliothèque et son onglet le dit</strong>, avec un <em>Vérifier à nouveau</em> à côté. Le dossier n’est pas retiré de votre bibliothèque — rebranchez le disque, appuyez dessus, et l’arborescence est là. Auparavant, un tel dossier refusait simplement de s’ouvrir, ce qui ressemble exactement à un dossier vide.","documentation.3de3cadc":"<strong>Écoutez-le d’abord.</strong> Sélectionnez un <code>.mid</code> et le panneau liste ce qu’il contient ; appuyez sur <strong>Lecture</strong> et il sonne — via un instrument intégré tout simple plutôt que l’artiste que vous avez sélectionné à ce moment-là, si bien que le même fichier sonnera pareil demain. Les pistes de batterie passent comme des frappes plutôt que comme des hauteurs, car le numéro de note d’une piste de batterie indique quel pad se déclenche, pas sa hauteur. L’écoute est construite à la première pression, pas quand vous cliquez sur le fichier, donc parcourir un dossier de boucles avec <kbd>↓</kbd> ne coûte rien. Elle ne touche jamais au transport de votre projet.","documentation.9acfff56":"Faites glisser un <code>.mid</code> du navigateur sur un <strong>générateur</strong> et ses notes y atterrissent. Déposez-le plutôt sur l’onglet <strong>Morceau</strong> et le fichier entier arrive sous forme d’arrangement — les sections en haut, les parties sur le côté — et cliquer sur n’importe quelle case ouvre ce clip dans son générateur, exactement comme quand on explore un morceau généré. Rien de ce que vous avez déjà n’est écrasé tant que vous ne choisissez pas une case.","documentation.7b266d93":"Un fichier en couches est <strong>séparé en basse, mélodie, contre-mélodie, accords et batterie</strong>, et chaque partie dit <strong>pourquoi</strong> elle a été routée là — « sur le canal de batterie GM », « accords — les notes se chevauchent », « voix la plus grave », « d’après le nom du fichier ». Une mauvaise supposition se corrige d’un clic plutôt que de se découvrir deux mesures plus loin.","documentation.d544549e":"<strong>Nommez vos fichiers et il vous écoutera.</strong> Un fichier appelé <code>…-Bass.mid</code> ou <code>…Drums.mid</code> est pris au mot, parce que c’est vous qui dites ce qu’il est plutôt que le plug-in qui devine. C’est plus important qu’il n’y paraît : la note MIDI d’une 808 indique <em>quelle touche déclenche l’échantillon</em>, pas à quel point elle sonne grave, si bien qu’une ligne de basse se trouve couramment dans le registre de la mélodie et qu’aucune mesure ne peut la distinguer d’un lead lent. La seule chose qui le peut, c’est le nom que vous lui avez donné.","documentation.02646e58":"Les clips importés <strong>adoptent le tempo de votre session</strong>. La plupart des fichiers MIDI exportés ne portent aucun tempo — le nombre dans le nom du fichier n’est pas dans les données — et le plug-in ne revendiquera pas un tempo qu’il n’a pas lu.","documentation.2528b54c":"<strong>Cinq générateurs de parties, plus le mode Morceau.</strong> Le mode Morceau n’est pas un sixième générateur — il pose un arrangement et remplit les cinq autres.","documentation.fe06eb64":"Onglet","documentation.f6222ac9":"Ce qu’il produit","documentation.764cb087":"<strong>Batterie</strong>","documentation.d18ca618":"Grosse caisse, caisse claire et off-snare, claquement, charleys fermé et ouvert avec leur grammaire de roulements, ride, crash, tom, cercle, claquement de doigts, percussion, shaker, tambourin, cloche à vache et bloc de bois — plus la sub glissante. Ceux qu’un artiste utilise font partie de cet artiste.","documentation.f973941a":"<strong>Mélodie</strong>","documentation.86e5726d":"Structures de phrase — boucle de riff, question/réponse, appel/réponse, longue arche — avec une préférence pour les notes de l’accord sur les temps forts et des procédés propres à chaque genre","documentation.4e420883":"<strong>Contre-mélodie</strong>","documentation.c81554ab":"Écho à l’octave, écho de cloche, arpège, lick en réponse et nappe tenue, placés dans les vides de la mélodie","documentation.3562e4d3":"<strong>Ligne de basse</strong>","documentation.6763aa65":"Le bas du spectre, calé sur le comportement de la sub de la batterie","documentation.677c857e":"<strong>Accords</strong>","documentation.d7eb09d9":"Des progressions dans la tonalité et la gamme de la session","documentation.7c237ecf":"<strong>Morceau</strong>","documentation.6d9aaa02":"Un arrangement qui remplit les cinq ci-dessus — un mode, pas un générateur","documentation.ecfc86d6":"<strong>Les cinq génèrent, et les cinq sont modifiables.</strong> La batterie a une grille de pads ; mélodie, contre-mélodie, ligne de basse et accords ont un piano roll. Un style dont la 808 <em>est</em> la ligne de basse le dit plutôt que de la doubler par un second bas du spectre.","documentation.5acc0069":"Les hauteurs sont choisies comme <strong>degrés de la gamme</strong> et seulement ensuite converties en notes MIDI, si bien que rester dans la tonalité est structurel plutôt que filtré après coup.","documentation.eb60a3b0":"Appuyez sur Générer dans l’onglet <strong>Morceau</strong> et vous obtenez un arrangement entier : une des formes de morceau propres à l’artiste, un clip par partie et par section, et les transitions qui en font un disque — le temps ou deux de silence avant que le refrain ne tombe, un changement de cap dans la seconde moitié, une outro qui s’éteint.","documentation.967c5bf5":"<strong>Une section joue un clip en boucle.</strong> Un couplet de seize mesures est une boucle de quatre mesures jouée quatre fois, ce que dessine la vue arrangement de toute DAW. Les sections du même type partagent un clip, parce que le couplet 1 et le couplet 2 sont le même beat — le changement de cap existe justement parce que c’est la règle.","documentation.fb2dbad1":"Ce que vous pouvez faire","documentation.0c81abc8":"Comment","documentation.b78ea20d":"Redimensionner, cloner, supprimer, copier/couper/coller des clips","documentation.f3887844":"Faites glisser l’un ou l’autre bord, double-cliquez sur un en-tête de section, et les raccourcis habituels","documentation.b4f2f858":"Relancer une section","documentation.462f801c":"<kbd>R</kbd>, ou le dé sur l’en-tête de section. Les clips verrouillés ne sont pas touchés","documentation.6ae2c0bb":"Verrouiller un clip, une rangée ou une section entière","documentation.d51e6c21":"Le cadenas sur la case, la rangée de la partie ou l’en-tête de section","documentation.91c16f4e":"Écouter une seule case","documentation.6bb5c318":"Le casque sur le clip. La vue l’indique tant que cela dure","documentation.7f68250f":"Ouvrir un clip dans son éditeur","documentation.9b3b8f91":"Double-cliquez dessus. Vos modifications sont réécrites dans l’arrangement","documentation.85574b57":"Boucler une section, couper ou isoler une partie","documentation.d174c5c9":"L’icône de répétition sur l’en-tête ; le haut-parleur et <kbd>S</kbd> sur la rangée","documentation.22fee5c2":"Choisir laquelle des formes de l’artiste construire","documentation.9b4ae385":"Le sélecteur dans la rangée de structure. Sans choix, c’est l’artiste qui décide","documentation.f3e4fadb":"Exporter","documentation.4ec1e842":"Un seul <code>.mid</code> multipiste, ou un fichier par partie dans un dossier","documentation.0969199e":"<strong>Couper et isoler sont des commandes d’écoute.</strong> Elles changent ce que vous entendez, jamais le morceau ni le fichier exporté — la même distinction que fait la coupure audio par piste. En basculer une pendant la lecture laisse le repère là où il est, pour vérifier une transition sans perdre votre place dans le disque.","documentation.24a78f85":"<strong>Le transport joue l’onglet que vous regardez.</strong> Il n’y a qu’un seul programme de lecture : l’onglet Morceau y place l’arrangement entier, et revenir à un onglet de générateur y remet le clip de cet onglet. Le repère que vous voyez est donc toujours celui qui bouge.","documentation.dd323d51":"<strong>Une relance reste à l’intérieur du disque.</strong> Elle garde le mode dans lequel le morceau a été généré, le tempo et la tonalité auxquels il l’a été, et tout swing que vous avez fixé — et elle laisse toutes les autres sections, y compris un clone de celle que vous avez relancée, exactement telles qu’elles étaient.","documentation.920e6fd6":"<strong>Les stems sortent en MIDI ou en audio, par partie ou par piste.</strong> La moitié audio était autrefois impossible, et la raison a été mesurée plutôt que supposée : le kit livré n’avait aucune voix pour les quatre parties mélodiques, donc les rendre aurait écrit quatre <code>.wav</code> silencieux en les appelant des stems. Le kit couvre désormais chaque piste générée, et vos propres one-shots couvrent le reste. Un <em>morceau</em> entier écrit toujours un <code>.mid</code> par partie — rendre des minutes d’audio demande une progression que vous pouvez suivre et un bouton d’annulation sur lequel appuyer, ce qui est un autre travail que de rendre une boucle de quatre mesures.","documentation.edc824f0":"<strong>Vous pouvez faire glisser une partie directement sur une piste de DAW.</strong> Chaque partie générée a une poignée MIDI et une poignée Audio dans le panneau droit ; activez <strong>Par piste</strong> et la partie de batterie devient une poignée par piste, pour que les charleys puissent sortir seuls. L’arrangement entier se fait glisser aussi, en MIDI. Les fichiers arrivent nommés <code>trap - Snare - 140 BPM - C# Minor</code>, et les notes du clip suivent le curseur pour que vous voyiez ce que vous avez attrapé. <strong>Windows uniquement pour l’instant</strong> — un glisser HTML5 dans la webview d’un plug-in n’est pas un glisser de fichier du système d’exploitation, donc chaque plateforme a besoin de sa propre source de glisser native. macOS et Linux gardent Exporter tant que la leur n’est pas écrite, et n’affichent aucune poignée plutôt qu’une poignée qui ne dépose rien.","documentation.f6b5ea7d":"<strong>Où se trouve un fichier déposé.</strong> Le glisser écrit le fichier dans votre dossier temporaire et transmet le chemin à votre DAW. Un <code>.mid</code> déposé est copié dans votre projet par toutes les DAW, donc ceux-là sont nettoyés au bout d’une semaine ; un <code>.wav</code> déposé est <em>référencé</em> par son chemin, donc ceux-là ne sont jamais supprimés — utilisez la fonction Collect All and Save de votre DAW pour en garder un pour de bon.","documentation.ac9b6565":"<strong>Il produit le son en plus des notes.</strong> Un synthétiseur polyphonique doté d’une bibliothèque d’usine de 225 instruments répartis sur 69 genres, et chacun des quatre générateurs mélodiques joue le sien — assigner un son différent à Mélodie, Contre-mélodie, Ligne de basse et Accords vous donne donc quatre voix à la fois, pas une seule partagée entre elles.","documentation.e8595ab4":"Rien ici n’est une bibliothèque d’échantillons. Chaque son est généré à partir d’une petite adresse — un instrument, un genre, une variation, une articulation et un timbre — si bien que toute la bibliothèque tient en une poignée d’entiers dans votre fichier de projet plutôt qu’en gigaoctets sur votre disque. Treize moteurs de synthèse se trouvent derrière : un violon est un modèle de corde frottée et un Rhodes un modèle physique de piano, c’est pourquoi leurs commandes se comportent différemment de celles d’une nappe.","documentation.d72a5e39":"<strong>Chaque adresse est un son différent.</strong> Les vingt-quatre variations d’un instrument dans un genre parcourent l’éventail propre à cet instrument — combien de temps une lame résonne, avec quelle force frappe un marteau, où une corde est pincée — plutôt que de lancer les dés vingt-quatre fois, et le genre atteint le modèle lui-même plutôt qu’un filtre placé après lui : une 808 trap résonne et glisse là où une grosse caisse house est sèche, et un piano jazz a des marteaux plus doux qu’un piano metal. Les 2 729 088 sont tous vérifiés, en les rendant.","documentation.72640dda":"L’onglet SYNTH","documentation.4a4148dd":"Le filtre, les deux enveloppes, les effets et les commandes générales du générateur que vous façonnez. Les quatre boutons en haut choisissent lequel — l’onglet SYNTH est le seul onglet qui ne soit pas lui-même une partie, il doit donc demander.","documentation.9e3449fc":"À l’intérieur d’une étagère d’instruments","documentation.dd09491c":"Ouvrez <strong>Instruments</strong> ou l’une des quatre <strong>Extensions d’usine</strong> et vous parcourez cette étagère par genre et par famille — les genres sont classés par ordre alphabétique et la liste s’ouvre sur <strong>Trap</strong>. Elle est paginée : un genre sans filtre de famille, c’est 5 400 lignes. <strong>L’étagère réduit la liste</strong> : ouvrir Extension d’usine 2 puis Claviers affiche les instruments Claviers de ce pack, et non tous les instruments Claviers du produit.","documentation.6034b304":"<strong>Cliquer sur une ligne la joue, et rien de plus.</strong> Le clip que vous entendez est l’instrument sur la note où il sonne le plus comme lui-même, dessiné sous forme d’onde dans le lecteur d’aperçu sous le navigateur, avec une tête de lecture et un temps qui défile. <kbd>&uarr;</kbd> et <kbd>&darr;</kbd> parcourent la liste et jouent ce sur quoi elles tombent, pour que vous puissiez parcourir une famille à l’oreille sans toucher la souris.","documentation.a1eb5eff":"<strong>Le mettre sur un générateur est une pression distincte</strong> — le bouton <em>Utiliser dans…</em> sous la liste, ou <kbd>Ctrl</kbd>/<kbd>&#8984;</kbd> + <kbd>&#9654;</kbd>, qui atterrissent tous deux sur l’onglet que vous regardez. Choisir un instrument efface la réverbération, la saturation, le gain et l’enveloppe que portait le <em>précédent</em>, pour que ce que joue le générateur soit ce que jouait l’aperçu. Vous ne devriez pas avoir à toucher un bouton pour obtenir le son que vous venez d’entendre.","documentation.7c97bb07":"<strong>La batterie va à la batterie et les instruments vont aux générateurs.</strong> Un instrument d’usine est un patch de synthé et une piste de batterie joue des one-shots, donc le raccourci refuse l’association plutôt que d’en faire quelque chose de surprenant. <kbd>Ctrl</kbd> + <kbd>&#9664;</kbd> joue un échantillon à l’envers dans l’aperçu et ne le mettra pas ainsi dans un générateur — inverser une note est le travail du piano roll.","documentation.7f76c6b2":"Le clavier","documentation.2d0fa842":"Affichez-le ou masquez-le depuis n’importe quel onglet. Cliquez et faites glisser sur les touches — la hauteur à laquelle vous appuyez sur la touche règle la vélocité — ou utilisez les touches de l’ordinateur. Celles-ci se mettent en retrait quand un champ de texte a le focus, pour que chercher un artiste ne vous joue pas de notes.","documentation.7a1b9f14":"Changer l’octave ou la plage envoie un All Notes Off, pour qu’une note tenue ne puisse pas rester bloquée parce que les touches sous elle ont changé.","documentation.30f9d8d3":"Le jouer depuis du matériel","documentation.ee7a9278":"<strong>Paramètres → Entrée MIDI.</strong> Un filtre de canal (ou tous les canaux, le réglage par défaut), une transposition en demi-tons, un décalage d’octave qui s’y ajoute, la plage de pitch bend et une courbe de vélocité — en dessous du milieu, un toucher léger sort plus fort ; au-dessus, il faut appuyer plus fort.","documentation.4d68e35d":"Une note transposée au-delà des extrémités du clavier est <strong>abandonnée, pas repliée</strong>. Une note repliée est une fausse note, et rien à l’écran ne vous dirait que c’est arrivé.","documentation.874b0424":"<strong>Les notes que vous jouez sont à vous.</strong> Elles ne sont jamais analysées, ne deviennent jamais partie d’un style et n’entraînent jamais rien — la même règle que pour un fichier MIDI que vous importez.","documentation.004f6eb1":"Les boutons de la page du générateur","documentation.a9a17e79":"Réverbération, delay, saturation, volume et panoramique pour la partie que vous regardez, avec les mêmes valeurs dans l’éditeur par partie du panneau droit. C’est un seul jeu de commandes affiché deux fois, pas deux qu’il faudrait garder synchronisés.","documentation.aac58205":"Le volume, le panoramique et l’enveloppe appartiennent à la <em>piste</em>, ils fonctionnent donc que la partie joue un instrument d’usine ou un one-shot à vous. Réverbération, delay et saturation s’appliquent aux propres effets de l’instrument, ils n’apparaissent donc que lorsqu’un son d’usine est chargé — sur votre propre échantillon, ils n’auraient rien à atteindre, et une commande qui ne change rien est pire qu’une commande absente.","documentation.7eff58e8":"Enregistrer un son","documentation.bd3b5639":"Façonnez un instrument, puis enregistrez-le sous une catégorie et un nom de votre choix. Les sons sont listés sous ces catégories dans l’onglet SYNTH.","documentation.857fd301":"<strong>Un son n’est pas un préréglage.</strong> Un <em>préréglage</em> dans le panneau droit est une session enregistrée — un artiste, une graine et d’éventuelles valeurs fixées. Un <em>son</em> est un instrument. Ils sont rangés à des endroits séparés et n’apparaissent jamais dans une même liste.","documentation.a64f42d4":"PACK — le rack d’échantillons","documentation.75928332":"Choisissez un genre et un instrument, indiquez combien, puis appuyez sur Générer. Jusqu’à 25 one-shots sont rendus hors ligne, chacun rogné et doté de fondus pour ne pas cliquer, et tout ce qui sort quasi silencieux est jeté avant d’atteindre le rack.","documentation.30f4f34e":"Jouez n’importe quel emplacement pour l’entendre. <strong>Échanger</strong> relance un emplacement sans toucher aux autres, <strong>×</strong> en retire un, et Exporter écrit ce qui reste — avec une normalisation en option. Le rendu se fait en arrière-plan avec une barre de progression et un bouton Annuler, pour que la fenêtre de votre DAW ne cesse jamais de se dessiner.","documentation.3fb1265f":"<strong>Paramètres → Entrée MIDI</strong>, sous les réglages d’entrée — les deux concernent ce qui passe entre ce plug-in et votre propre matériel. WAV ou AIFF, 16 bits, 24 bits ou 32 bits flottant, à 44,1, 48, 88,2, 96, 176,4 ou 192 kHz.","documentation.0682be26":"Choix","documentation.769bb19e":"Quand","documentation.0a30f217":"WAV 16 bits","documentation.e77855ff":"Le réglage par défaut, et ce que ce plug-in a toujours écrit.","documentation.7d81c5bd":"WAV 24 bits","documentation.6ce283a3":"Ce que la plupart des producteurs attendent d’un bounce. Six dB de plage utile en plus.","documentation.a40ce484":"WAV 32 bits flottant","documentation.34ccd0a3":"Garde tout ce qui a dépassé la pleine échelle, pour qu’un bounce trop chaud puisse encore être ramené.","documentation.7f9266a3":"AIFF 16 ou 24 bits","documentation.2c807357":"Pour un flux de travail qui le demande. Entiers uniquement — l’AIFF n’a pas de forme flottante ici.","documentation.30e94467":"<strong>Une boucle que vous faites glisser dans votre DAW est toujours un WAV 16 bits, quel que soit ce réglage.</strong> Une boucle glissée doit porter son propre tempo pour atterrir calée à la bonne vitesse plutôt qu’à celle de votre projet, et seul un WAV peut contenir cette information. Ce réglage concerne les fichiers que vous <em>enregistrez</em>, dont vous avez choisi la destination.","documentation.e667e4fb":"<strong>Trois chemins, et celui qu’il vous faut dépend de ce que vous faites.</strong> Le plug-in joue sur sa propre piste, fait glisser des fichiers vers l’extérieur, ou les exporte dans un dossier.","documentation.3ac408e8":"1. Simplement le jouer","documentation.9eccb298":"Le plug-in émet du MIDI sur la piste où il se trouve, et produit aussi le son lui-même — la batterie via son kit et chaque partie mélodique via son propre instrument. Lancez la lecture dans votre DAW et vous entendez le beat sans rien router.","documentation.25c81dca":"Si vous préférez que votre propre instrument joue les notes, routez la sortie MIDI du plug-in vers lui comme votre hôte le permet, et coupez le son propre de la partie en ne lui assignant aucun instrument.","documentation.a651299f":"2. Faire glisser un clip","documentation.ba47208c":"Attrapez une pastille de partie et faites-la glisser sur une piste. Vous obtenez un <code>.mid</code> par défaut, ou de l’audio si vous basculez la pastille. Faire glisser l’arrangement entier donne un fichier par partie.","documentation.74b1c304":"<strong>Le glisser n’existe que sous Windows pour l’instant.</strong> Sous macOS et Linux, les pastilles ne le proposent pas, parce qu’une commande qui ne peut pas fonctionner est pire qu’une commande absente. Utilisez plutôt Exporter — il produit les mêmes fichiers.","documentation.3df20937":"Une boucle <em>audio</em> glissée porte son propre tempo, elle atterrit donc calée à la vitesse à laquelle elle a été faite plutôt qu’à celle de votre projet. C’est une particularité du WAV, c’est pourquoi une boucle glissée est toujours un WAV 16 bits, quel que soit le format d’export choisi.","documentation.ff72e267":"3. Exporter dans un dossier","documentation.5d91da4a":"Choisissez un dossier et obtenez un fichier par partie — en MIDI, ou en audio dans le format que vous avez choisi. C’est le chemin qui fonctionne sur toutes les plateformes, et celui à utiliser pour un arrangement entier.","documentation.29940c77":"Par hôte","documentation.9f733253":"Format à installer","documentation.dc3decbb":"Détails","documentation.e6225dc8":"Live ne lit pas le CLAP. Déposez un <code>.mid</code> sur une piste MIDI ; à partir d’un fichier multipiste, Live crée un clip par piste.","documentation.d976ad22":"FL Studio 21.2+","documentation.c0fb74c6":"CLAP (ou VST3)","documentation.c7b038df":"Lit le CLAP nativement. Un <code>.mid</code> multipiste atterrit dans la playlist sous forme de canaux séparés.","documentation.d1100b6d":"Reaper","documentation.fc15247e":"CLAP ou VST3","documentation.ce4fa0e2":"Accepte les deux. Reaper demande comment importer un fichier multipiste plutôt que de deviner.","documentation.82653a52":"Bitwig","documentation.600bbc6d":"Le CLAP est son format natif.","documentation.fd6889aa":"Logic Pro","documentation.acdf4173":"AU","documentation.a74dbbef":"macOS uniquement. Logic ne lit ni le CLAP ni le VST3.","documentation.1f04dbe6":"<strong>Deux de ces lignes sont vérifiées et trois ne le sont pas.</strong> Ableton Live 12 et FL Studio ont été chargés et ont généré ; Reaper, Bitwig et Logic n’ont pas encore été ouverts, donc leurs lignes décrivent ce que chaque hôte documente plutôt que ce que quelqu’un a vu se produire. Quand l’un d’eux sera testé, c’est dans <code>docs/daw-matrix.md</code> que le résultat ira.","documentation.c076a592":"Le plug-in lit le tempo et la métrique de l’hôte à chaque bloc. Un trap écrit à 140 sort à <strong>92 dans un projet à 92&nbsp;BPM</strong> — parce qu’un clip généré au tempo de l’artiste ne correspond pas au morceau que vous avez demandé.","documentation.ab86fb82":"Ordre de priorité","documentation.15955a81":"<strong>Ce que vous fixez l’emporte.</strong> Fixez un tempo dans les pastilles de session et il prime sur tout.","documentation.32319078":"<strong>Ensuite l’hôte.</strong> Avec la synchronisation automatique activée, le tempo de la DAW est utilisé.","documentation.5e24a1af":"<strong>Ensuite l’artiste.</strong> Avec la synchronisation automatique désactivée, le tempo écrit pour le modèle s’applique.","documentation.1125e7e4":"<strong>Un tempo fixé reste dans la plage où l’artiste travaille.</strong> Le champ BPM s’arrête à la plage affichée dans le panneau — faites glisser ou tapez au-delà et il se cale sur la limite — et passer à un artiste qui ne peut pas atteindre votre tempo fixé le ramène à son tempo le plus proche plutôt que de générer quelque chose qu’il ne joue jamais. La saisie n’est corrigée que lorsque vous quittez le champ, donc le <kbd>1</kbd> tapé en route vers <kbd>140</kbd> n’est pas réécrit sous votre curseur. <strong>L’hôte n’y est jamais soumis :</strong> le tempo d’un projet appartient au projet.","documentation.f2eb4b94":"<strong>La pastille de gamme propose les gammes dans lesquelles écrit cet artiste.</strong> Un mode est ce qui porte son caractère, donc une gamme choisie sur un artiste est rendue au modèle quand vous passez à un autre qui ne l’utilise pas. La pastille de tonalité n’est volontairement pas restreinte — une tonalité, c’est une transposition, la même musique à une autre hauteur.","documentation.638c602e":"La synchronisation automatique est un réglage de session enregistré avec votre projet — trois états, pas deux. La désactiver est le moyen d’atteindre le tempo écrit pour l’artiste depuis un projet en cours.","documentation.ac4e2b0c":"Chaque génération a une <strong>graine</strong>. La même graine, le même artiste et la même session produisent toujours un motif identique à l’octet près — sur n’importe quelle machine, n’importe quel jour. Copiez la graine depuis la pastille, recollez-la, et le beat revient.","documentation.f8ac4ea5":"Laissez le champ de graine vide pour en obtenir une nouvelle à chaque fois ; la pastille affiche alors la graine réellement utilisée, pour que vous puissiez copier une génération qui vous a plu même sans avoir jamais tapé de nombre.","documentation.c902e125":"Le déterminisme est imposé par la suite de tests, pas seulement voulu — c’est aussi pourquoi un projet enregistré peut restaurer un beat sans stocker une seule note.","documentation.5d19dc54":"Un préréglage est une session nommée — artiste, graine, mesures et valeurs fixées. Les préréglages d’usine sont compilés dans le binaire ; les vôtres sont écrits dans le dossier de données par utilisateur de la plateforme, ils survivent donc à n’importe quel projet.","documentation.6c29a0d2":"<strong>Aucun préréglage d’usine ne fixe de tempo.</strong> Fixer une valeur est une instruction de l’utilisateur, et un fichier livré n’est pas l’utilisateur — un préréglage d’usine qui fixerait un tempo écraserait celui de votre DAW dès son chargement.","documentation.4df575be":"Nommez un motif qui vous plaît et il sera là la prochaine fois — dans n’importe quel morceau, dans n’importe quelle DAW. Chacun est son propre fichier JSON dans le dossier de données par utilisateur de la plateforme ; un enregistrement raté coûte donc une boucle plutôt que l’étagère entière, et vous pouvez les sauvegarder, les synchroniser ou en donner un à quelqu’un en copiant un fichier.","documentation.6053a251":"<strong>Un motif enregistré, ce sont des notes, pas du son.</strong> Le kit n’est volontairement pas stocké, ce qui rend « utilisez-le avec les sons que vous voulez » vrai plutôt que simplement promis : chargez le motif, changez de kit, et la même interprétation joue à travers d’autres échantillons. C’est aussi ainsi qu’un motif survit à un plantage — un plug-in vit dans le processus de quelqu’un d’autre et meurt avec lui.","documentation.c6f3d453":"Ce n’est ni un préréglage ni le projet. Un <em>préréglage</em> est un point de départ et ne stocke aucune note, parce que le moteur les régénère ; le <em>projet</em> se souvient de ce morceau. Un motif enregistré, c’est la prise que vous avez gardée.","documentation.ca18c184":"Chaque génération de la session est gardée, depuis la première, comptée séparément pour chaque générateur. <kbd>&#9664;</kbd> et <kbd>&#9654;</kbd> les parcourent, et revenir en arrière ramène toute la configuration : l’artiste, l’humeur, la graine, les mesures et les valeurs fixées — pas seulement le nombre.","documentation.8dc74fe7":"L’affichage montre le tempo et la tonalité <strong>réellement utilisés</strong>, ce qui n’est pas toujours ce que vous aviez fixé : un beat fait pendant que votre DAW était à 92 a été fait à 92, et le tempo change les notes.","documentation.d7bad06c":"<strong>Et il survit à la session.</strong> Cliquez sur le compteur de prises — le « 3 / 40 » entre les flèches — et chaque génération que vous avez jamais faite est là, groupée par artiste, chaque ligne indiquant sa durée, son tempo et quand vous l’avez faite. Choisissez-en une et elle revient. Les flèches répondent à « reculer d’une prise » ; ceci est pour le beat de mardi soir dont vous n’avez jamais noté la graine.","documentation.1223e0b4":"Il est conservé par utilisateur plutôt que dans le projet — l’endroit où vous avez généré est un fait qui vous concerne, pas quelque chose à livrer dans un morceau envoyé à un label — et il survit à une mise à jour. Chaque artiste garde sa propre série de prises, si bien qu’une soirée passée sur l’un ne peut pas chasser celles que vous avez gardées d’un autre. <strong>Videz-le quand vous voulez</strong> : c’est un relevé de ce que vous avez fait, et pouvoir le vider n’est pas un simple confort.","documentation.13e89cca":"Choisir une prise la <em>restaure</em>, comme le font les flèches — donc tout ce que vous avez dessiné à la main sur le clip actuel est remplacé. Ce n’est pas un aperçu.","documentation.5415794a":"<strong>Verrouillez une piste et une relance ne peut pas y toucher.</strong> Cliquez sur le cadenas de n’importe quelle rangée de batterie, ou appuyez sur <kbd>L</kbd> quand la rangée a le focus, et Générer reconstruit tout le reste autour, note pour note. Un verrou ne change rien à ce qui est exporté.","documentation.99bec605":"Le plug-in enregistre votre artiste, votre graine, vos mesures, vos valeurs fixées et la taille de la fenêtre <strong>dans le fichier de projet de la DAW elle-même</strong>. Rouvrez le morceau et la session revient. Aucun fichier à gérer, aucun chemin à choisir.","documentation.2c40e200":"Le motif lui-même n’est pas stocké — les entrées le sont, et le moteur est déterministe, donc restaurer revient à régénérer. C’est pourquoi un projet enregistré coûte quelques octets au lieu de centaines de kilo-octets de notes.","documentation.3e527f79":"Tous les raccourcis du plug-in et de la version autonome, groupés comme dans le panneau de l’application. Appuyez sur <kbd>Shift</kbd> + <kbd>?</kbd> dans l’application pour voir la même liste avec vos propres réaffectations, que cette page ne peut pas connaître.","documentation.876884a2":"Là où une ligne affiche <kbd>Ctrl</kbd> / <kbd>⌘</kbd>, cela signifie Ctrl (Windows/Linux) ou ⌘ (macOS).","documentation.e5651c68":"Touches","documentation.97c89a4d":"Action","documentation.c10d76c9":"Transport","documentation.86247409":"<kbd>Space</kbd>","documentation.fe13ca09":"Lire ou mettre en pause","documentation.a1e10fc7":"<kbd>F9</kbd>","documentation.7fa3a667":"Démarrer ou arrêter l’enregistrement","documentation.4b2adf96":"<kbd>F10</kbd>","documentation.b32e9662":"Activer ou désactiver le métronome","documentation.dba91bb2":"<kbd>K</kbd>","documentation.7dda588a":"Afficher ou masquer le panneau droit","documentation.523bc70d":"<kbd>E</kbd>","documentation.0b4b9af3":"Basculer entre l’explorateur de fichiers et le répertoire","documentation.df9030e9":"<kbd>Shift</kbd> + <kbd>?</kbd> ou <kbd>F1</kbd>","documentation.1f06ac86":"Afficher ce panneau","documentation.e9789990":"Affichage et disposition","documentation.e14c9778":"<kbd>V</kbd>","documentation.1d83fd23":"Afficher ou masquer un panneau","documentation.d4d84f89":"<kbd>Shift</kbd> + <kbd>V</kbd>","documentation.09faca1e":"Mode focus - panneaux et onglets masqués","documentation.fc45f9b7":"Générer","documentation.285be7d3":"<kbd>Enter</kbd>","documentation.0c77ce7a":"Rechercher dans le répertoire","documentation.04522798":"<kbd>G</kbd>","documentation.ac1fc67e":"Générer cette partie","documentation.627c2d8c":"<kbd>Shift</kbd> + <kbd>G</kbd>","documentation.3767cc00":"Générer toutes les parties","documentation.ed629d67":"<kbd>1 – 6</kbd>","documentation.5ee84ca1":"Choisir un générateur","documentation.51462405":"<kbd>R</kbd>","documentation.9a7a1f12":"Relancer le clip sélectionné","documentation.5eafac83":"<kbd>L</kbd>","documentation.81eb04cd":"Conserver cette piste de batterie lors d’une relance","documentation.9018d7e2":"<kbd>←</kbd> / <kbd>→</kbd>","documentation.cdf3fbba":"Parcourir vos prises","documentation.3b9ba1a2":"Édition","documentation.fd138353":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>A</kbd>","documentation.913afff1":"Tout sélectionner","documentation.ebad6201":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>C</kbd>","documentation.af74f7c5":"Copier","documentation.b737693a":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>X</kbd>","documentation.38d13bda":"Couper","documentation.098d9ba7":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>V</kbd>","documentation.db248300":"Coller","documentation.414f88f4":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>Z</kbd>","documentation.39fc7212":"Annuler","documentation.fc1e31a5":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>Shift</kbd> + <kbd>Z</kbd> ou <kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>Y</kbd>","documentation.471b94d4":"Rétablir","documentation.08b1c0d8":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>D</kbd>","documentation.972d5737":"Dupliquer","documentation.f66bceff":"<kbd>Delete</kbd>","documentation.f6fdbe48":"Supprimer","documentation.07fdb121":"<kbd>Esc</kbd>","documentation.04d948a3":"Désélectionner","documentation.70440046":"Notes","documentation.5d4723bf":"<kbd>↑</kbd> / <kbd>↓</kbd>","documentation.8c532548":"Transposer d’un demi-ton","documentation.6cac4df7":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>↑</kbd> / <kbd>↓</kbd>","documentation.2b308ba3":"Transposer d’une octave","documentation.d47af99e":"Décaler dans le temps","documentation.ac264590":"<kbd>*</kbd>","documentation.be758f68":"Étirer au double de la longueur","documentation.a9253744":"<kbd>/</kbd>","documentation.dd9f8fd9":"Comprimer à la moitié de la longueur","documentation.8382840e":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>R</kbd>","documentation.3ee05a25":"Inverser la note sélectionnée","documentation.7c37d8f8":"Grille de batterie","documentation.9e4e8841":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>3</kbd>","documentation.4157bd81":"Triolet dans cette case","documentation.43a310f9":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>5</kbd>","documentation.7e966ffc":"Quintolet dans cette case","documentation.a5878dde":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>7</kbd>","documentation.1f5d282a":"Septolet dans cette case","documentation.7ec8386d":"<kbd>Alt</kbd> + <kbd>clic</kbd>","documentation.ebfc4304":"Copier la mesure 1 sur cette mesure","documentation.2ff1c1cd":"<kbd>Shift</kbd> + <kbd>glisser</kbd>","documentation.fb11f8c2":"Faire glisser un cadre pour sélectionner des cases","documentation.4fe7447c":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>clic</kbd>","documentation.54e8dccd":"Ajouter une case à la sélection","documentation.1a36d4f6":"<kbd>Clic droit</kbd>","documentation.0aeadb3b":"Palette de roulements pour cette case","documentation.c9889415":"<kbd>Clic droit</kbd> + <kbd>glisser</kbd>","documentation.394a6a30":"Effacer toutes les cases survolées","documentation.dcd5f1f8":"Navigateur d’échantillons","documentation.94d34d10":"Lire l’échantillon à l’envers / à l’endroit","documentation.d604eafc":"L’annulation est illimitée au sein d’une session et couvre l’artiste, la graine, les mesures, les valeurs fixées, chaque génération <strong>et l’arrangement</strong> — une seule pile, quel que soit l’onglet où vous êtes. Dans un champ de texte, c’est l’annulation de votre système qui prend le raccourci, pour que le champ de graine puisse encore effacer un caractère tapé.","documentation.e90cfbee":"Le même plug-in, dans sa propre fenêtre, sans aucune DAW — pratique pour essayer des choses rapidement et sur les machines où vous ne produisez pas.","documentation.c1864be2":"<strong>Elle ne peut pas se synchroniser à votre DAW, et ne le pourra jamais</strong> — il n’y a pas d’hôte, donc rien à quoi se synchroniser. Un tempo fixe peut être défini en ligne de commande, ce qui emprunte le même chemin, mais le vrai tempo, la vraie métrique et la vraie tête de lecture d’un hôte demandent un vrai hôte.","documentation.fb858c80":"<strong>Et elle ne signale aucun tempo de projet, sauf si vous en demandez un.</strong> Sans <code>--tempo</code>, il n’y a pas de projet, donc rien ne prime sur l’artiste : choisissez un modèle et vous l’entendez au tempo auquel il a été écrit. Passez <code>--tempo</code> et cette valeur fixe se comporte exactement comme celle d’un hôte.","documentation.58c0f8e2":"Aucun compte. Aucune télémétrie. Rien sur vous, vos projets ou vos productions n’est transmis. Génération, lecture, import et export sont entièrement locaux.","documentation.6dae90a7":"<strong>Le plug-in n’établit aucune connexion sortante, quelle qu’elle soit.</strong> Les deux qui existaient — une vérification de mise à jour au lancement et un rapport de plantage optionnel — appartenaient à l’application de bureau et ont été retirées avec elle. Un plug-in est installé et mis à jour par celui qui installe les plug-ins, et aucun client HTTP n’y est compilé. Deux garde-fous de compilation le vérifient à chaque commit au lieu de croire l’affirmation sur parole : l’un lit le graphe des dépendances et échoue si un client HTTP y est lié, l’autre pilote la vraie interface pendant une génération et échoue si le navigateur tente une seule requête hors de la machine.","documentation.bef6f4df":"<strong>L’application web est livrée par le réseau ; ce que vous créez, non.</strong> Une page doit être téléchargée — l’application elle-même et les données de style à partir desquelles elle génère. C’est tout. La génération tourne sur votre machine, dans votre navigateur ; vos beats, vos graines et tout ce que vous importez y restent et ne sont jamais envoyés. Après une seule visite, l’onglet fonctionne réseau coupé.","documentation.410bfc53":"<strong>La collaboration est la seule exception, et seulement si vous l’utilisez.</strong> Les salles relient votre machine directement aux personnes que vous invitez. Si vous enregistrez quelqu’un comme contact, un petit service peut vous dire quand il est en ligne — et on ne lui dit rien d’exploitable : une clé qui change toutes les quelques minutes, et une adresse chiffrée avec un secret que vous êtes seuls à détenir, tous les deux. Il ne peut pas la lire, ne peut pas lister qui est là, et ne peut pas déduire qui connaît qui. Désactivez-le, ou n’enregistrez jamais de contact, et vous collez un code à la place. Le service de collaboration est atteint par un programme distinct, jamais par le plug-in que charge votre DAW, et c’est ce qui garde vraie la phrase ci-dessus.","documentation.0b27ac6b":"Les rapports de plantage sont écrits dans un dossier sur votre propre disque et ne sont jamais envoyés nulle part. Ils existent pour que vous ayez quelque chose à joindre à un rapport de bug si vous le souhaitez — personne d’autre que vous ne lit ce dossier.","documentation.6d222977":"Chaque réponse ici reformule quelque chose déjà écrit dans la licence, l’<a href=\"legal/disclaimer.md\">avertissement sur les noms</a> ou les crédits. Rien sur cette page n’est une nouvelle promesse.","documentation.daf9a79b":"Est-ce de l’IA ?","documentation.2458a52d":"Non, et pas au sens faible de « nous ne l’appelons pas comme ça ». Il n’y a aucun apprentissage automatique nulle part dans le produit — aucun modèle, aucune donnée d’entraînement, aucune inférence, aucun réseau de neurones d’aucune sorte. Le moteur lit un ensemble de nombres et de règles écrits à la main et construit un motif à partir d’un générateur aléatoire à graine. Vous pouvez lire ces nombres : c’est du JSON brut, et chacun d’eux est une plage de tempo, un pourcentage de swing, une densité de notes, une grammaire de roulements ou une tendance d’accords.","documentation.3bf82a34":"Alors comment peut-il sonner comme un artiste précis ?","documentation.9412c301":"Parce que les habitudes d’un producteur se décrivent. À quelle fréquence les charleys doublent, où tombe la caisse claire, si la 808 glisse et jusqu’où, quelles familles d’accords apparaissent et lesquelles jamais — tout cela est écrit à la main, à partir d’interviews publiées, d’articles techniques et d’écoute. C’est le même genre de document qu’une leçon de batterie qui vous apprend un shuffle, et ça marche pour la même raison.","documentation.fa02d276":"Les artistes sont-ils impliqués ? L’ont-ils approuvé ?","documentation.ac411997":"Non. <strong>Aucun artiste, producteur, label ou éditeur nommé dans ce logiciel ne l’a approuvé, parrainé, validé ou examiné, ni n’y est lié d’aucune manière.</strong> Leurs noms apparaissent comme des références descriptives à un style reconnaissable et rien d’autre — de la même façon qu’une grille d’accords pourrait être étiquetée « bossa nova ». Aucun nom n’est utilisé comme marque ou comme indication d’origine pour ce logiciel ou pour ce qu’il génère.","documentation.af1c7364":"Contient-il leur musique ?","documentation.bb221e18":"Non. Un modèle de style ne contient aucun MIDI, aucun audio, aucune transcription d’un enregistrement et aucun contenu mélodique ou textuel d’une chanson. Aucune fonction ne recrée un morceau précis, et il n’y en aura jamais — c’est une décision de conception permanente plutôt que quelque chose qui n’est pas encore construit.","documentation.92ebf1ef":"Puis-je sortir ce que je fais ? Puis-je le vendre ?","documentation.02c55f87":"Oui. Ce qu’écrit le générateur est original par construction : il a été assemblé à partir de règles et d’un nombre, sans aucun enregistrement dans la chaîne, donc rien dedans ne provient du travail de quelqu’un d’autre. Vous possédez ce que vous produisez et vous ne devez rien à personne pour cela — voyez la licence ci-dessous pour la formulation exacte.","documentation.1d3f4df2":"La mise en garde habituelle s’applique et n’a rien à voir avec ce logiciel : si vous déposez sur un pad un échantillon dont vous n’avez pas les droits, cet échantillon n’est toujours pas à vous. Les notes sont à vous ; un enregistrement que vous avez importé reste ce qu’il était déjà.","documentation.114f1c77":"Et s’il écrit par accident une mélodie qui existe déjà ?","documentation.e79791f6":"Il le vérifie. Chaque mélodie et contre-mélodie reçoit une empreinte d’après sa forme — la suite d’intervalles et les espaces entre eux — et est comparée à une table de mélodies bien connues avant que vous ne l’entendiez. Une correspondance est jetée et tirée à nouveau.","documentation.9e84e0da":"<strong>Soyons francs sur ce que cela couvre.</strong> La table contient des mélodies du domaine public — traditionnelles, hymnes et classiques — parce que la construire à partir d’autre chose voudrait dire que ce logiciel porte les notes de quelqu’un d’autre, la seule chose qu’il ne doit jamais faire. Le filtre attrape donc une citation accidentelle d’un air célèbre, ce qui vaut la peine d’être attrapé. Ce n’est <em>pas</em> la raison pour laquelle ce que vous produisez est original. Cette raison, c’est tout ce que disent les deux réponses ci-dessus.","documentation.13eef4e4":"Contacte-t-il un serveur ?","documentation.772074f7":"Non. Voyez <a href=\"#privacy\">Confidentialité et réseau</a> plus haut pour la réponse complète, y compris les deux choses qui touchent bien un réseau, et pourquoi : le chargement de l’application web, et la collaboration si vous choisissez de l’utiliser.","documentation.58fc0ea4":"D’où viennent les boucles de batterie et les one-shots ?","documentation.ccf41857":"Les deux sont à nous. Les 5 085 boucles MIDI livrées ont été écrites par les propres générateurs de ce produit à partir de ses propres modèles de style — aucune boucle n’a été extraite de l’audio ou du MIDI de quiconque. Les one-shots d’aperçu sont synthétisés à partir d’oscillateurs et de bruit filtré, ils ne contiennent donc aucun matériau enregistré et aucune licence tierce ne s’y attache.","documentation.1f932b39":"Puis-je l’utiliser hors ligne ?","documentation.a812ebd9":"Le plug-in et la version autonome n’ont jamais eu besoin d’un réseau. L’application web se télécharge une fois, puis fonctionne réseau coupé.","documentation.a1904ba7":"Il n’y a pas de rapporteur qui contacte un serveur, et il n’y en aura jamais. À la place, il y a un dossier : quand l’une ou l’autre moitié du plug-in plante, elle écrit ce qui s’est passé sur votre propre disque, et c’est vous qui décidez de l’envoyer ou non.","documentation.801c98db":"Où se trouvent les rapports","documentation.9cacc2d0":"<code>%APPDATA%\\Freally MIDI Master\\crashes\\</code>","documentation.3b993d8d":"<code>~/Library/Application Support/Freally MIDI Master/crashes/</code>","documentation.1a91a6c1":"<code>$XDG_DATA_HOME/freally-midi-master/crashes/</code>, ou <code>~/.local/share/freally-midi-master/crashes/</code>","documentation.90d83808":"Le nom du fichier indique quelle moitié a lâché : <code>-panic</code> est le moteur audio avec une trace d’appels, <code>-page</code> est l’interface, et sous Windows <code>-fault</code> est une erreur matérielle comme une violation d’accès. Les vingt plus récents sont gardés, pour que le dossier ne grossisse jamais sans limite et que vous puissiez tous les joindre à un rapport de bug.","documentation.4ec55525":"Si c’est l’<em>interface</em> qui a planté, vous verrez un panneau avec un chemin de retour vers votre session plutôt qu’un rectangle mort — l’arrangement vit en dehors de la partie qui a planté, donc appuyer sur le bouton redessine votre propre travail. Signalez-le quand même ; le journal est déjà sur le disque.","documentation.cd05c2a9":"Donc : quand vous le signalez, indiquez l'hôte, le format (CLAP ou VST3) et la version du système, et joignez le fichier le plus récent du dossier ci-dessus. Si le plantage a emporté toute la DAW, joignez aussi le journal écrit par votre DAW — quand l'hôte tombe, il ne nous reste parfois plus aucune fenêtre depuis laquelle écrire.","documentation.f7ca8294":"Propriétaire, <strong>Tous droits réservés</strong> ; le code source est privé. Vous ne pouvez ni le redistribuer ni livrer de produits dérivés. Il n’est <strong>pas</strong> open source.","documentation.5d361274":"<strong>La musique que vous faites avec est la vôtre</strong>, sans redevance et sans obligation d’attribution.","roster.827703c6":"Chaque artiste, producteur et genre que le plug-in modélise.","roster.numbers.genres":"genres","roster.8d0c67df":"<strong>Ce sont des paramètres écrits à la main, pas des données d’entraînement.</strong> L’audio de personne n’a été analysé pour construire quoi que ce soit de tout cela. Chaque entrée est un ensemble de nombres qu’un humain a relevés dans des recherches publiées — plages de tempo, swing, sur quels temps une kick tombe — et les noms sont utilisés comme on utilise un nom de genre, pour dire à quoi ressemble un style. Aucun modèle n’a été entraîné sur qui que ce soit ici, et le plug-in génère des motifs originaux plutôt que de reproduire un enregistrement.","roster.fb1a2b56":"<strong>Aucune affiliation, approbation ou paternité n’est implicite ni revendiquée.</strong> Aucun artiste, producteur, label, éditeur ou détenteur de droits mentionné ici n’a approuvé, parrainé, validé, examiné ce logiciel ni n’y est lié d’aucune manière. Aucun nom ci-dessous n’est utilisé comme marque ou nom de produit, ni comme indication d’origine pour ce logiciel ou pour ce qu’il génère. Toutes les marques et tous les noms appartiennent à leurs détenteurs respectifs. <a href=\"legal/disclaimer.md\">Lire l’avertissement complet</a>.","roster.40f89a05":"Le répertoire","roster.e13848fc":"Nom, genre ou époque","roster.bce06414":"Rechercher","roster.3deb7456":"Type","roster.6a720856":"Tous","roster.1528d87e":"Artistes","roster.a44fa04f":"Producteurs","roster.96817ade":"Genres","roster.5bd44ebe":"Niveau","roster.ab64ea9b":"Phare","roster.2dfa6607":"Standard","roster.2a864697":"Style de","roster.f37a89cb":"Époque","roster.55ac5448":"Chargement du répertoire…","roster.type.artist":"Artiste","roster.type.producer":"Producteur","roster.type.genre":"Genre","roster.shown":"{shown} sur {total} correspondent","roster.none":"Rien ne correspond.","roster.failed":"Le répertoire n’a pas pu être chargé. Essayez de recharger la page.","roster.file":"Cette page est ouverte comme fichier local, et les navigateurs refusent de charger le répertoire depuis une page file://. Ouvrez-la plutôt via HTTP.","kit.skip":"Passer au contenu","kit.nav.site":"Site","kit.nav.home":"Accueil","kit.nav.features":"Fonctionnalités","kit.nav.documentation":"Documentation","kit.nav.roster":"Catalogue","kit.nav.changelog":"Journal des modifications","kit.nav.language":"Langue","kit.nav.allApps":"Toutes les apps Freally","kit.badge.progress":"v1.0.0-beta est terminée · v1.0.0RC est la prochaine","kit.cta.features":"Voir toutes les fonctionnalités","kit.cta.docs":"Lire la documentation","kit.price":"Freally MIDI Master est gratuit aujourd'hui, mais ne le restera peut-être pas toujours : les versions futures pourraient être vendues.","kit.noDownloads":"Il n'y a pas encore de téléchargement, et le code source est privé.","kit.label.overview":"Aperçu","kit.label.inAction":"En action","kit.label.inside":"À l'intérieur","kit.label.roadmap":"Feuille de route","kit.ladder.done":"Fait","kit.ladder.planned":"Prévu","kit.ladder.goal":"L'objectif","kit.label.honesty":"Honnêteté","kit.family.label":"La famille Freally","kit.family.title":"<span class=\"hl-muted\">Une famille.</span> <span class=\"hl-bright\">Huit apps.</span>","kit.cta.label":"Ce qui a changé","kit.cta.title":"<span class=\"hl-muted\">Chaque version,</span> <span class=\"hl-bright\">consignée.</span>","kit.cta.lede":"Le journal des modifications recense tout ce qui a changé dans Freally MIDI Master, version après version, dans les dix-huit langues.","kit.cta.changelog":"Lire le journal des modifications","kit.footer.thisApp":"Cette app","kit.footer.family":"La famille Freally","kit.status.devVersion":"En développement · v1.0.0-beta","kit.head.features":"<span class=\"hl-muted\">Tout ce qu'il fait,</span> <span class=\"hl-bright\">côte à côte.</span>","kit.label.numbers":"En chiffres","kit.label.free":"Gratuit aujourd'hui","kit.label.compare":"Comparaison","kit.label.principles":"Principes","kit.label.limits":"Limites","kit.states.title":"Ce que signifient les états","kit.states.done":"construite et étiquetée, mais pas un téléchargement sur ce site","kit.states.planned":"encore à construire","kit.states.goal":"la version à laquelle mène la route","kit.states.ladder":"Voir chaque échelon de la route","kit.head.documentation":"<span class=\"hl-muted\">Comment ça marche,</span> <span class=\"hl-bright\">étape par étape.</span>","kit.search.placeholder":"Rechercher dans la documentation","kit.docs.contents":"Sommaire","kit.head.roster":"<span class=\"hl-muted\">Chaque style,</span> <span class=\"hl-bright\">dans une seule liste.</span>","kit.numbers.lead":"Chaque chiffre est compté à partir de l’application elle-même. Rien n’est estimé, rien n’est arrondi à la hausse.","kit.label.styles":"Styles","kit.head.changelog":"<span class=\"hl-muted\">Chaque changement,</span> <span class=\"hl-bright\">version après version.</span>","kit.changelog.lede":"Le plus récent d'abord : tout ce qui a changé dans Freally MIDI Master, dans chaque langue de ce site.","kit.changelog.versions":"Versions","kit.changelog.unreleased":"Non publié","kit.search.none":"Rien sur ce site ne correspond à cela.","changelog.69c6a54708de":"<span class=\"release__meta\"><span class=\"release__ver\">Non publiée</span></span>","changelog.2a6141e43be0":"Modifié","changelog.e872b6a54c3f":"<strong><code>freally-encode</code> et <code>freally-drag</code> sont des crates à part entière</strong> (tag partagé <code>shared-v2</code>, le découpage A de Freally Unloop). Le module d’écriture WAV/AIFF avec son chunk de tempo <code>acid</code>, la sonde WAV et l’unique porte de rééchantillonnage <code>rubato</code> sont passés de <code>freally_library::encoder</code> et <code>plugin/src/audio/resample.rs</code> à <code>encode/</code> (<code>freally-encode</code>) ; la source de glisser-déposer OLE / Cocoa / GTK est passée de <code>plugin/src/drag/</code> à <code>drag/</code> (<code>freally-drag</code>), générique sur le produit. MIDI Master consomme les deux et ses octets sont inchangés : les mêmes fichiers WAV et AIFF, le même chunk <code>acid</code> à chaque profondeur, le même dossier de spool de glisser-déposer. Le chunk de session de la bibliothèque reste dans <code>freally_library::encoder</code>, qui réexporte le reste.","changelog.57c8863aec4f":"<strong>FLAC et MP3, derrière des features.</strong> <code>freally-encode</code> ajoute FLAC (<code>flacenc</code>, feature <code>flac</code>, un commentaire Vorbis <code>BPM=</code>) et MP3 (<code>rusty_mp3</code>, feature <code>mp3</code>, ID3v2.3 <code>TBPM</code>/<code>TIT2</code>) pour le Print d’Unloop. MIDI Master n’active encore ni l’un ni l’autre. Les modules d’écriture bas niveau ne réétiquettent jamais l’audio : une fréquence qu’ils ne peuvent pas porter est refusée, et les portes de rééchantillonnage convertissent d’abord. <code>ci:local</code>, la CI et <code>cargo deny</code> compilent, testent et vérifient désormais les licences de la crate avec toutes les features activées.","changelog.e418959c78ca":"<strong>L’adaptateur webview nomme son propre dossier de données</strong> (<code>WebViewEditor::with_data_dir_name</code>, valeur par défaut inchangée : <code>Freally MIDI Master</code>), et l’ajustement de l’éditeur à l’écran (<code>system_scale</code>, <code>work_area</code>) est passé dans le module <code>screen</code> de l’adaptateur. Un nom invalide revient à la valeur par défaut.","changelog.28724e313f97":"<strong><code>engine</code> est autonome</strong> : <code>data/humanize/groove.json</code>, son README et <code>data/novelty/hooks.hash</code> sont passés sous <code>engine/data/</code>, si bien que la crate se compile depuis une copie vendorisée ou publiée, et pas seulement depuis un checkout complet.","changelog.7542eeec97e8":"<strong><code>engine::smf_read::read_facts</code></strong> — les notes, le format, le tempo, le PPQ, les pistes, la signature rythmique et la longueur d’un fichier MIDI, pour la Loop Library d’Unloop.","changelog.5af8a9a4077e":"<strong><code>freally-extract</code> est une crate à part entière</strong> (tag partagé <code>shared-v3</code>, pour la TASK-020 de Freally Flipcopy et la TASK-090 de Freally Unloop). L’extracteur — attaques, grille, batterie, lignes mélodiques, test vocal, chroma — est passé de <code>plugin/src/extract/</code> à <code>extract/</code> (<code>freally-extract</code>), avec la porte de décodage placée devant lui (<code>plugin/src/audio/import.rs</code>, désormais <code>freally_extract::decode</code>), le détecteur de hauteur (<code>plugin/src/audio/pitch.rs</code>), <code>midi_hz</code> et <code>SILENCE_PEAK</code>. Chaque ancien chemin réexporte ce qui a bougé, si bien que l’extraction, l’import de one-shots et l’analyse de la bibliothèque de MIDI Master lisent les mêmes fichiers de la même façon ; seule la tâche qui lance une extraction sur un worker reste dans le plug-in. La crate se compile pour <code>wasm32</code> (l’application web d’Unloop), et <code>ci:local</code> et la CI le vérifient désormais.","changelog.a04385060482":"<strong><code>freally_extract::decode::decode_facts</code></strong> (et <code>decode_file_facts</code>) — la même porte de décodage, qui renvoie aussi ce que contenait le fichier avant le repli en mono : ses canaux, sa profondeur de bits, ainsi que la crête et le RMS sur tous les canaux. Pour les pages imprimées de Flipcopy. Comptabilisé par l’unique lecteur au passage des paquets ; les portes qui existaient déjà renvoient exactement ce qu’elles renvoyaient.","changelog.6cb361b3247a":"<strong><code>freally_library::audition::NoteRenderer</code></strong> (<code>render_notes</code> dans le plan de Flipcopy, <code>shared-v3</code>) — les notes d’un clip rendues via un préréglage de la bibliothèque, ou via une boîte à rythmes avec une voix par piste de batterie GM, avec le pitch bend et la pédale de sustain respectés et une queue après la dernière note. Les voix sont celles de <code>SynthEngine</code>, la batterie celle de <code>drumkit</code>, les événements sont appliqués sur leur trame, et le rendu d’un préréglage tire sa graine du préréglage, si bien que les mêmes notes donnent les mêmes octets. Une note de batterie à laquelle aucune piste ne répond est comptée, jamais devinée. Pour le MIDI → audio de Flipcopy ; rien dans MIDI Master ne l’appelle encore.","changelog.86cdd25e66f0":"<strong><code>engine::smf_read::read_facts</code> signale chaque pitch bend et chaque contrôleur</strong> (<code>Facts::controls</code>, <code>shared-v3</code>), dans l’ordre chronologique, plafonnés à 20 000 avec <code>controls_capped</code> qui le signale — un plafond, jamais un refus, si bien que chaque fichier qui s’importait avant s’importe exactement comme avant.","changelog.ed6c4224859d":"<strong>Les refus comme valeurs</strong> (<code>shared-v3</code>) : <code>decode_facts</code> et <code>read_bounded</code> de la porte de décodage, ainsi que <code>engine::smf_read::read_facts</code>, refusent avec un <code>Refusal</code> typé (trop gros, trop long <em>à la fréquence propre du fichier</em>, silencieux, SMPTE, trop de notes…) dont le <code>Display</code> est la phrase que ces portes ont toujours renvoyée — si bien que chaque porte <code>String</code> dit exactement ce qu’elle disait. Pour Freally Flipcopy, qui imprime chaque refus dans la langue du producteur avec sa limite au lieu de comparer du texte anglais. <code>read_facts</code> renvoyait un <code>String</code> à <code>shared-v2</code>.","changelog.980fad0ffb14":"<strong><code>NoteRenderer::set_sample_rate</code></strong> (<code>shared-v3</code>) : une nouvelle fréquence garde les moteurs chauds (chacun réajusté à sa prochaine utilisation) au lieu de les reconstruire.","changelog.e9ddffd5fc76":"<strong><code>freally_extract::decode::frame_budget</code></strong> (<code>shared-v3</code>) : les trames que contient un décodage à une fréquence donnée pour une limite en secondes — la règle propre de la porte, désormais publique, si bien qu’un produit qui rend un fichier qu’il relira par la porte (les copies de Freally Flipcopy) refuse le rendu que la porte refuserait, avant de l’allouer.","changelog.013f4389933a":"<strong><code>read_bounded</code> est borné par ce qu’il lit</strong> (<code>shared-v3</code>, revue de code de Freally Flipcopy) : un périphérique est refusé avant qu’un seul octet soit lu, et un fichier qui grossit après la vérification de sa taille est lu jusqu’à <code>MAX_FILE_BYTES</code> puis refusé — la seule vérification de taille laissait lire <code>/dev/zero</code>, qui annonce une longueur nulle, jusqu’à ce que l’hôte manque de mémoire.","changelog.2d1ace37beb0":"<strong>Une note plus courte qu’une trame est relâchée</strong> (<code>NoteRenderer</code>, <code>shared-v3</code>) : son relâchement tombe une trame après son attaque, jamais dessus — sur une même trame, les relâchements passent en premier, si bien qu’une note dont le début et la fin s’arrondissaient à la même trame sonnait pendant toute la queue.","changelog.3649549ac755":"<strong><code>drums::proposal_name</code> est public (masqué de la documentation)</strong> pour que le banc d’essai de la batterie l’atteigne à travers la nouvelle frontière de crate.","changelog.87e36c5e8277":"<strong>nih-plug avance d’un commit</strong> (<code>shared-v3</code>) : le <code>ProcessContext::process_mode()</code> du fork, pour qu’un plug-in sache qu’un bloc est un rendu hors ligne même quand un hôte CLAP a changé de mode sans le réinitialiser (les sons de la machine de Freally Flipcopy ne doivent jamais atteindre un bounce). L’adaptateur et les deux manifestes de plug-in avancent ensemble : un seul <code>nih_plug</code> dans le build.","changelog.807f6de9d0ba":"<strong><code>nih-plug-webview</code> accepte les fichiers déposés depuis l’OS</strong> (<code>WebViewEditor::with_file_drop_handler</code>, <code>shared-v3</code>, pour la vitre de Freally Flipcopy) — les événements de dépôt de fichiers de wry avec leurs chemins, sur le thread d’interface de l’éditeur. Sur option : sans gestionnaire, la webview garde son propre comportement, et l’éditeur de MIDI Master n’en définit aucun.","changelog.1246fc93bca0":"Corrigé","changelog.464aedef592b":"<strong>Un fichier MIDI fait de note-on qui ne se terminent jamais est refusé</strong>, et non lu : la limite de notes compte les notes ouvertes comme les notes fermées, et un note-off trouve sa note en temps logarithmique — un fichier d’un million de note-off orphelins ne prend plus des secondes.","changelog.22e2ad641345":"<strong>Le nettoyage des fichiers vieux d’une semaine dans le spool de glisser-déposer ne supprime jamais l’audio d’un sous-dossier</strong>, ne suit jamais un lien, et un glisser-déposer de spool, de débordement ou de fichier refuse un nom ou un chemin qui n’est pas simple.","changelog.59ff0563db02":"<strong>L’audio exporté à une fréquence différente de celle du rendu a exactement la bonne longueur et se place exactement où il faut.</strong> Le rééchantillonneur perdait les dernières trames de chaque conversion (48 000 trames à 48 kHz donnaient 44 098 trames à 44,1 kHz, et non 44 100) et décalait tout jusqu’à trois trames — +1,17 trame de retard à 44,1→96 kHz, une demi-trame d’avance à 96→48 kHz. La longueur vaut désormais <code>frames × to / from</code> à la trame près, et le placement est juste à un cinquantième de trame près à chaque fréquence d’export. Cela change les octets de tout export ou glisser-déposer à une fréquence non native, et un one-shot de kit converti à une fréquence de périphérique différente de la sienne garde désormais ses dernières trames ; tout ce qui est à sa propre fréquence est inchangé.","changelog.db671325856c":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0RC</span><time class=\"release__date\" datetime=\"2026-09-17\">2026-09-17</time></span>","changelog.2d4bc1529072":"<strong>La première version candidate</strong>, 153 entrées depuis la 0.4.0. Pas un téléchargement : ces binaires servent aux propres tests du propriétaire dans Ableton, FL Studio, Reaper et Freally Oscillate, et aucun lien n’apparaît sur le site avant que ce soit fait.","changelog.2140e4134a93":"<strong>Il tourne désormais à quatre endroits</strong> — ce plug-in, une version autonome, un onglet de navigateur qui exécute le même générateur compilé en wasm, et MixSir sur un téléphone. <strong>Nouveau :</strong> salons de collaboration, quatre Extensions d’usine (1 400 instruments, 5 085 boucles, 189 artistes de plus), fondus de clips, une vue audio des clips qui est l’audio réel, probabilité et vélocité par note, une session qui voyage dans le fichier exporté, et un produit vert.","changelog.89b5266eb048":"<strong>Connu :</strong> pas encore d’éditeur Linux, donc Linux n’est pas compilé ici ; les binaires ne sont pas signés, par principe, avec leurs sommes de contrôle à côté ; et onze constats de revue sont consignés et non corrigés dans <code>docs/product-roadmap.md</code>, aucun n’étant un plantage ni une perte de données.","changelog.68f004440417":"Corrigé - le contrôle e2e expirait sur un serveur de dev à froid, 2026-09-17","changelog.9656ae419100":"Quatre specs d’accessibilité échouaient sur <code>page.goto</code> alors que la page n’avait aucun problème : un <code>vite</code> à froid compile le graphe de modules à la première requête du navigateur (19,5 s mesurées), et avec quatre workers, quatre specs le payaient en même temps. <code>e2e/warm.setup.ts</code> compile désormais l’application une fois avant la suite — l’a11y est passée de 4 en échec/3 instables à <strong>9/9</strong>, et l’exécution entière est devenue plus rapide, 4,7 min contre 7,1.","changelog.aeb4521d29c5":"⚠ La première tentative a placé l’exclusion sur la mauvaise couche de configuration et a silencieusement réduit la galerie à <strong>0 test collecté</strong>, ce qu’un contrôle rapporte comme une réussite.","changelog.730e1894b827":"Modifié - le produit est vert désormais, et c’est le vert de l’icône, 2026-09-16","changelog.b34d121fa3fb":"Tout le violet de l’application, du plug-in et du site de documentation a disparu. <code>#79D920</code> est <strong>échantillonné</strong> sur <code>images/freally-icon.png</code> — le centre pondéré de ses pixels vert vif — si bien que l’interface et l’icône de la barre des tâches sont le même vert plutôt qu’un vert presque identique.","changelog.b9820271dd5a":"⛔ Le thème clair prend le vert d’ombre de l’icône, <code>#1A6B02</code>, car <code>#79D920</code> n’offre que <strong>1,79:1</strong> sur blanc. Le même calcul a attrapé un vrai bug : un bouton de marque avec une étiquette blanche codée en dur, illisible sur le nouveau vert, utilise désormais <code>--color-on-primary</code>.","changelog.17307457bdf8":"⚠ Les neutres ont bougé en teinte et non en luminance, si bien qu’aucune des 112 assertions de contraste n’a bougé. La couleur cyan de la tête de lecture reste intacte, à dessein.","changelog.97e593faa953":"Ajouté - le nom tourne en haut de la fenêtre, 2026-09-16","changelog.a5f5f81eb744":"« FREALLY MIDI MASTER v1.0.0RC », gravé et tournant sur son axe Y en haut au centre de l’application. C’est une extrusion plutôt qu’un retournement — dix copies empilées le long de Z, car un seul <code>rotateY</code> se réduit à un trait fin à 90° et donne l’impression que le nom s’éteint. Il s’arrête net sous <code>prefers-reduced-motion</code>, figé de biais pour que la profondeur reste visible.","changelog.84bc48ed5549":"Ajouté - les clips ont un fondu d’entrée et de sortie, avec une courbe que vous pouvez plier, 2026-09-16","changelog.ef9458203075":"Chaque clip de l’arrangement du morceau a un fondu d’entrée et un fondu de sortie, chacun avec une poignée pour sa longueur et un point pour sa forme — pour qu’un arrangement d’artiste puisse être plié jusqu’à devenir le vôtre.","changelog.2cb75c827e48":"⛔ Les deux tracés ne peuvent jamais se croiser : une paire croisée ne décrit aucune enveloppe, donc quand ils se chevaucheraient, ils se réduisent <em>proportionnellement</em> plutôt que l’un efface silencieusement l’autre. Le <code>fadeGain</code> de la page reflète exactement le <code>Fade::gain_at</code> du moteur, si bien que le dessin et l’audio sont une seule et même formule.","changelog.3dfc5811a505":"Ajouté - la vue audio d’un clip est désormais l’audio réel, 2026-09-16","changelog.6279a3048ed5":"Passez l’arrangement en clips audio et vous voyez chaque clip rendu par son propre instrument, pour savoir comment il sonne avant de le faire glisser dans votre DAW.","changelog.ee37a55bde55":"⛔ Le thread de l’éditeur ne fait jamais de rendu — 320 clips à une demi-seconde chacun figeraient l’hôte. Le plug-in répond depuis un cache ou met le travail en file d’attente, et la frise garde son esquisse de notes jusqu’à ce que l’image arrive. Le « temps réel » découle du fait que la clé du cache est le clip <em>et son son</em> : un bouton tourné donne un nouveau rendu, et rien n’interroge en boucle.","changelog.a9a5cc1bf02a":"⚠ Un onglet de navigateur garde l’esquisse de notes pour toujours : aucun audio n’y est préparé.","changelog.7f09fbbe15e8":"Ajouté - probabilité et plage de vélocité par note, 2026-09-16","changelog.750b30239ec8":"<strong>N’importe quelle note du piano roll peut recevoir une probabilité de jouer et une vélocité qui varie.</strong> Mike : <em>« B5-2 — Probabilité par note »</em>, <em>« B5-3 — Écart/plage de vélocité par note »</em>. Une probabilité se dessine comme la part remplie de la note ; une plage est une bande autour de son plafond dans la piste de vélocité.","changelog.38ee53053857":"⛔⛔ L’EXPORT FIGE, ET IL FIGE DE LA MÊME FAÇON À CHAQUE FOIS","changelog.a910d8608bd3":"Soit le <code>.mid</code> fige un seul tirage et deux exports diffèrent — ce qui casse les snapshots de référence et le contrôle <code>web_parity</code> à l’octet près — soit la fonction ne vaut qu’en prévisualisation et ment sur ce que vous obtiendrez.","changelog.a2258c7138d5":"▶ <strong>Les deux branches du dilemme supposent que le figeage est aléatoire. Il ne l’est pas.</strong> Le tirage est un hachage de la graine du clip, de la passe et de l’index de la note, et chaque export fixe la passe, si bien que le fichier fige <em>et</em> que deux exports sont identiques. Ableton fige de façon non déterministe ; ceci est strictement meilleur et ne coûte rien. Une note non modifiée saute entièrement le tirage plutôt que de toujours gagner, ce qui garde chaque snapshot identique à l’octet près.","changelog.431581274355":"Corrigé - l’icône de la version autonome venait d’un fichier qui n’a jamais existé, 2026-09-16","changelog.a1f30e06011e":"<code>plugin/build.rs</code> disait à chaque lecteur de régénérer <code>icon.ico</code> depuis <code>images/freally_app_icon.png</code>, qui n’a jamais été dans ce dépôt. Il désigne désormais <code>images/freally-icon.png</code> — la vraie icône du produit.","changelog.d910c7246ee7":"⚠ Les entrées du <code>.ico</code> sont en DIB et vérifiées une par une : des entrées compressées en PNG font retomber le compilateur de ressources sur l’icône Rust par défaut, <em>silencieusement</em>.","changelog.1ec023a53376":"Ajouté - votre session voyage dans le fichier, 2026-09-16","changelog.fd23b1eb34b6":"Un <code>.mid</code> ou un <code>.wav</code> exporté emporte désormais toute la session qui l’a produit. Dans une DAW, c’est un fichier ordinaire ; ouvert ici, l’artiste, les graines, les valeurs fixées, l’humeur, les verrous, les mutes et les assignations de pads reviennent tous — si bien qu’un fichier se rouvre comme <strong>le vôtre</strong> plutôt que comme les notes de quelqu’un. Le MIDI utilise <code>FF 7F</code>, que les lecteurs doivent ignorer ; l’audio utilise un chunk RIFF à côté du chunk <code>acid</code> qui porte déjà le tempo. Redéposez un <code>.wav</code> que ce produit a exporté et la session revient instantanément au lieu d’une minute d’analyse qui ne ferait que l’approcher.","changelog.906d755eff63":"⛔ Un fichier que quelqu’un vous a envoyé n’est pas fiable : le blob est versionné et sa longueur plafonnée, et un document avec un seul champ faux est refusé <strong>en entier</strong>, car une session à moitié appliquée, c’est votre nom d’artiste par-dessus les valeurs fixées de quelqu’un d’autre. <code>midly</code> analyse un fichier tronqué sans broncher — 200 octets donnent encore un document plausible — donc le blob déclare sa propre longueur.","changelog.7294c9f3bc34":"Corrigé - le bouton Exporter du navigateur ne pouvait pas écrire de fichier, 2026-09-16","changelog.f9ee85761134":"Appuyer sur Exporter dans l’onglet Morceau d’un navigateur répondait <em>« il n’y a rien de généré à écrire »</em>, à chaque fois : un seul store sert le plug-in et l’onglet et envoie <code>{ song }</code>, alors que la couche fichiers de l’onglet lisait une liste <code>files</code> que rien n’envoie. Il rend désormais via la commande que le glisser-déposer utilisait déjà, si bien que le fichier que vous téléchargez et celui que vous faites glisser sont les mêmes octets.","changelog.98dc5d6ecb9c":"Corrigé - déposer un <code>.mid</code> sur l’onglet Morceau du navigateur stockait la mauvaise chose, 2026-09-16","changelog.f322f30777de":"<code>explorer_song</code>, <code>explorer_midi_split</code> et <code>explorer_midi_audition</code> recevaient tous la réponse du <em>découpage</em>, si bien que l’onglet Morceau recevait une liste de parties là où va un arrangement.","changelog.cd2c30298eab":"⚠ Les deux bugs sont sortis parce que les specs couvrant ces boutons tournent contre le mock, qui répond correctement. La couche fichiers de l’onglet n’avait aucun test ; elle vérifie désormais la <strong>forme</strong> plutôt que le nom, puisque le contrôle des noms était vert pour les deux bugs.","changelog.992288d62132":"Corrigé - le mute forcé du propriétaire ne fonctionnait sur personne, 2026-09-15","changelog.91b56d408438":"Mute forcé, caméra forcée à l’arrêt et retrait du salon étaient trois boutons qui ne faisaient rien et ne signalaient rien : la page demandait <code>collab_force</code> et <code>collab_remove</code> depuis leur écriture, et le plug-in ne répondait à aucun des deux. La page interprète tout rejet comme <em>« il n’y a pas de sidecar »</em>, ce qui explique que personne n’ait jamais vu d’erreur — y compris un propriétaire essayant de couper un micro resté ouvert. Les deux reçoivent désormais une réponse, et un argument mal formé est refusé plutôt que remplacé par une valeur par défaut, car chaque valeur par défaut ici est une décision sur la caméra de quelqu’un d’autre.","changelog.63b986d4078b":"Corrigé - une mention légale que personne ne pouvait lire dans le thème sombre, 2026-09-15","changelog.362a34927497":"La mention sur la formulation des noms sous la liste déroulante du répertoire fait ~10,9 px et était peinte dans le niveau <strong>atténué</strong>, que la palette réserve au grand texte. Elle mesurait <strong>4,33:1</strong>, sous les 4,5:1 qu’exige le petit texte. Elle utilise désormais le niveau du corps de texte.","changelog.29cb2a06fe81":"⚠ La suite d’accessibilité pilote le thème clair, où la même déclaration mesurait 5,78:1 et passait ; une assertion unitaire vérifie donc désormais les trois thèmes.","changelog.97a64162696b":"Corrigé - le contrôle qui traque les commandes d’interface mortes ne voyait pas la collaboration, 2026-09-15","changelog.b5db170b03d8":"<code>bridge_names.rs</code> récupérait chaque <code>invoke('name')</code> du frontend — mais chaque module de collaboration passe une <em>constante</em> par une fonction utilitaire, précisément pour qu’une même orthographe ne puisse pas diverger entre trois sites d’appel. La convention qui rendait ces noms sûrs est celle qui les cachait, et <strong>sept commandes étaient invoquées par des commandes d’interface livrées et rien n’y répondait.</strong> Le contrôle résout désormais les constantes ; deux sont corrigées ci-dessus et les cinq autres sont listées dans le test avec la raison pour laquelle chacune n’est pas construite, si bien que le manque est nommé sous forme exécutable plutôt qu’oublié.","changelog.2296e280a445":"Modifié - le nom de piste d’un motif exporté dit « le style », 2026-09-12","changelog.b9aa73561b5e":"Le nom de piste écrit <strong>à l’intérieur</strong> d’un <code>.mid</code> était <code>trap — Drums</code> ; il est désormais <code>trap style — Drums</code>, la distinction que font déjà l’interface et les noms de fichiers. Le nom d’un interprète décrit un style, jamais une marque d’origine sur un fichier qui quitte cette application.","changelog.a1c7a1a5e076":"⚠ Pas une note n’a bougé : les quatre snapshots de référence diffèrent chacun de six octets de texte.","changelog.9d55f9efea57":"Ajouté - l’explorateur de fichiers s’ouvre sur Catégories, avec les chiffres, 2026-09-11","changelog.8fe51cad16bc":"Il s’ouvrait auparavant sur les familles d’instruments dans l’ordre où le moteur les gardait, sans aucun décompte — et les étagères de la bibliothèque, les packs de boucles et les kits de batterie formaient une arborescence de dossiers dessinée <em>à l’intérieur</em> du navigateur d’instruments, si bien que les Packs d’usine étaient tout simplement inaccessibles depuis le haut.","changelog.0297cd02ea56":"Il s’ouvre désormais sur <strong>Catégories</strong>, une ligne par emplacement, chacune indiquant ce qu’elle contient : <strong>Instruments</strong> et quatre <strong>Extensions d’usine</strong> (248 et 350 chacune), <strong>Packs de batterie</strong> (onze kits, 407 one-shots, écoutables pour la première fois) et <strong>Packs d’usine</strong> (5 085 boucles MIDI). Les lignes sont triées par ordre alphabétique dans celle des dix-huit langues que vous utilisez, et un disque débranché garde sa place et est marqué <strong>Indisponible</strong> en toutes lettres plutôt que seulement par une couleur.","changelog.830c1bfc1fee":"Le décompte vient du moteur sans filtre — ce qui est sur l’étagère, pas ce qui a survécu aux puces de filtre — donc il ne bouge pas quand vous appuyez sur <em>Ligne de basse</em>.","changelog.371bd3942abc":"⛔ Corrigé par le même changement : les étagères débordaient les unes sur les autres. <em>Extension d’usine 2 → Claviers</em> listait chaque instrument Claviers des cinq étagères, car l’étagère était un dossier à l’écran et rien du tout dans la requête.","changelog.30193f2cd07f":"Modifié - l’interface dit « le style », pas « l’artiste », 2026-09-11","changelog.61bd40930314":"Neuf libellés restants disaient <em>artiste</em> là où ils voulaient dire <em>le style</em> — <em>« Utilise le tempo de l’artiste »</em>, <em>« Ce que l’artiste écrit »</em>. Huit affirmaient quelque chose sur une personne réelle. Les neuf nomment désormais le style, dans les dix-huit langues, avec le mot propre à chaque langue.","changelog.094d4fef1e50":"Ajouté - le site de documentation en dix-huit langues, 2026-09-11","changelog.3ec2581c410e":"Un sélecteur de langue sur chaque page, qui propose les mêmes dix-huit langues que le plug-in, chacune sous son propre nom.","changelog.d7aa7f80c47a":"Corrigé - nommer vos exports ne casse plus les Paramètres dans un onglet de navigateur, 2026-09-11","changelog.8269f52c0420":"Le panneau de nommage des exports demandait à l’onglet un modèle de nommage et recevait une forme différente de celle qu’il lit, entraînant tout le panneau Paramètres dans sa chute. Un onglet n’a pas de modèle de nommage — ses téléchargements sont nommés dans le moteur — donc il le dit et omet la section.","changelog.756e358cd7bf":"Corrigé - les cloches sonnent comme des cloches au lieu d’être coupées net, 2026-09-10","changelog.f454ead481c6":"Une cloche d’église sonnait 3,2 secondes alors que ses propres partiels sont accordés pour sonner neuf secondes : relâcher la touche engageait un étouffoir, et une cloche de clocher n’en a pas. Même chose pour un gong, des cloches d’orchestre, un steel pan et un handpan. Une cloche d’église sonne désormais 6,6 secondes, et les instruments réellement étouffés ne sont pas touchés, car raccourcir le son est justement leur raison d’être.","changelog.bf56e0465d30":"Deux défauts que ce correctif a mis au jour : <em>tout arrêter</em> ne fonctionnait plus sur ces instruments, si bien qu’une panique laissait un gong sonner à plein niveau — une panique et un relâchement de touche sont désormais deux choses différentes — et le pitch bend d’un instrument frappé modifiait son volume de jusqu’à 7 dB, car réaccorder un résonateur qui sonne déplace aussi son niveau.","changelog.721f6099a36a":"⚠ Connu et non corrigé : 107 des 118 instruments de la bibliothèque nommés <em>Bell</em> ou <em>Chime</em> sont construits à partir d’oscillateurs harmoniques plutôt que des partiels inharmoniques d’une cloche. Les générateurs ne puisent que dans ceux qui sont modélisés.","changelog.a3790f42036f":"Corrigé - le bouton de pitch bend fait enfin varier la hauteur, et reste là où vous le mettez, 2026-09-10","changelog.7eae79e5967e":"<strong>Douze des treize moteurs d’instruments ignoraient entièrement la molette de pitch</strong> — chaque cloche, guitare, corde frottée, cuivre, piano, orgue, voix, boîte à rythmes et instrument de caractère, depuis le bouton dessiné <em>comme</em> depuis un contrôleur matériel. Un instrument modélisé reçoit sa hauteur une seule fois, et rien ne lui transmettait la molette ensuite. Désormais, les partiels d’une cloche, la longueur de corde d’une guitare et la voix d’un chanteur bougent tous, tandis que les parties qui ne suivent pas la note restent en place — la caisse d’un violon, les formants d’une voix, la boîte d’un kalimba.","changelog.28b122d799de":"<strong>Et le bouton ne défait plus votre réglage.</strong> Il revenait au centre au relâchement, ce que fait une molette à ressort cachée et non un bouton dessiné avec un affichage de valeur. Il garde désormais sa position ; un double-clic le recentre, comme pour tous les autres boutons.","changelog.bfc70626288e":"⚠ Cela a rendu accessible un second défaut, corrigé ici aussi : sur les instruments à banc de résonateurs d’accords, la <em>deuxième</em> note d’une phrase jouée avec la molette maintenue sortait une quinte trop haut. Rien n’aurait pu le trouver avant, car la molette ne pouvait pas encore être maintenue quand la touche suivante s’enfonçait.","changelog.5acc9d14ec6b":"Corrigé - le clavier virtuel remplit l’espace qui lui est donné, 2026-09-10","changelog.d414fd02f3e7":"Le piano s’arrêtait à mi-chemin et se collait au bord droit : sa rangée dimensionne ses enfants selon leur propre contenu, si bien que le clavier était aussi large que les petites commandes d’octave au-dessus de lui plutôt qu’aussi large que l’application. Il remplit désormais son conteneur à toutes les tailles.","changelog.06900e6126d2":"Ajouté - faites glisser une boucle d’un Pack d’usine directement dans vos motifs, 2026-09-10","changelog.e811e0ddcc9f":"Le navigateur de packs livre 5 085 boucles MIDI et pouvait toutes les jouer et en faire <strong>sortir</strong> une vers votre DAW — mais il n’y avait aucun moyen d’en faire <strong>entrer</strong> une, si bien que vous entendiez le beat voulu et le reconstruisiez à la main. Chaque ligne de boucle est désormais une source de glisser-déposer : déposez-la sur un générateur et elle arrive découpée sur les bonnes parties, exactement comme un <code>.mid</code> venant de l’explorateur de fichiers.","changelog.aa75d339c210":"⚠ L’onglet Morceau refuse une boucle et le dit par le curseur : Morceau construit un arrangement à partir des sections d’un fichier, et quatre mesures n’en ont aucune.","changelog.470ee0ab09bc":"Corrigé - les dossiers partagés d’un pair s’ouvrent, et le badge dit la vérité, 2026-09-09","changelog.184268a38575":"L’explorateur partagé a reçu son client à la version précédente et ne pouvait pas fonctionner. Trois défauts, tous invisibles parce que le navigateur mock était alimenté à la main en lignes à la forme de la <em>page</em> et que rien ne les comparait à ce qu’envoyait le plug-in.","changelog.a159c8fdb762":"<strong>Aucun dossier ne pouvait être ouvert.</strong> Le plug-in répondait <code>kind: &quot;folder&quot; | &quot;sound&quot;</code> sans <code>isDir</code>, ce que le volet lit pour dessiner un triangle de dépliage — si bien que chaque racine de partage s’affichait comme un fichier, et que « avez-vous ceci ? » était demandé à propos de répertoires.","changelog.806039630970":"<strong>Chaque fichier prétendait durer une fraction de seconde.</strong> Le champ de durée de la ligne n’est pas une durée : c’est la longueur repliée de façon logarithmique sur 0 à 1 pour qu’un one-shot et une boucle de quatre mesures soient comparables. Elle était affichée comme « 0.35s ». Le champ porte désormais le nom de ce qu’il est et s’affiche sans unité.","changelog.56c9265a4563":"<strong>« Vous avez quelque chose d’approchant » ne pouvait jamais apparaître.</strong> Il faut pour cela les quatre nombres qui décrivent un son, et seule l’empreinte était envoyée, si bien qu’un producteur ayant en FLAC un pack qu’il possède en WAV s’entendait dire qu’il ne le possédait pas.","changelog.ddf9187bb139":"⚠ La règle du propriétaire est inchangée : <strong>aucun octet d’échantillon ne passe entre deux pairs</strong> — seize octets d’empreinte et quatre nombres.","changelog.67c4f1f163e5":"Corrigé - une coupure Wi-Fi ne met plus fin à votre session de collaboration, 2026-09-09","changelog.658c8087a2ab":"Un paquet perdu ou un portable sortant de veille était traité comme le départ de l’autre personne. La connexion signale « disconnected » alors qu’elle essaie encore — un état explicitement transitoire qui se résout généralement de lui-même — et le sidecar coupait le lien dès le premier. Il revérifie désormais pendant huit secondes l’adresse dont il dispose, ce qui rend une brève coupure invisible. Toute coupure plus longue reste un vrai départ : la place, le pseudo et la couleur sont gardés deux minutes, comme avant.","changelog.b55b8659f982":"Corrigé - charger un instrument fait apparaître le clavier et ses boutons, 2026-09-09","changelog.0b543bd7a5ca":"Déposer un échantillon sur un générateur, ou en router un avec <code>Ctrl</code>+<code>Arrow</code>, donnait une voix à la partie — et la rangée de boutons qui la façonne n’apparaissait qu’après avoir changé d’onglet et être revenu, car les commandes de réverbération, de délai, de saturation et de hauteur lisaient une réponse périmée à « cette partie produit-elle déjà un son ? ». Charger un instrument ouvre désormais aussi le clavier à l’écran, pour avoir de quoi en jouer.","changelog.1af1ee74267d":"Modifié - deux comportements de batterie atteignent les artistes pour lesquels ils ont été conçus, 2026-09-09","changelog.ec4815846944":"Une caisse claire en comping et un backbeat joué sur un clap avaient tous deux été construits, et aucun n’était accessible — aucun artiste ne demandait l’un ou l’autre. Art Blakey fait désormais du comping, ce que décrit sa fiche de recherche ; Trina et Trick Daddy mettent le backbeat sur le clap, ce qui, selon leurs fiches, est la marque de la Miami bass.","changelog.6858345a1f88":"Corrigé - le même préréglage sonne désormais pareil deux fois, 2026-09-06","changelog.daafbdc5a835":"Écouter un préréglage donnait un son légèrement différent à chaque clic — jusqu’à <strong>quatre fois le niveau</strong> pour les larges nappes de texture désaccordées. Démarrer un nouveau son réinitialisait le délai et la réverbération et laissait tourner l’aléatoire de chaque voix, or cet aléatoire est à la fois l’endroit où un oscillateur commence son cycle <em>et</em> le bruit dont est fait un son de batterie, si bien que les voix d’une nappe s’annulaient d’une quantité différente à chaque lecture. Elles tirent désormais leur graine du préréglage : le même son deux fois est le même son, et les notes varient toujours entre elles.","changelog.3f7eb09bb886":"⚠ Deux préréglages étaient réellement trop faibles pour être prévisualisés une fois la mesure devenue fiable — <em>Pluck Coin</em> et <em>Frozen Cloud</em> — et tous deux sont légèrement remontés.","changelog.449f05332b7d":"Corrigé - plus aucun instrument n’est décentré, 2026-09-05","changelog.e606f1a76e95":"Certains sons étaient figés avec un <strong>offset DC</strong> — la forme d’onde décalée par rapport à la ligne centrale au lieu d’osciller autour. Il se lit comme du volume sur un vumètre et comme rien à l’oreille, mange de la marge et fait se comporter un mix bizarrement pour des raisons que rien à l’écran n’explique. <em>Current Pad</em> était le pire, à −0,26 de la pleine échelle, avec quarante lignes des Extensions partageant ce profil. Chaque synthé supprime cela en sortie ; Freally le fait désormais aussi.","changelog.a6132c39d808":"⚠ Une poignée de nappes sont plus faibles, et c’est le correctif qui fonctionne — une partie de leur niveau venait de l’offset qui poussait davantage le saturateur. Aucune n’a été retravaillée : elles déclenchaient une vérification de niveau qui les mesurait au cinquième d’une montée à laquelle elle accordait 1,25 seconde pour s’achever. Elle écoute désormais quatre secondes, comme le lecteur de prévisualisation.","changelog.a91d6c053bff":"Corrigé - les boutons, les touches et toutes les autres commandes à glisser, 2026-09-05","changelog.c585e5feb470":"Tourner un bouton sur la page <strong>Synth</strong> pouvait ne rien faire du tout : il s’allumait, prenait le focus, affichait un nombre, et le son ne changeait jamais.","changelog.8794dd5d5b82":"Chaque commande à glisser demande à l’OS de capturer le pointeur pendant toute la durée du geste, pour qu’un glissement survive au curseur qui s’éloigne du bouton — et cette demande était faite <em>avant</em> que la commande ne s’arme. Sur toute machine où elle était refusée, la commande ne commençait jamais à écouter et le geste était perdu. Douze commandes partageaient ce défaut : les boutons, les touches du clavier, la grille de batterie, le piano roll, la piste de vélocité, la règle, l’éditeur d’enveloppe, l’éditeur de pads, les rangées du kit, la bande de prévisualisation, le redimensionneur du panneau latéral et la frise du morceau. Elles s’arment désormais d’abord et demandent ensuite.","changelog.1ba8e646a9fb":"Corrigé - les pianos sonnent comme des pianos, 2026-09-05","changelog.e02d9461473c":"Chaque piano avait un bourdonnement au début au lieu d’une frappe de touche. Deux défauts, tous deux mesurés plutôt que devinés :","changelog.0f157fbd683f":"<strong>La note arrivait à plein volume et y restait.</strong> Une corde frappée décroît dès son tout premier instant ; celle-ci non — les cinq millisecondes suivantes étaient <em>plus fortes</em> que les premières, car la décroissance rapide de la corde était réglée à trois secondes et ne peut pas placer de coude près d’une attaque.","changelog.96ba7fca5dbd":"<strong>Il n’y avait presque pas d’harmoniques.</strong> Un piano à queue au do central portait un demi-pour-cent de son énergie au-dessus de 2 kHz et était presque une onde sinusoïdale ; la dixième harmonique disparaissait en soixante millisecondes et la trentième en quatorze.","changelog.85ae339fad0a":"Le marteau est désormais plus fort et plus brillant, plus brillant sur le piano à queue que sur le droit, ce qui fait la différence entre les deux mécaniques. Les cordes à l’unisson sont accordées plus près les unes des autres — l’ancien écart variait assez d’une note à l’autre pour s’entendre comme un vacillement.","changelog.7f16b5debe9e":"Corrigé - le bouton Lecture sous le navigateur de fichiers, 2026-09-05","changelog.032dc3a33890":"Le bouton Lecture sous le navigateur et celui à l’intérieur faisaient des choses différentes, et celui de l’extérieur avait tort : sur un fichier MIDI, il jouait le dernier <code>.wav</code> que vous aviez écouté, sous le nom du fichier MIDI. Les deux passent désormais par la même porte.","changelog.6e3d80e0d484":"Corrigé - Inverser vous montre le clip à l’envers, 2026-09-05","changelog.7fc0fa7a1923":"Activer <strong>Inverser</strong> changeait le son et laissait l’image telle quelle, si bien que la seule commande dont le rôle est d’être évidente ne montrait rien. La forme d’onde est dessinée en commençant par la fin quand l’inversion est active, la tête de lecture va toujours de gauche à droite, et cliquer sur une crête joue la crête cliquée.","changelog.a67a54c25c17":"Ajouté - le chat vocal sait trouver votre micro et vos haut-parleurs, 2026-09-05","changelog.10fcf618e62d":"La moitié vocale de la collaboration avait tout sauf le matériel : annuleur d’écho, noise gate, codec et tampon de gigue étaient tous construits et pilotés par rien. L’assistant de session liste désormais les micros et les sorties que votre machine signale, ouvre la paire que vous avez choisie, et les ferme dès que vous désactivez Voix — si bien que le voyant de votre interface s’éteint quand vous le décidez. Votre sortie est un choix distinct de votre micro, car moniteurs et casque sont deux choses différentes.","changelog.0772f73fd745":"⚠ Le chat vocal exige le périphérique à 48 000 Hz. Si le vôtre ne l’est pas, Freally nomme le périphérique et la fréquence plutôt que d’échouer en silence.","changelog.1ff4564ad0c5":"Corrigé - le marqueur de tête de lecture ne se fige plus quand la fenêtre est occupée, 2026-09-05","changelog.a38a827fadc1":"Faire glisser la barre de titre de la version autonome figeait la tête de lecture jusqu’à ce que vous lâchiez, puis elle sautait en avant — exactement comme si la lecture s’arrêtait puis reprenait. Ce n’était pas le cas ; le son jouait tout du long. Le marqueur demandait au plug-in où il en était trente fois par seconde et <em>attendait</em>, et déplacer une fenêtre sous Windows bloque la boucle de fenêtre de l’application, si bien que les réponses cessaient d’arriver alors que le thread audio ne manquait pas un temps. Il continue désormais d’avancer d’après le tempo entre les réponses et se corrige quand l’une d’elles arrive.","changelog.8360bb400211":"⚠ Le même gel pouvait se produire chaque fois que la fenêtre d’une DAW était occupée ; il ne s’agit donc pas seulement du glisser.","changelog.df274a80a110":"Ajouté - vos propres échantillons, sur votre propre étagère, 2026-09-05","changelog.10a7ad8818d9":"Indiquez à Freally MIDI Master les dossiers où vous rangez vos one-shots et il détermine lesquels peuvent être joués comme instruments. Appuyez sur <strong>Trouver des instruments dans mes dossiers</strong> dans Catégories ; il affiche sa progression et vous pouvez l’arrêter à tout moment. Un second passage sur des dossiers inchangés est instantané. Ce qu’il trouve va sur une étagère à vous, sous les quatre Extensions d’usine, à votre nom.","changelog.9d27db12ab2d":"⚠ Un échantillon faible est conservé — le faible volume est votre choix, et seul un fichier sans aucun son est refusé. Tout ce qui dépasse dix secondes est écarté : jouer un échantillon plus bas l’<em>étire</em>, donc une nappe de huit secondes jouée une octave plus bas tient seize secondes par note.","changelog.6209b0e7418a":"⚠ L’analyse nécessite le plug-in ou la version autonome. Un onglet de navigateur ne peut ouvrir qu’un dossier à la fois et l’oublie au rechargement : il n’a donc aucune bibliothèque à parcourir.","changelog.376464b49a86":"Ajouté - l’application demande comment nommer votre étagère, 2026-09-05","changelog.f7195bf33438":"La première fois que vous ouvrez Freally MIDI Master, juste après la licence, il demande comment votre étagère doit s’appeler et ne génère rien tant que vous n’avez pas répondu. Tout ce que vous enregistrez vit sous ce nom, et le changer renomme l’étagère — rien ne bouge et rien n’est perdu.","changelog.f38da5062167":"⚠ Si votre machine ne permet pas à l’application d’enregistrer le nom, elle le garde pour la session, le signale et vous laisse continuer. Rien n’est jamais bloqué par un fichier qu’elle n’a pas pu écrire.","changelog.bf9a5273bae3":"Ajouté - le panneau KIT vous dit quand un échantillon glisse, 2026-09-05","changelog.53f56fa197ef":"Déposez un riser ou une 808 qui glisse sur un pad mélodique et l’application y trouvait une note, avec assurance, puis jouait ce glissando sur chaque touche — chacune à un intervalle différent. Elle mesure désormais si l’échantillon <em>tient</em> sa hauteur et l’indique sous le pad : <strong>« Cet échantillon ne tient pas une seule hauteur : chaque touche jouera son glissando. »</strong> Elle vous prévient plutôt que de refuser le fichier : un glissando vaut toujours la peine d’être joué, ce n’est simplement pas un instrument.","changelog.74c665daca9f":"Ajouté - les chiffres derrière un batteur humain, 2026-09-05","changelog.6f4d1b6a2a74":"<code>data/humanize/groove.json</code> contient ce que font réellement 1 150 vraies performances de batterie — par style un ratio de swing, et par élément la distance qui le sépare du reste du kit, son degré de flottement, et ce que mesurent une ghost note, un coup principal et un accent. <strong>Rien de ce que vous avez créé ne change</strong> : aucun artiste livré n’utilise les nouveaux chiffres, donc chaque graine reconstruit le beat qu’elle reconstruisait avant.","changelog.6ad4570e7118":"⚠ Une découverte est audible : la pédale de charleston d’un batteur arrive 7 à 20 ms avant le reste du kit dans tous les styles mesurés. Et une chose est délibérément absente — le flottement d’un batteur est d’environ 15 ms, jazz ou punk, donc il n’y a pas de table de souplesse par genre, car il n’existe pas de souplesse par genre.","changelog.21279277c064":"Ajouté - entendez un style pendant que vous le construisez, 2026-09-05","changelog.95e2355db08d":"Avec le transport en marche, l’éditeur de style joue ce que vous construisez au fur et à mesure — déplacez le curseur de swing ou changez le placement de la caisse claire et la boucle suivante est le style que vous venez de décrire. Rien n’est enregistré pendant ce temps, et votre propre prise revient dès que vous fermez l’éditeur, que vous ayez enregistré le style ou non. Écouter est un son, pas une modification.","changelog.23f920ae884b":"Ajouté - le téléphone peut demander un MP3 au poste de travail, 2026-09-04","changelog.e2666ce60865":"MixSir a toujours pu enregistrer sa propre lecture en WebM, ce qui fonctionne partout et a un défaut que rien ne pouvait corriger : il enregistre en <strong>temps réel</strong>, donc un morceau de trois minutes prenait trois minutes. Sur le même réseau que votre poste, vous pouvez désormais simplement télécharger un <strong>MP3</strong>, encodé hors temps réel sur la machine qui a l’audio. Chaque stem a son propre bouton, si bien qu’envoyer une ligne de basse à quelqu’un se fait d’une touche au lieu d’un WAV de 40 Mo.","changelog.a0fab848af1f":"⛔ Trois fichiers, trois sens, nommés sous les boutons : <em>Save your mix</em> rend la balance que vous venez de régler, sur le téléphone ; <em>Save small</em> est cette balance en WebM, en temps réel ; <em>Desk mix — MP3</em> est la prise <strong>telle que générée</strong>, chaque fader à l’unité. Les confondre jetterait discrètement le mix sur lequel vous avez passé dix minutes. Un stem est l’exception, et c’est pourquoi c’est le meilleur des trois : un stem à l’unité <em>est</em> le stem.","changelog.a33866df627b":"⚠ Rien n’a été ajouté au plug-in — l’encodeur vit dans le programme compagnon derrière son propre feature flag, et un contrôle échoue si cela cesse d’être vrai.","changelog.fef58795ee93":"Modifié - le garde-fou de nouveauté compare à 47 mélodies au lieu de 7, 2026-09-04","changelog.cada7f45de77":"Chaque mélodie que le générateur écrit reçoit une empreinte de sa <em>forme</em> — la suite des intervalles et des écarts entre les attaques — et est comparée à une table intégrée avant que vous ne l’entendiez ; une correspondance est jetée et tirée à nouveau. Cela a été livré avec sept mélodies du domaine public et 104 empreintes, soit un interrupteur qui fonctionne avec presque rien derrière. La table contient désormais <strong>47 mélodies et 834 empreintes</strong>, toujours sous les cinq millisecondes promises.","changelog.43f8d897f696":"⛔ <strong>Ce que ce n’est pas.</strong> Chaque mélodie de la table est du domaine public, définitivement : filtrer contre un hook commercial voudrait dire dériver le contour de ce hook, et une liste de contours <em>est</em> une donnée de notes — la seule chose que ce produit ne doit jamais contenir. Le garde-fou attrape une citation accidentelle d’une mélodie connue. Ce n’est <strong>pas</strong> la raison pour laquelle le résultat est original ; cette raison, c’est un moteur fondé sur des règles, sans aucun enregistrement nulle part dans la chaîne.","changelog.239a6df00f04":"Ajouté - quatre packs Extension d’usine, 1 400 nouveaux instruments transposables, 2026-09-04","changelog.0790681bb3a3":"<strong>La bibliothèque passe de 248 à 1 648 instruments, et de 410 688 préréglages à 2 729 088</strong> — toujours sans un seul fichier sur le disque, car chaque préréglage est calculé à partir de son adresse. Ils arrivent sous forme de quatre nouvelles étagères plutôt que d’être versés dans les dossiers que vous connaissez : analogique soustractif ; FM et premiers numériques ; texture, bande et poussière ; et voix et corps d’instruments du monde, plus les deux registres que rien d’autre n’utilise.","changelog.fb5ae337c7b0":"<strong>Ils sonnent comme des machines, pas comme des préréglages</strong>, et le premier jet n’avait aucune des quatre choses qui produisent cet effet : les oscillateurs tournent <strong>librement</strong>, donc deux notes ne commencent jamais à l’identique ; le filtre <strong>suit le clavier</strong> ; <strong>la vélocité ouvre le filtre</strong> au lieu de seulement monter le niveau, ce qui est le signe le plus courant d’un instrument synthétisé ; et un second LFO ajoute un ou deux cents de dérive à la hauteur — pas un vibrato, juste le patch qui vit.","changelog.23d9f8efe0a6":"Rien ne sonne comme autre chose, et c’est mesuré : le contrôle existant rend chaque instrument à chaque variation dans les 69 genres et échoue si deux d’entre eux tombent sur la même empreinte.","changelog.63aed5e7b3ac":"Ajouté — Freally MIDI Master tourne dans un navigateur, 2026-09-03","changelog.6392d72ebb78":"<strong>Toute l’application, dans un onglet, sans rien à installer</strong> — pas une démo, et pas une version réduite. Le navigateur exécute <strong>la même crate que le plug-in</strong>, compilée en WebAssembly, si bien qu’un beat généré dans un onglet et un beat généré dans votre DAW sont les mêmes octets. C’est un contrôle plutôt qu’une promesse : <code>web_parity</code> génère des deux côtés et compare le <code>.mid</code> octet par octet, refus compris.","changelog.29825d1f51d3":"⛔ <strong>Deux choses qu’un navigateur ne peut pas faire</strong>, dites avant que vous ne le découvriez à vos dépens : il n’y a pas de <strong>Suivre la DAW</strong>, car un onglet n’a pas de transport d’hôte, et un clip ne peut pas être déposé directement sur une piste de DAW. Les deux limites apparaissent dans l’application et dans Paramètres → À propos.","changelog.db4a975527be":"La bibliothèque arrive entière dans l’onglet — <strong>410 688 préréglages</strong> — et ne coûte rien à livrer, car chacun est calculé plutôt que stocké. Après une visite, l’onglet génère avec le réseau coupé, et il s’installe dans sa propre fenêtre. <strong>La charte hors ligne est amendée dans le même changement</strong> : la page est <em>livrée</em> par le réseau, la génération se fait sur votre machine, et rien de ce que vous créez n’est jamais envoyé.","changelog.7fc622405ce4":"<strong>Les portes de génération sont passées dans <code>engine</code>.</strong> <code>generate</code>, <code>generate_song</code> et <code>reroll_section</code> formaient la moitié avant de <code>plugin/src/bridge.rs</code> ; elles sont désormais <code>engine::compose</code>, appelées par les deux surfaces, si bien que l’onglet et la DAW ne peuvent pas diverger.","changelog.24935964d5ea":"<strong>La bibliothèque d’instruments est sa propre crate.</strong> <code>freally-library</code> contient les préréglages, la taxonomie, les voix par partie, l’encodeur WAV et le kit de batterie. Le plug-in la réexporte là où elle vivait.","changelog.acd41991926e":"<strong>Deux nouveaux contrôles dans les deux exécuteurs de CI locale</strong> : la cible wasm se compile, et l’onglet est piloté de bout en bout dans un vrai navigateur, aux tailles bureau et téléphone.","changelog.4aec523a2a62":"Ajouté — les instruments sonnent désormais comme des disques, 2026-09-02","changelog.6d0a65060c37":"Les instruments d’usine ont été réaccordés sur ce que mesure un échantillon professionnel — combien de temps sonne un charleston, où se situe le poids d’un kick, comment décroît une mailloche. Les producteurs passaient outre plusieurs d’entre eux, et les chiffres disent pourquoi : les charlestons de boîte à rythmes étaient <strong>trois à cinq fois plus courts qu’un vrai</strong>, si bien qu’ils sonnaient comme des clics au lieu de charlestons.","changelog.b042e5f2df6f":"<strong>Un bug sous quatre moteurs était le vrai sujet.</strong> <code>decay</code> sur les moteurs modal, percussion et percussions du monde, et <code>length</code> sur impact, sont chacun documentés comme un <em>multiplicateur</em> dont la valeur neutre est 1,0 — et chacun était plafonné à 1,0. <strong>Aucun son de la bibliothèque ne pouvait sonner plus longtemps que l’instrument réel.</strong> Le marimba mesurait 250 ms contre une référence de 510 ms et ne bougeait pas, quelle que soit la force avec laquelle le modèle poussait. Les quatre sont corrigés, avec un contrôle qui échoue si le plafond revient.","changelog.ef8652a0758c":"<strong>248 instruments</strong> désormais, contre 225, pour <strong>410 688 préréglages</strong>. La modulation de hauteur se trouve facilement : 91 y répondent et 157 non, la bibliothèque filtre selon ce critère, et chaque ligne qui l’a porte une marque.","changelog.3632677bb11b":"Ajouté — 5 085 boucles MIDI dans les Packs d’usine, 2026-09-02","changelog.81f74a7b5aa1":"Parcourez et écoutez des boucles de batterie, de percussions, de basse, d’accords, de mélodie et de contre-mélodie au lieu de générer, écouter et générer encore. <strong>Chacune a été écrite par les propres générateurs de cette application à partir de ses propres modèles de style</strong> — neuf mégaoctets de notes, pas un gigaoctet d’enregistrements de quelqu’un d’autre. Choisir une boucle la joue et la liste reste à l’écran, si bien qu’on peut parcourir un dossier d’un bout à l’autre.","changelog.00e23d8a58a2":"<strong>Deux choses devaient être corrigées d’abord.</strong> Le navigateur dessinait les dossiers et cliquer sur une ligne ne faisait rien — le moteur de rendu et le lecteur de fichiers étaient tous deux terminés et aucun n’était branché. Et une fois branchés, chaque boucle était lue comme une boucle de <em>batterie</em> quel que soit le dossier, ce qui est pire qu’il n’y paraît : une ligne de basse se trouve exactement là où vivent le kick, la caisse claire, le clap et les charlestons sur la table standard, si bien qu’elle se rejouait comme un beat parfaitement convaincant qui n’était pas le fichier.","changelog.c666d6acd7c9":"Ajouté — 189 artistes et producteurs de plus, 2026-09-02","changelog.b172c11f2b00":"Des bâtisseurs de riddims dancehall, de l’amapiano, du Jersey club, de la drum &amp; bass, de la house, du reggaeton et les scènes de Detroit et du Michigan. <strong>2 413 modèles de style</strong> sont désormais livrés.","changelog.1f6f98bb4f11":"Corrigé — une touche maintenue ne s’arrêtait jamais, 2026-09-02","changelog.efe64f0af95b":"Appuyer sur une touche à côté du piano roll d’un générateur faisait sonner une note qui ne finissait jamais. Relâcher la souris l’arrête désormais, tout comme glisser ailleurs, la perte du focus de la fenêtre ou la fermeture du panneau. Les touches sont aussi correctement étiquetées : texte blanc sur les touches noires, noir sur les blanches, sur les deux claviers.","changelog.0e9f1cb9b77e":"Corrigé — le navigateur de boucles aurait pu être livré vide, 2026-09-02","changelog.f2656c4e7099":"Un changement qui empêchait le pack de boucles d’être compilé deux fois dans l’application — neuf mégaoctets, dans chaque build — l’empêchait aussi d’être trouvé tout court. Le navigateur aurait dessiné une arborescence vide. Attrapé par le test qui compte les fichiers plutôt que de faire confiance au code.","changelog.203799973680":"Modifié — la suite de tests tourne en une fraction du temps, 2026-09-02","changelog.f050d1cd9b2a":"Rien qu’un producteur voie, mais c’est la différence entre attraper une erreur en quelques minutes et en une heure. Un contrôle régénérait la mesure de chaque modèle une fois pour chaque autre modèle auquel il était comparé — <strong>de 435 secondes à 1</strong>. Les suites de variété utilisent désormais tous les cœurs : mélodie <strong>576 s → 60 s</strong>, contre-mélodie <strong>800 s → 66 s</strong>. L’exécuteur de CI locale place aussi ses vérifications bon marché en premier, si bien qu’une erreur de formatage est signalée en quelques secondes plutôt qu’après toute la suite Rust.","changelog.fc2bc79afd01":"Corrigé — le contrôle de variété couvrait un genre sur soixante-neuf, 2026-08-31","changelog.909b99ff0cc9":"Le contrôle ne tournait que sur House ; Trap avait des sub-basses qui sonnaient de façon identique et il ne trouvait rien, car il ne regardait nulle part près d’elles. Il y a désormais <strong>un <code>#[test]</code> par genre</strong> — 69 au total, qui balaient <strong>372 600 préréglages</strong>. Les faire passer au vert a pris quatre tours :","changelog.128cc96e56d9":"<strong>Huit paires d’instruments partageaient une variante de modèle aux paramètres identiques</strong> — <code>Bell</code>/<code>ChurchBell</code>, <code>GrandPiano</code>/<code>AcousticPiano</code> entre autres. Ils n’étaient pas similaires, c’était le même patch sous deux noms, et chacun est désormais séparé par ce qui le distingue réellement.","changelog.b445820a134e":"<strong>Élargir le jitter était le mauvais réflexe, trois fois.</strong> Cela a fait passer de 56 genres en échec à 13, et les 13 derniers étaient deux tirages tombant proches par hasard — ce que davantage de jitter rend moins probable et jamais impossible. Chaque variation prend désormais sa propre <strong>tranche</strong> de la plage saillante de l’instrument.","changelog.34ce292c4fde":"⚠ Le contrôle a une résolution assez fine pour attraper ce qui a été signalé — les vingt-quatre de <code>Sub808</code> corrélaient à 1,0000 — et ne tranche pas sur le fait que deux marimbas audiblement différents diffèrent <em>assez</em>.","changelog.e0c180b1af50":"Corrigé — un instrument sonnait pareil dans les 69 genres, 2026-08-31","changelog.36341f1261ab":"Mesuré, et sans appel : le préréglage signature de <code>Sub808</code> corrélait à <strong>0,9938</strong> entre Trap et House, et un piano acoustique allait de <strong>0,974 à 0,997</strong> sur tout le répertoire. La branche modélisée de <code>apply_genre</code> ne pouvait atteindre que <code>filter.cutoff</code>, <code>filter.drive</code> et la chaîne d’effets — un filtre qu’un modèle physique utilise à peine et une chaîne placée <em>après</em> lui — si bien que rien de ce qu’elle faisait ne changeait la façon dont un instrument était frappé, frotté ou soufflé.","changelog.43cbc2d5c9d0":"<code>colour_modelled</code> projette le genre sur les paramètres <strong>propres</strong> à chaque moteur. La 808, c’est le decay et le glide : une 808 trap sonne une mesure ou plus et glisse vers la note, un kick house est serré et ne glisse pas, et les profils le portaient déjà sous <code>weight</code> — Trap <strong>0,88</strong> contre House <strong>0,60</strong>. La dureté du marteau, c’est le piano, et c’est ce dont parle la littérature sur l’harmonisation des pianos : Jazz se situe à <code>drive</code> 0,10 contre 0,70 pour Metal. Un genre plus brillant monte les tirettes aiguës d’un Hammond ; un genre plus dur pince une corde plus près du chevalet.","changelog.5e368038fb52":"⚠ Chaque poussée est construite à partir de plus d’une dimension de profil : une seule dimension à ±0,30 reste en dessous de ce qu’un auditeur ou une empreinte peut distinguer.","changelog.151c57cb8bd1":"Ajouté — un contrôle sur l’axe des genres, et pourquoi il compte plutôt qu’il n’interdit","changelog.0976e9520f58":"<code>an_instrument_sounds_different_in_every_genre</code> rend le préréglage signature de chaque instrument dans les 69 genres — 15 525 rendus — et exige que chacun sonne distinct dans au moins <strong>62</strong> d’entre eux.","changelog.171a63bd1519":"⛔ <strong>Un décompte, pas une interdiction par paire.</strong> Exiger que les 2 346 paires de genres diffèrent échouait sur <code>Jungle == Breakbeat</code> et <code>Cinematic == Downtempo</code>, des genres qui partagent réellement un caractère — et fabriquer une différence entre eux pour faire passer un test au vert est exactement l’erreur derrière 396 modèles d’artistes annulés. Ce qui était demandé, c’est qu’un instrument ne soit pas <strong>un seul</strong> son portant 69 étiquettes, et un plancher sur le décompte de sons distincts le dit sans rien inventer.","changelog.a04ef14ec8d1":"Corrigé — une écoute était rendue à partir de zéro à chaque fois, 2026-08-31","changelog.642ec6d63dec":"⛔ <strong>Cette bibliothèque ne peut pas être pré-calculée, et le chiffre explique pourquoi.</strong> 225 instruments × 69 genres × 24 variations, cela fait <strong>372 600</strong> préréglages ; à quatre secondes de mono 22 kHz, cela fait <strong>61 Go</strong>, et au format flottant 48 kHz que lit le lecteur, 266 Go. Un clip est donc rendu une fois, puis se comporte comme un clip pré-calculé : <strong>23,79 ms en moyenne, 42,5 ms au pire</strong> pour le rendu, contre ~0,1 ms pour rendre une copie gardée en mémoire. Trente-deux clips, environ 24 Mo — monter et descendre une liste avec les flèches revisite la même poignée de lignes, si bien qu’un petit cache attrape presque chaque répétition.","changelog.10eb1736b8c9":"Ajouté — ↑/↓ parcourent la bibliothèque et jouent ce sur quoi elles tombent, 2026-08-31","changelog.43b3eb09cc47":"Le même geste que l’arborescence de fichiers a depuis août, et la bibliothèque était la seule liste du panneau où il fallait cliquer sur chaque ligne. ⚠ Lié à la liste plutôt qu’à la fenêtre, si bien qu’il ne se déclenche jamais pendant que le piano roll utilise les mêmes touches pour décaler des notes.","changelog.6a4614d116ae":"Corrigé — la moitié de la bibliothèque de préréglages était un seul son répété, 2026-08-31","changelog.0f63f6bd0158":"⛔⛔ **<code>modelled_defaults</code> promettait <em>« une touche d’humanisation par préréglage »</em> au-dessus de <code>let _ = rng;</code>** — un commentaire décrivant un comportement que personne n’avait écrit. La relance qu’il appelait ne sait faire varier qu’une <em>table d’ondes</em>, ce qu’aucun modèle physique ne lit. Mesurées, les variations 0 à 5 de <code>Sub808</code> étaient <strong>identiques à l’octet près, corrélation 1,0000</strong>, tandis que la table d’ondes du patch changeait consciencieusement. Environ la moitié de la bibliothèque est modélisée, donc la moitié des 24 variations par combinaison étaient un seul son vingt-quatre fois. <code>randomize_modelled</code> déplace les paramètres <strong>propres</strong> à chaque moteur, avec un jitter autour des valeurs par défaut du type plutôt qu’une relance, car une variation est une autre <em>prise</em> d’un instrument, pas un autre instrument.","changelog.aafb4b3e7173":"⛔ <strong>Une sub est une sinusoïde, et la remplacer n’est pas une variation.</strong> La relance du pack la remplaçait par une dent de scie et empilait neuf voix désaccordées ; à 32 Hz, cela donne des arêtes, des battements et de l’aliasing — exactement le grésillement signalé.","changelog.99d2732af475":"⛔ <strong>Slap Bass et Pluck Bass partageaient une branche</strong> et étaient le même patch sous deux noms. Les deux sont désormais une corde de basse électrique, séparées là où un musicien les sépare.","changelog.c9eec0781f88":"Ajouté — un contrôle qui écoute les 5 400 préréglages d’un genre, 2026-08-31","changelog.d954c7fae943":"<code>no_two_presets_in_a_genre_render_the_same_sound</code> rend chaque instrument × variation dans House — 225 × 24 — prend l’empreinte de chacun par la longueur, le niveau, la pente d’attaque et huit rapports harmoniques, et vérifie qu’aucun ne se percute. 24 secondes.","changelog.f1e878d4342a":"⛔ <strong>Il doit écouter, pas lire le patch</strong> : les variations de la 808 Sub différaient sur le papier, si bien qu’une empreinte prise sur <code>Patch</code> aurait laissé passer les vingt-quatre. Il a été vérifié <em>contre</em> le bug — avec <code>randomize_modelled</code> désactivé, il échoue immédiatement et nomme les paires en collision.","changelog.e32c895d315b":"Corrigé — la prévisualisation ne promettait pas ce que jouait le générateur, 2026-08-31","changelog.d0db0dc79e31":"Le <strong>patch</strong> n’a jamais été le problème : l’écoute et le générateur construisent le même préréglage. Ce qui divergeait, c’était tout ce qui s’empile par-dessus — <code>PartSound</code> porte la réverbération, le délai, la saturation, la modulation de hauteur, le gain, le panoramique et une ADSR ; le générateur appliquait les sept et l’écoute aucun, si bien qu’une partie portant encore la réverbération du dernier instrument faisait jouer le nouveau à travers elle. Choisir un instrument réinitialise désormais le façonnage, via une seule porte par laquelle passent à la fois le bouton <code>Use in …</code> et <code>Ctrl</code>+→.","changelog.25007f86466f":"⚠ Délibérément différent de la règle au-dessus dans le navigateur, qui lit d’abord le son stocké d’une partie pour que le simple fait de <em>toucher</em> une partie ne puisse pas effacer vos modifications. Choisir un nouvel instrument est un autre acte.","changelog.89099f78768b":"Modifié — la bibliothèque s’ouvre sur Trap, et ses genres se lisent par ordre alphabétique, 2026-08-31","changelog.49d670380403":"⚠ <code>genre</code> est un index dans une liste qui n’existe pas encore quand la valeur par défaut du store est écrite, si bien que <code>0</code> n’a jamais désigné un genre — il désignait celui que la taxonomie listait en premier. Il passe à Trap quand la taxonomie arrive, et seulement depuis un <code>0</code> intact. Le tri porte sur ce qui est dessiné, jamais sur ce qui est stocké : la bibliothèque découpe selon l’index de la taxonomie, donc trier la liste elle-même redirigerait silencieusement chaque adresse.","changelog.28cf77745a93":"⚠ Le mock répondait <code>Genre 1 … Genre 69</code> — déjà alphabétique et sans Trap, il ne pouvait donc tester aucune des deux règles. Il répond désormais avec les vrais noms.","changelog.07bc5a7db520":"Corrigé — chaque instrument s’écoutait comme le même bip de moins d’une seconde, 2026-08-31","changelog.3de906154cb6":"Le symptôme était réel et ce n’était pas la synthèse : mesuré par le vrai chemin de rendu, le centroïde spectral d’un piano acoustique se situe à 1,32 contre 2,87 pour un clavinet, et le routage est correct.","changelog.b68a797d6d3c":"⛔⛔ <strong>Ce qu’ils partageaient, c’était la forme.</strong> L’écoute empruntait un moteur de rendu qui dimensionne un <strong>one-shot pour un sampler</strong> — un gate de 0,6 s et une queue de 1,4 s. Une demi-seconde suffit pour entendre un marimba et pas du tout pour entendre un orgue, un violon ou une nappe, les familles dont le caractère <em>est</em> ce qui se passe après l’attaque — si bien que les 225 revenaient comme des bips de moins d’une seconde, à la même hauteur et avec à peu près la même crête.","changelog.c87553afd32f":"L’écoute tient désormais sa propre note, 1,5 s + 2,5 s : des durées qui étaient toutes entre 0,6 et 1,0 s sont de 0,64 s pour un clavinet et de 1,84 à 1,91 s pour un orgue. ⚠ Un instrument frappé ne paie rien, puisqu’il est coupé au seuil de silence.","changelog.6fffbb4dd6a9":"Corrigé — le lecteur de prévisualisation ne montrait jamais un instrument en train de jouer, 2026-08-31","changelog.06945748a71f":"L’interrogation de la tête de lecture demandait <code>selected === null</code> — mais <code>selected</code> désigne un <strong>fichier</strong>, et écouter un instrument le vide exprès pour que le panneau MIDI cesse de décrire un <code>.mid</code> que vous n’entendez plus. Un instrument écouté se lisait donc comme « rien ne joue » : pas de tête de lecture, pas de temps écoulé, pas de déplacement, pendant tout le clip. Elle demande désormais si une <strong>forme d’onde</strong> est chargée, ce qui est vrai pour les deux chemins.","changelog.bfe82ac019ab":"Corrigé — chaque génération dans la version autonome sortait à 120 BPM, 2026-08-31","changelog.e1391ea65a06":"⛔ <strong>La version autonome de nih-plug annonce un tempo, et c’est sa valeur <code>--tempo</code> par défaut de 120.</strong> L’en-tête du fichier lui-même dit qu’il n’y a rien <em>sur quoi</em> se synchroniser, et le transport disait 120 à chaque bloc malgré tout — si bien que la synchronisation automatique sans tempo fixé devenait un forçage à 120 qui l’emportait sur chaque artiste du répertoire : suicideboys écrit à 125–160 et générait à 120, Drake à 130–150 et générait à 120.","changelog.5d84da78d405":"Une ligne suffit à le corriger : le tempo de l’hôte fait autorité par défaut, car le tempo d’une DAW ne doit jamais être remis en question, et la version autonome l’efface <strong>sauf si l’utilisateur a lui-même indiqué un tempo</strong> avec <code>--tempo</code>, auquel cas c’est exactement ce qu’il a demandé.","changelog.d7a7889636c7":"Modifié — l’inspecteur de style a quitté le panneau gauche, 2026-08-31","changelog.df3b5905432c":"Le panneau en bas à gauche affiche désormais le nom, le genre, les gammes et les tempos du style, et rien d’autre — ce que <code>ArtistPane</code> dessinait déjà. Le déversement de paramètres en dessous a disparu ; embellir deux fois ses libellés ne répondait pas à la plainte, car ce sont les paramètres eux-mêmes dont on ne voulait pas.","changelog.95bc4d0e3982":"⚠ <code>StyleInspector</code> est conservé, démonté, pour qu’une seule ligne suffise à le restaurer — et avec lui partent les forçages par paramètre et son propre « Enregistrer comme mon style ». La boîte de dialogue de l’éditeur de style enregistre toujours un style à vous.","changelog.d0654c4b85c2":"Corrigé — cliquer sur un instrument pour l’entendre construisait aussi son patch, 2026-08-31","changelog.4d2ba450de39":"Une ligne de la bibliothèque appelait <code>select</code>, qui construit le patch en Rust <strong>et</strong> recharge la page synthé — deux allers-retours par ligne, payés par quelqu’un qui ne faisait qu’écouter une liste. L’écoute n’a jamais eu besoin ni de l’un ni de l’autre. Une ligne se contente désormais d’écouter et de surligner, si bien qu’un instrument atteint un générateur par exactement un geste : le bouton <code>Use in …</code> ou <code>Ctrl</code>+→.","changelog.bc2c85aa41fb":"⛔ Et ce bouton atterrit désormais là où les lignes l’annoncent. Il lisait <code>activeTab</code> alors que les lignes lisaient <code>targetPart</code>, qui diffèrent sur la page SYNTH — si bien que le bouton nommait un générateur et la liste à côté un autre. Il <strong>charge</strong> aussi le patch désormais ; sans cela, vous entendiez l’ancien instrument jusqu’à la génération suivante.","changelog.8d96a9b23a8a":"Corrigé — une génération pouvait utiliser une gamme dans laquelle l’artiste n’écrit jamais, 2026-08-30","changelog.0aa78e305fb2":"Le moteur tire déjà une gamme non fixée dans la propre liste du modèle, donc le trou, c’était la <strong>valeur fixée</strong> : elle survit à un changement d’artiste par conception, et rien ne vérifiait si le nouvel artiste écrit dans cette gamme. Choisir la pentatonique mineure sur la trap puis passer à UK Drill générait de la drill dans un mode que la drill n’utilise pas — et la puce facilitait cela, en proposant les <strong>41</strong> modes que connaît le moteur, dont la trap n’en écrit que quatre. La puce propose désormais les gammes propres à l’artiste, et un changement d’artiste <strong>abandonne</strong> une valeur fixée que le nouvel artiste n’écrit pas.","changelog.8f482a9b2c0b":"⚠ Abandonnée plutôt que remplacée, alors que le tempo à côté est borné : une plage a une valeur légale la plus proche, un ensemble non. Il n’y a pas de mode « le plus proche » du phrygien, et en inventer un reviendrait à laisser l’application choisir le son d’un artiste. La puce de tonalité n’est pas touchée — une tonalité, c’est une transposition, alors qu’un mode est le caractère lui-même.","changelog.2f2d6d4a01f2":"Modifié — « N’écrit pas » revient dans le panneau de l’artiste, 2026-08-30","changelog.7983a70d1982":"C’est la moitié qui évite le silence : les générateurs de basse, d’accords, de mélodie et de contre-mélodie renvoient chacun une piste <em>vide</em> quand le modèle n’a écrit aucun bloc, si bien qu’un artiste qui n’écrit pas de ligne de basse répond à Générer sur cet onglet par rien du tout.","changelog.4e9d74d07396":"⚠ Seulement la moitié négative. « Écrit … » est une liste que l’on peut déduire des onglets ; « N’écrit pas … » est celle qui change ce que vous faites ensuite, et elle ne s’affiche que lorsque quelque chose manque.","changelog.3ebd75dbc890":"Corrigé — la graine chevauchait le panneau STYLE, 2026-08-30","changelog.60812270f2e2":"<code>.stage__controls</code> fait 740 px intrinsèques et était en <code>nowrap</code> avec <code>flex-shrink: 0</code> sur chaque enfant — un objet inamovible dans une piste <code>1fr</code> entre deux panneaux que vous pouvez faire glisser jusqu’à 560 px chacun. Un élément trop grand dans un conteneur flex en colonne déborde vers le <em>début</em>, si bien qu’il se peignait vers la gauche par-dessus le panneau.","changelog.3d60f1aa0052":"⛔ <code>SeedChip.css</code> avait déjà résolu la moitié du problème et se faisait écraser : le champ de graine est <code>flex: 1 1 20ch</code> avec <code>min-width: 0</code> précisément pour pouvoir rendre un caractère, et le <code>flex-shrink: 0</code> général un niveau au-dessus faisait qu’on ne le lui demandait jamais. La graine demande désormais <strong>10ch et grandit</strong>, car flexbox choisit les retours à la ligne à partir de la base avant tout rétrécissement. La rangée passe à la ligne en dernier recours, ce qu’elle ne faisait jamais avant.","changelog.d69262d1a787":"Modifié — le panneau de l’artiste dit trois choses, 2026-08-30","changelog.843ac4d32d6d":"Genres, gammes et plage de tempo — et <strong>toutes</strong> les gammes, là où il affichait la première. Un artiste qui n’écrit qu’en mineur naturel et un autre qui passe du mineur au dorien et à la pentatonique mineure ne s’utilisent pas de la même façon, et une seule entrée ne permet pas de les distinguer.","changelog.150a5f8a6f30":"⛔ Ce qui a été retiré, nommé pour ne pas être restauré par accident : l’époque, la première tonalité, la mention half-time, les humeurs, et Écrit / N’écrit pas. Cela supprime aussi une contradiction que portait ce panneau — il revendiquait Basse pour les 360 modèles dont la 808 <em>est</em> la ligne de basse, alors que l’onglet Basse les refusait.","changelog.db7b20c296bf":"Corrigé — Drake générait à 73 BPM, 2026-08-30","changelog.e6fd0aee8b1e":"Drake écrit à 130–150. Un tempo fixé survit à un changement d’artiste par conception et n’était borné qu’aux 20–999 d’Ableton, si bien qu’un 73 apporté d’un autre artiste restait 73. La borne vit désormais dans la commande que vous regardez, et un changement d’artiste ramène un tempo fixé apporté dans la plage du nouvel artiste — borné, pas effacé, car quelqu’un qui a demandé le haut de la plage d’un artiste veut le haut de la plage du suivant.","changelog.5d6b18a3616d":"⛔ Cela a d’abord été tenté deux couches plus bas, et les tests ont rejeté les deux essais. Dans le setter du store, le champ de tempo fixe une valeur à <em>chaque frappe</em> et ne borne qu’à la perte du focus — sinon taper « 5 » en route vers « 50 » serait corrigé sous le curseur. Dans le moteur, <code>reroll_section</code> fait passer le tempo <strong>de l’enregistrement</strong> par la même fonction, si bien que la borne faisait descendre un morceau à 155 jusqu’à 145, une section à la fois.","changelog.7831fdaa78c2":"Corrigé — les instruments, pour chaque modèle plutôt que pour quelques-uns, 2026-08-30","changelog.6d061d82240b":"2 224 modèles, et seule la mélodie s’était jamais vu demander ce qu’elle était. Les trois autres parties venaient d’une présélection par genre qui n’avait rien lu du modèle. Chaque partie répond désormais depuis son propre bloc :","changelog.32d6056dcb8e":"<strong>Contre-mélodie.</strong> <code>styles</code> est écrit sur <strong>1 876</strong> modèles et ne disait rien du son jusqu’à aujourd’hui. ⛔ Un écho à l’octave reçoit en réponse l’instrument de la mélodie elle-même, car c’est ce qu’<em>est</em> un écho à l’octave.","changelog.4d54431ef084":"<strong>Accords.</strong> 696 modèles sont en septième de dominante, ce qui appelle des claviers et non une nappe en dent de scie ; un <code>vamp</code>, c’est quelqu’un qui fait du comping, et ce ne peut pas être une nappe.","changelog.23468091c213":"<strong>Basse.</strong> ⛔ <strong>Aucun instrument de basse</strong> pour les <strong>360</strong> modèles dont la 808 est la ligne de basse, car le moteur refuse cette partie précisément pour eux. Découvert sous la forme d’une Pluck Bass sur $uicideboy$.","changelog.c1557e2ef5e3":"⚠ La contre-mélodie a eu sa propre étagère parce qu’elle partageait celle de la mélodie, et aucune liste de leads ne contenait une nappe, une section de cordes ou un chœur — si bien que 655 modèles disant <em>« ma contre-mélodie est tenue »</em> recevaient en réponse un Saw Lead.","changelog.3eb279716ce7":"Corrigé — 120 BPM et 73 BPM sonnaient exactement pareil, 2026-08-30","changelog.20ba9ed93269":"<code>Schedule::arm</code> place chaque note d’après le tempo auquel la prise a été <strong>générée</strong>, et rien ne réarmait quand le nombre changeait : la puce bougeait, le Générer suivant l’utilisait, et tout ce qui était déjà chargé continuait de jouer à l’ancien tempo.","changelog.be97e25d3228":"⛔ Un tempo est une horloge, pas un réglage de génération. Les notes ne bougent pas ; l’horloge, si, ce que fait une DAW quand vous faites glisser son tempo. Le même réarmement répond dans l’autre sens — avec la synchronisation automatique activée, faire glisser le tempo du projet laissait auparavant le plug-in jouer au tempo auquel la prise avait été faite.","changelog.3b643d7c2f3d":"Corrigé — trois affichages et une barre de titre, 2026-08-30","changelog.97cc14c61e0e":"<strong>L’inspecteur de style était le fichier JSON avec une feuille de style dessus.</strong> Retirer <code>$schema</code> laissait trente lignes commençant chacune par <code>arrangement.</code>, la moitié utile de chaque chemin à la fin, défilant latéralement hors d’un panneau étroit. Le bloc est désormais un titre et la ligne se lit comme des mots — <code>Section bars › Hook</code>. ⚠ La <strong>valeur</strong> n’est pas touchée : embellir <code>[4,8]</code> en « 4 ou 8 » ferait mentir un champ modifiable sur ce qu’il accepte.","changelog.0affc50612cd":"<strong>La ligne d’état dit à qui appartient le son</strong> — <em>« Instrument d’origine : Tambourine »</em>, <em>« Votre one shot : 808long.wav »</em> — ce dont a besoin quelqu’un qui décide de ce qu’il peut publier.","changelog.469d7247448c":"<strong>Le lecteur de prévisualisation</strong> est épinglé au pied de l’explorateur : le panneau défile, si bien qu’une bibliothèque avec des favoris poussait le transport hors de vue, ne laissant aucun bouton Stop à l’écran pendant que le plug-in continuait de jouer.","changelog.83ea9df0754e":"<strong>La barre de titre avait l’icône Windows par défaut</strong>, car une barre de titre prend son icône dans la classe de fenêtre et <code>baseview</code> en enregistre une sans icône. ⛔ Version autonome uniquement — dans une DAW, cette fenêtre appartient à l’hôte.","changelog.8db43618eb5d":"Corrigé — les instruments qu’un artiste charge réellement, 2026-08-30","changelog.124d7acd17d3":"⛔⛔ <strong>La mélodie de Drake était un Hand Bell et sa contre-mélodie un Recorder.</strong> Trois défauts, mesurés :","changelog.d4d7ff8f906c":"<strong><code>melody.timbreHint</code> n’avait aucun lecteur.</strong> Il est écrit <strong>1 966 fois avec 252 valeurs distinctes</strong> et <code>grep</code> ne le trouvait que dans les tests, si bien que le son de chaque modèle était tiré parmi les 77 instruments qui servent une partie mélodique. Il est lu désormais : le nom devient l’instrument et le modificateur devient un timbre.","changelog.cb4b176767c3":"<strong>Le tirage de repli ne savait pas pour quel genre il tirait.</strong> ⚠ La première version filtrait par <em>famille</em> et se trompait encore — la famille Claviers contient le bandonéon, si bien que les accords de Drake sortaient en <strong>Bandoneon</strong>.","changelog.9ec8b19d2a99":"<strong>La variation était tirée entre 0 et 23</strong>, alors que le code avait toujours dit que la variation 0 est le préréglage signature, si bien que le son par défaut d’un artiste était une variante marginale de l’instrument qu’il recevait.","changelog.83d8f379ed55":"▶ Mesuré après coup : la mélodie de Drake est un Electric Piano doux, celle de Future un Bell brillant, celle d’Adele un Grand Piano chaleureux. Les moteurs n’ont jamais été le problème — 179 des 225 instruments sont déjà routés vers un modèle physique.","changelog.d24230b7e18c":"Ajouté — les consignes de la nuit, 2026-08-30","changelog.94468f71b792":"<strong>Une écoute en one-shot pour les instruments d’usine.</strong> Le navigateur pouvait prévisualiser chaque <code>.wav</code> du disque et pas un seul des 225 instruments. ▶ Trois pièces étaient déjà dans l’arborescence et n’avaient jamais été assemblées.","changelog.d9630357c37d":"<strong>Une note d’écoute propre à chaque instrument.</strong> La table répondait C4 pour tout sauf pour une basse, si bien qu’un tuba et un piccolo étaient écoutés sur la même note.","changelog.a0f4946b92e6":"<strong>Une barre d’état dans le pied de page.</strong> Le <code>1.1.00</code> dans ce coin était la position du transport et se lisait comme un numéro de version. ▶ La région live qui remplit la barre écrivait déjà ces phrases et n’avait été montrée à personne.","changelog.24e91666084b":"<strong>Le métronome tombe désormais sur le temps</strong> : le clic était déclenché au début du bloc qui contenait le temps, ce qui fait <strong>43 ms</strong> avec la période de 2048 trames de la version autonome.","changelog.40c605708dea":"<strong>Une piste du kit peut être choisie comme cible de routage</strong>, et <code>Ctrl</code>+→ y envoie l’instrument sélectionné. Rien n’entre dans un générateur à rebours.","changelog.8a97e46ad351":"Corrigé — trois affichages qui mentaient, 2026-08-30","changelog.13efc12c8cad":"<strong>L’inspecteur de style listait <code>$schema</code> et le bloc de recherche.</strong> Il ignore désormais la comptabilité du fichier et la provenance des recherches ; <code>era</code> et <code>genres</code> restent, car le sélecteur d’instruments les lit.","changelog.31e9eda443e8":"<strong>L’éditeur d’enveloppe dessinait ses poignées d’extrémité à moitié.</strong> Une poignée se place à sa valeur, donc un sustain à 0 dB est sur le bord supérieur et un release au maximum sur le bord droit, avec cinq unités de cercle hors de la viewBox. La boîte a désormais une marge.","changelog.5ba045b1b88b":"<strong>Le panneau du kit affichait « Intégré » quoi qu’un artiste ait chargé</strong>, jetant le nom par lequel le chargeur de préréglages répondait déjà.","changelog.3f52a91cd88b":"Ajouté — les indispensables de la v1.0.0, 2026-08-29","changelog.fd9a52e845e2":"<strong>Verrous par paramètre.</strong> Verrouillez le <em>rythme</em> et relancez les hauteurs, ou l’inverse. ⛔ Composé dans <code>withLocks</code> plutôt qu’à chaque porte, si bien que Générer et Tout générer en bénéficient par construction — une règle installée à une porte et pas à l’autre est un échec que ce dépôt a consigné sept fois.","changelog.17455804e395":"<strong>Rôles de one-shot fondés sur le contenu.</strong> Quand un nom de fichier ne dit rien, un échantillon est classé à partir de six caractéristiques DSP lisibles et le volet affiche la raison : <em>« 808 · 1,9 s · 62 Hz · 4 % de bruit »</em>. ⛔ Des seuils, pas un classifieur, et le nom l’emporte toujours.","changelog.3ba97e819e31":"<strong>L’inspecteur de style</strong>, avec chaque valeur attribuée au modèle qui l’a fournie. ⛔ Un forçage s’applique après le mode et avant le lint, si bien qu’un mode ne peut pas silencieusement l’emporter sur une valeur que vous venez de fixer.","changelog.b3fc14e1aaf9":"<strong>Reçu de provenance.</strong> Désactivé par défaut, écrit localement, jamais envoyé nulle part.","changelog.e9eeec6e1529":"<strong>Le docteur des fichiers manquants.</strong> ⛔ « Vérifié » et « apparié par le nom » sont deux affirmations différentes et sont dessinées différemment, car seul un hachage enregistré <em>avant</em> la disparition d’un fichier peut prouver un candidat.","changelog.4c2e5321dca4":"<strong>Jouez les notes.</strong> ⛔ Les attaques sont calées et les longueurs non — étirer une note jouée jusqu’à la grille est ce qui fait sonner une entrée quantifiée comme une machine.","changelog.8c0513f107b0":"<strong>Coécrire un style.</strong> ⛔ Un diff par rapport au modèle d’origine, jamais une copie : une copie fige les valeurs par défaut d’aujourd’hui, et chaque amélioration ultérieure du parent cesse de l’atteindre, silencieusement.","changelog.beb404bfb850":"Vérifié comme déjà construit","changelog.9c1a0003d15a":"FMM-S01 (échantillonneur dans le plug-in), FMM-S02 (contournement MIDI seul et mute audio par piste avec le MIDI qui circule toujours) et FMM-S03 (glisser-déposer natif du MIDI et de l’audio rendu vers l’extérieur) avaient tous été livrés sous des numéros de tâche antérieurs.","changelog.18fb79233d8e":"Ajouté — un bouton d’enregistrement, un métronome, et une touche qui joue un accord, 2026-08-26","changelog.55c7530e6073":"<strong>Enregistrez ce que vous jouez, dans le clip de la partie</strong>, depuis le clavier à l’écran, un clavier MIDI ou les touches de l’ordinateur. ⛔ Une note tenue à travers la boucle est une seule note, non tronquée à la barre de mesure, et <strong>le deuxième passage s’ajoute en overdub</strong>. Les deux découlent d’une seule décision : le temps est compté à partir du moment où l’enregistrement démarre et n’est converti en position qu’au moment où la note est écrite.","changelog.29e9a0b6f948":"⛔ <strong>Seul le bouton Abandonner vide une prise.</strong> Un enregistreur à un passage qui mange sa propre prise est l’échec que chaque producteur a connu dans un autre outil et qu’il testera dans les trente premières secondes.","changelog.2339bbf1e7ae":"<strong>Un métronome à côté.</strong> ⛔ C’est une aide à l’écoute, et il ne peut jamais atteindre un mix rendu, un glisser-déposer vers l’extérieur ou un export de pack.","changelog.6136b9c1d42c":"<strong>Une touche joue l’accord.</strong> ⛔ Il n’y a qu’un seul constructeur d’accords, sur le thread audio ; la page envoie une fondamentale et jamais un accord, car une copie des demi-tons de la gamme en TypeScript serait le deuxième constructeur que tout ceci existe pour empêcher.","changelog.fd3543d53681":"<strong>Noms d’accords sur le piano roll et sur les touches.</strong> ⛔ La tonalité vient de la session, jamais des notes : C–E♭–G est <code>i</code> en C mineur et <code>vi</code> en E♭ majeur, et un nom qui oscille entre les deux est pire que pas de nom du tout.","changelog.0c3159dec9e4":"Sécurité — trois façons d’entrer dans un salon qui n’auraient pas dû exister, 2026-08-27","changelog.f18e6a3e8b22":"⚠ Aucune n’est encore accessible dans un build livré, mais chacune était un vrai trou dans du code par ailleurs terminé, et chacune est corrigée avec un test qui la reproduit.","changelog.866ebdbc95a0":"⛔⛔ <strong>Une réponse d’invitation collée pouvait usurper l’identité du propriétaire.</strong> L’identifiant de pair de la réponse est écrit par celui qui l’a construite, et il était trivialement devinable, car un salon et son propriétaire étaient créés à partir d’une même lecture d’horloge — <code>room-&lt;t&gt;</code> trahissait <code>me-&lt;t&gt;</code>.","changelog.839fdc680905":"⛔⛔ <strong>Un invité pouvait signer à la place d’un autre membre.</strong> Une trame de signalisation nomme le pair qu’elle concerne et ce nom était pris sur parole, si bien qu’un invité pouvait prendre la place du propriétaire dans la table de connexions d’une victime. ⚠ Un test affirmait que l’ancien comportement était correct ; il maintenait le trou ouvert.","changelog.21f5bf6627b0":"⛔⛔ <strong>Un arrivant tardif pouvait apprendre le mauvais successeur</strong>, car la liste des membres qu’il recevait était triée par place plutôt que par ordre d’arrivée.","changelog.2a4225044c45":"<strong>Le fichier de port du sidecar est en <code>0600</code> sous Linux</strong>, créé ainsi plutôt que restreint après coup.","changelog.ae9b66d28161":"Corrigé — l’enregistreur, au second regard, 2026-08-27","changelog.bf75d500547e":"Tous se trouvaient dans du code qui venait d’être livré, et chaque correctif a un test qui échoue avec l’ancien comportement.","changelog.06a1e90fa8d5":"⛔⛔ <strong>Une prise atterrissait là où vous aviez appuyé sur Enregistrer, pas là où vous aviez joué.</strong> L’horloge démarrait au bouton plutôt qu’au transport, si bien qu’un accord joué sur le premier temps de la mesure 4 après avoir armé à la mesure 3 arrivait une mesure plus loin dans le clip.","changelog.df8e2475b858":"⛔ <strong>Tout ce qui dépassait 1 024 notes dans un passage était perdu</strong> : le transfert avançait son curseur avant de vérifier si la note était arrivée.","changelog.a60f121ecd2e":"⛔ <strong>Une prise jouée sur deux générateurs s’écrasait sur un seul</strong>, le moteur qui avait fait sonner chaque note étant ignoré au profit de l’onglet ouvert.","changelog.398bb76fb6e9":"⛔ <strong>Une note coupée par le bouton panique durait jusqu’à la fin de la prise</strong>, si bien qu’un accord de 200 ms était écrit comme une note durant tout l’enregistrement.","changelog.e8057c8ad5f1":"<strong>La boucle repartait au mauvais endroit dans toute métrique qui n’est pas en <code>x/4</code>.</strong>","changelog.225cbcabcd7f":"Corrigé — le build navigateur, et une fixture qui mentait, 2026-08-27","changelog.6cff7080b85d":"⛔⛔ <strong>Sept commandes du pont n’avaient pas de fixture, si bien que l’enregistreur et le mode accords étaient morts hors du plug-in</strong> — dans <code>vite dev</code>, le build web et chaque exécution de bout en bout — et rien ne passait au rouge, car chaque site d’appel avale l’erreur. Le piano roll demande les noms d’accords depuis son propre dessin, donc c’était un appel rejeté par image pendant toute la vie de la page.","changelog.dd41a2bcdfe7":"⛔ <strong>La fixture refusait ensuite trente-cinq des quarante et une gammes</strong>, si bien que le mode accords restait mort pour quiconque avait fixé Dorien, et elle nommait les accords en dièses là où le moteur les nomme en bémols. Une fixture qui peut répondre autrement que la vraie chose fait précisément ce qu’elle ne doit jamais faire.","changelog.8dae7783d759":"<strong>Modifier un pad d’un rack dérivé réinitialisait les sept autres</strong>, définitivement, car la disposition modifiée l’emporte ensuite pour toujours.","changelog.130d4f5e7331":"<strong>Un nouveau projet écrivait chaque accord en C</strong>, car « aucune tonalité définie » était envoyé comme « la tonalité de C ».","changelog.dbf257322b22":"Modifié — la page de confidentialité dit ce qui quitte réellement la machine, 2026-08-27","changelog.a78636091f9d":"⛔⛔ <strong>Elle disait « aucun serveur STUN n’est configuré et aucun n’est compilé par défaut ». Ce n’était pas vrai.</strong> Le build en livre deux — Cloudflare et Google — et contacte l’un d’eux quand vous ouvrez ou rejoignez un salon, si bien qu’il peut apprendre qu’une certaine adresse utilise une application WebRTC. Pas à qui vous parlez, ni ce que vous envoyez. Les deux sont désormais nommés sur la page dans les dix-huit langues, avec le moment où ils sont contactés et ce qu’ils apprennent.","changelog.48cff82da9bd":"⚠ Un test affirmait la phrase fausse, et c’est ainsi qu’elle a survécu. Ce qui reste dû, et qui est désormais dit, c’est un réglage pour les changer ou les désactiver.","changelog.0b9b24ca1f7c":"Ajouté — l’instrument a gagné un clavier, une bibliothèque dans laquelle enregistrer, et un rack d’échantillons, 2026-08-23","changelog.bbd370386f96":"<strong>Quatre instruments à la fois.</strong> Mélodie, Contre-mélodie, Ligne de basse et Accords possèdent chacun un <code>SynthEngine</code>. ⚠ Mesuré à <strong>26 % d’un bloc de 128 trames</strong> pour quatre parties à 16 voix.","changelog.8d4e8720aff1":"<strong>Enregistrez un son</strong> sous une catégorie et un nom de votre choix. ⛔ Un <em>son</em> est un instrument ; un <em>préréglage</em> dans le panneau droit est une session enregistrée. Des répertoires différents, jamais une seule liste.","changelog.8945b84546af":"<strong>PACK — un rack d’échantillons de 25 emplacements</strong>, rendu hors du thread de l’éditeur avec une progression et un bouton Annuler, les rendus quasi silencieux étant rejetés avant d’atteindre le rack.","changelog.b0679c7fd0e5":"<strong>Jouez-le depuis du matériel.</strong> ⛔ Une note transposée au-delà des extrémités est abandonnée, pas repliée : une note repliée est une fausse note et rien à l’écran ne le dirait.","changelog.0a8a403c1283":"<strong>AIFF, 24 bits, 32 bits flottant et fréquences jusqu’à 192 kHz.</strong> ⛔ Une boucle glissée reste toujours un WAV 16 bits, car seul un WAV porte le chunk <code>acid</code> qui la fait arriver à son propre tempo.","changelog.becd79896add":"Corrigé — quatre défauts que personne ne cherchait, 2026-08-23","changelog.5aa574085b3e":"⛔⛔ <strong>Un projet rouvert nommait un son qu’il ne jouait pas.</strong> <code>part_sounds</code> est restauré avec la session, donc le panneau revenait en affichant l’instrument assigné — et rien ne renvoyait le patch, si bien que chaque moteur était encore sur le son initial. Le panoramique n’atteignait pas non plus le thread audio.","changelog.e41b41f68e79":"⛔⛔ <strong><code>Shift+ArrowUp</code> qui ne faisait rien sous macOS était une course à la relecture, pas le modificateur.</strong> Chaque validation de bouton fait un aller-retour et relit la valeur, et la réponse d’une validation pouvait arriver après une modification plus récente et l’écraser. La vérification a désormais lieu à l’arrivée de la réponse. Shift ne faisait que le rendre visible : un pas grossier annulé atterrit à un endroit manifestement faux, un pas fin annulé reste dans la tolérance.","changelog.8da0d11157f2":"<strong>Les WAV 32 bits flottants étaient refusés comme « compressés »</strong>, ce qui est faux, et c’est ce que la plupart des DAW exportent.","changelog.eab27dba438d":"<strong>Le gain, le panoramique et l’enveloppe par partie n’atteignaient aucun son.</strong>","changelog.33498857d52b":"<strong><code>MAX_EXTRACT_SECONDS</code> 60 → 300</strong>, sur la base d’une mesure plutôt que d’un coup de pouce. La mémoire de pointe de l’analyse était justifiée comme « plusieurs fois la longueur décodée » ; mesurée avec un allocateur qui suit le pic, elle est de <strong>1,2×, constante</strong> — 13,9 Mo à une minute, 69,5 Mo à cinq. ⛔ Elle <strong>refuse</strong> toujours plutôt que de tronquer : les cinq premières minutes d’un fichier de sept minutes seraient une supposition présentée comme une transcription.","changelog.034ba0a65cf5":"<strong>Réverbération, délai et saturation ne sont dessinés que sur un instrument d’usine</strong>, car l’échantillonneur n’a pas de chaîne d’effets et, sur votre propre échantillon, ils ne changeraient rien.","changelog.975e6e71fd3a":"La bibliothèque partagée du plug-in est passée dans sa propre crate. ⛔ <code>cargo test --workspace --release</code> était incapable de lier depuis des mois — 413 externes non résolus — car <code>panic = &quot;abort&quot;</code> et une cible <code>[&quot;cdylib&quot;, &quot;lib&quot;]</code> faisaient compiler par Cargo une même bibliothèque deux fois sous un seul nom de fichier.","changelog.2cecc0c1d888":"Les zips téléchargés contiennent <code>INSTALL.txt</code>.","changelog.38fbbc3ec4b5":"Corrigé — un <code>secondaryAnchor</code> hérité mangeait tout le budget de kick d’un enfant, 2026-08-22","changelog.37aab3338c62":"⛔⛔ <strong>129 modèles livrés génèrent désormais un kick différent.</strong> <code>drums.kick.anchors</code> est un tableau, donc un enfant qui écrit le sien remplace celui du parent — mais <code>secondaryAnchor</code> est un scalaire séparé à côté, si bien qu’il survivait à ce remplacement et était réintégré par union. Un modèle disant <em>« mes ancrages sont 1 et 3 »</em> recevait 1, 2&amp; et 3, et là où cela remplissait le budget de densité, chaque coup de kick devenait garanti et la piste cessait de varier. Mesuré sur <code>darius-rucker</code> : <strong>92 formes de kick distinctes sur 200 graines</strong> sur sa propre base, <strong>4</strong> sur une base dont le secondaire est <code>&quot;2&amp;&quot;</code>.","changelog.7b1e2aadc5b3":"Un enfant qui écrit <code>anchors</code> sans <code>secondaryAnchor</code> n’en hérite plus. 34 genres écrivent ce champ et 282 modèles écrivent leurs propres ancrages avec un budget qu’un secondaire ajouté remplirait : ce n’a donc jamais été le problème d’un seul modèle.","changelog.42019e6efdae":"Corrigé — l’écran À propos créditait un jeu de données que le produit n’utilise pas, 2026-08-22","changelog.e38cc70c3c1f":"Dans les dix-huit langues, il disait <em>« Statistiques de timing et de vélocité dérivées du Magenta Groove MIDI Dataset »</em>. <strong>Ce n’est pas vrai</strong> : l’humaniseur est écrit à la main à partir de recherches publiées sur la technique, et l’outil qui aurait lu le GMD n’a jamais été écrit. Retiré du volet À propos et de <code>docs/credits.md</code>. L’attribution est due quand vous <em>utilisez</em> une œuvre ; en attribuer une que vous n’utilisez pas est une fausse déclaration sur l’origine des chiffres du produit.","changelog.36015e08f729":"Ajouté — des étiquettes dans l’explorateur de fichiers, et le dossier des plantages enfin proposé","changelog.1e983e7b7fd6":"<strong>Étiquettes.</strong> Ajoutez-les et retirez-les sur le fichier sélectionné, avec complétion, et filtrez l’arborescence par étiquette ou par étoile. ⛔ Un dossier ne satisfait jamais un filtre d’étiquette par son propre nom : un filtre d’étiquette est une affirmation sur des <em>fichiers</em>, donc un dossier nommé <code>808s</code> ne doit pas réadmettre les fichiers sans étiquette qu’il contient.","changelog.3ef25c4b3313":"<strong>Le dossier des plantages est proposé plutôt que caché.</strong> Le hook de panique et la frontière d’erreur écrivaient tous deux des rapports que rien ne lisait jamais.","changelog.8d8b9b03bc3f":"<strong>Une génération est annoncée aux lecteurs d’écran</strong>, alors qu’auparavant elle ne produisait rien de perceptible — la grille est un canvas et tout le reste était visuel.","changelog.20ad24384bcf":"<strong>Les nouveaux clips s’ouvrent à votre propre longueur.</strong>","changelog.6e286b860c79":"<strong>Les humeurs sont déclarées avant l’entraînement, et non déduites après.</strong> Les relire sur les prises conservées répond à <em>« qu’avez-vous généré »</em> plutôt qu’à <em>« quel est ce flux de travail »</em>, si bien qu’un style entraîné sur vingt prises sombres et une prise bounce s’enregistrait comme les deux.","changelog.273946b10440":"<strong>Quatorze artistes underground de plus</strong> — rage, opium et jerk — portant le répertoire à <strong>1 317 modèles</strong>.","changelog.50f34d3336e8":"Ajouté — trois contrôles qui bouchent des trous que rien ne surveillait","changelog.12458ceaee7b":"<strong>Aucun alias ne peut être le propre nom d’un autre modèle.</strong> À 1 317 modèles, il fallait que quelque chose d’autre que la vigilance l’impose. ⚠ Il n’échoue que sur un seul type de collision : un tag de crew qui nomme plusieurs modèles est une façon légitime d’atteindre un groupe de personnes.","changelog.5b575339b3de":"<strong>Pas de <code>std::net</code> dans notre propre Rust</strong>, sous forme de <code>clippy.toml</code>. Toute vérification de dépendances est aveugle à un socket ouvert via <code>std</code>, car cela ne lie rien et ne résout rien de nouveau dans <code>Cargo.lock</code>. ⚠ Une analyse du texte source a été écrite en premier puis jetée : elle ne résolvait rien, si bien que <code>use std::net as n</code> passait sans encombre.","changelog.8ba8228a27d5":"<strong>Les cinq mots que le guide de ton interdit.</strong> ⛔ La première exécution a attrapé un texte <em>correct</em> — « Re-roll every unlocked pad » — donc la règle porte sur le verbe de startup et son gérondif, jamais sur le participe passé : ce produit a des verrous.","changelog.6951117e4210":"Ajouté — treize paramètres de plus que le jeu de données écrivait et qu’aucun code ne lisait, 2026-08-18","changelog.02b8b216112f":"Treize clés ont quitté le registre de la dette, sur environ <strong>1 600 réglages écrits</strong> qui ne faisaient rien.","changelog.22595cc7e4a2":"<strong>Le rimshot sous la caisse claire</strong> (231 modèles), qui double le backbeat sur le temps plutôt qu’à côté — un rimshot sous une caisse claire, c’est un seul fût frappé de deux façons.","changelog.759a885d7eed":"<strong>Le temps de glide de la 808</strong> (105 modèles). La drill claque en 20–35 ms et l’afroswing glisse sur 130–220, et tout cela sortait des enceintes comme « le reste de la note », car le trajet était codé en dur à trois endroits. ⚠ Tiré une fois pour la prise, pas par note : un tirage par note aurait déplacé la position rng de 105 modèles à chaque glissement — une clé portant sur le <em>timbre</em> réécrivant leurs <em>hauteurs</em>.","changelog.46c9a98765f4":"<strong>Le backbeat verrouillé</strong> (5 modèles), pour que le 2 et le 4 restent en place pendant que les ghost notes autour respirent.","changelog.712e506631ab":"<strong>Le four-on-the-floor dans le hook</strong> (29) et <strong>le couplet en cross-stick</strong> (74), qui nomment tous deux une section que la batterie n’avait jamais vue. ⛔ Le cross-stick <em>déplace</em> le backbeat sur le cercle plutôt que de le doubler, ce qui rend le couplet plus calme que le refrain.","changelog.d833b34971a3":"<strong>L’accord de la caisse claire</strong> (7 modèles). ⛔ Le registre classait cela sous la 808, où l’écrire aurait désaccordé une <em>ligne de basse</em> — une fausse note plutôt qu’un timbre.","changelog.86a977b8200a":"Corrigé — ce que la passe de revue a trouvé, 2026-08-18","changelog.b6906fa13a4e":"⛔⛔ <strong>Un son de batterie jouait trop bas dans le plug-in et bougeait dans le stem exporté.</strong> Un même numéro de note servait deux lecteurs : l’hôte, qui a besoin de la <strong>voix GM</strong> d’un fût, sinon un kick qui se promène déclenche quatre fûts différents dans votre rack, et le sampler de prévisualisation, qui lit le même numéro pour décider de combien retransposer le pad. Calé sur GM, chaque son de batterie jouait trop bas <em>uniquement dans la prévisualisation en direct</em>, tandis que le rendu retransposait correctement.","changelog.f91f216318eb":"⛔⛔ <strong>Un couplet en cross-stick faisait taire la règle d’arrêt de la 808 elle-même.</strong> Le backbeat était écrit directement sur la piste du cercle, et la 808 lit les coups de caisse claire à travers lesquels elle ne doit pas sonner — si bien que dans un couplet, cette liste revenait vide et la 808 tenait par-dessus le coup même devant lequel la drill, par définition, s’arrête.","changelog.df60688769f5":"⛔ <strong>Le four-on-the-floor du hook réécrivait la grammaire propre du kick dès la mesure 2</strong>, les pulsations ajoutées tirant leurs vélocités du même flux que lit chaque mesure suivante.","changelog.c566b1219e10":"⛔ <strong>Une relance retirait au sort les longueurs de boucle de l’enregistrement</strong>, si bien qu’une section relancée revenait avec une autre longueur de clip et que la fin de chaque répétition tombait dans le silence.","changelog.6bafa094d3d1":"Modifié — le registre de la dette dit ce qui est réellement dû, 2026-08-18","changelog.9c4c6538b967":"Quatre entrées étaient périmées ou fausses : <code>timbreHint</code> revendiquait 21 modèles et compte <strong>1 234 écritures</strong>, la plus grosse clé écrite mais non lue du jeu de données ; la moitié <code>true</code> de <code>monoCutSelf</code> fonctionne déjà, et ce qui n’est pas lu, ce sont les quatre modèles qui écrivent <code>false</code> ; <code>minimalism</code> et <code>chordFrequency</code> étaient classées au mauvais niveau, et la seconde est héritée par les 590. Trois sont désormais marquées <strong>une question pour Mike</strong> plutôt qu’une tâche, car chacune soit contredit une clé que le même modèle écrit, soit est inerte.","changelog.148f80ce9161":"Ajouté — seize paramètres que le jeu de données écrivait et qu’aucun code ne lisait, 2026-08-18","changelog.5a6d1f5a2389":"<strong>Une note de cluster est désormais sa propre articulation.</strong> Trois contrôles devaient distinguer un ornement du temps qu’il entoure et aucun n’y parvenait : marqué comme un roulement, il comptait comme un <em>fill</em> ; marqué comme une ghost note, il comptait comme la caisse claire qui <em>répond</em> au backbeat ; et non marqué, c’était le backbeat — si bien qu’un test avait discrètement commencé à mesurer un ornement large d’une triple croche comme un décalage et aurait continué de passer pour une mauvaise raison.","changelog.da3d109cb5d7":"<strong>Clusters de caisse claire</strong> (19 modèles), le marqueur phare du jerk. ⛔ Centrés sur le temps, pas commencés dessus, si bien que le backbeat est entouré plutôt que traîné en retard.","changelog.3af1edb2e147":"<strong>La plage de vélocité propre à une piste</strong>, <strong>la couche sub du kick</strong>, <strong>un temps sauté</strong> (43 modèles) et <strong>une 808 qui ignore le kick</strong> (15). ⛔ La 808 filtre les attaques du kick lui-même, donc le verrou ne pouvait jamais que rendre la sub <em>plus clairsemée</em> — jamais la déplacer.","changelog.ce23805b3729":"⛔ <strong>Chacun tire de son propre flux à graine.</strong> Une violation de cette règle a été attrapée deux pistes plus loin : la vélocité de la couche sub faisait avancer le flux du kick, le kick bougeait, la ligne de basse suit le kick, et un modèle est tombé à 946/1000 lignes de basse distinctes pour un plancher de 950 — un contrôle de ligne de basse qui échouait à cause d’une vélocité de batterie.","changelog.3838ea6a725f":"Corrigé — deux paniques accessibles depuis un modèle modifié à la main, 2026-08-18","changelog.5d8e80129d6f":"<strong>Une clé non ASCII dans un modèle utilisateur faisait planter la DAW hôte.</strong> Le lint parcourt chaque clé de chaque modèle, y compris un modèle importé ou modifié à la main, et en découpait les trois derniers octets — ce qui panique quand cet index tombe à l’intérieur d’un caractère multi-octet. La release est compilée en <code>panic = &quot;abort&quot;</code>, donc c’est la DAW qui disparaît, à <strong>chaque lancement</strong>, jusqu’à ce que le fichier soit trouvé et supprimé. Comparé en octets désormais. ⚠ Aucun modèle livré n’a de clé non ASCII, donc la CI ne l’aurait jamais vu.","changelog.9ca14e5ed251":"<strong>Un déplacement plus large que ce qu’un <code>f64</code> peut soustraire paniquait dans <code>rand</code>.</strong> Une plage de <code>[-1e308, 1e308]</code> atteignait l’échantillonneur, qui calcule <code>high - low</code>, obtient <code>inf</code> et fait un unwrap sur une erreur. Une seule borne couvre désormais les trois clés de décalage.","changelog.df3a55b59625":"Corrigé — un style vide ne s’enregistre plus, 2026-08-18","changelog.58a45134d22e":"Un brouillon qui ne dit rien que sa base ne dise déjà, ouvert sans aucun beat à l’écran, est refusé avec une raison plutôt qu’écrit. ⛔ Cocher une gamme n’est délibérément pas du contenu : la liste de gammes que propose l’éditeur est restreinte à celles de la base, donc chaque gamme que vous pouvez cocher est une gamme que votre base utilise déjà.","changelog.4dd7f6210e64":"⛔ Mesuré par rapport au brouillon avec lequel la boîte de dialogue s’est ouverte, pas par rapport à un formulaire vierge — la première version s’était trompée d’une façon qui faisait que la règle ne se déclenchait presque jamais, car le brouillon tire son swing des valeurs par défaut du modèle sélectionné et six modèles sur 1 303 se trouvaient correspondre.","changelog.7da6467e020c":"Modifié — deux coûts de chargement du jeu de données mesurés et supprimés, 2026-08-18","changelog.7355c12f6bd4":"Le lint n’alloue plus un pointeur JSON par clé et par modèle — il construisait un pointeur complet, qu’un constat soit levé ou non, plus une copie en minuscules de chaque clé. Et <code>resolve_all</code> fusionne chaque chaîne d’ancêtres une seule fois : 534 des 590 modèles sont des artistes reposant sur quelques dizaines d’archétypes de genre, et chacun refaisait la même fusion.","changelog.715106ffd3f6":"Corrigé — une contre-mélodie tenue a cessé d’entrer au même endroit à chaque fois, 2026-08-17","changelog.7ad05d0e7f17":"Une contre-mélodie <code>sustain_pad</code> choisit désormais à quel endroit de la phrase elle entre. L’entrée était le premier tick que le lead laissait libre — la même réponse pour chaque graine tirant la même longueur de phrase — si bien que sur un vamp, où les quatre mesures sont un seul accord, un tiers des graines recevaient une seule note tenue au même endroit. Vingt-sept modèles se trouvaient juste sous le plancher de variété de la contre-mélodie pour cette seule raison ; vingt-trois le franchissent désormais sans aucun changement à leurs données.","changelog.c4353fab112d":"⚠ L’entrée est choisie dans la <em>première moitié</em> de la phrase : une nappe qui entre pendant la dernière mesure de sa phrase n’est pas une nappe, et la longueur est tout ce que revendique <code>sustain_pad</code>. L’ancienne réponse reste le repli pour un lead si legato que la première moitié n’offre rien, si bien qu’aucune nappe de modèle ne devient muette.","changelog.be20007c0663":"Ajouté — les parties auxquelles un générateur répond, et quatre archétypes que la recherche attendait, 2026-08-15","changelog.a6502afe501a":"<strong>Générer une contre-mélodie remplit la mélodie à laquelle elle répond, et l’harmonie contre laquelle les deux sont écrites.</strong> Le moteur a toujours rendu ces parties, que vous ayez appuyé sur Générer ou non, si bien qu’une contre-mélodie sur une nouvelle session répondait à quelque chose que personne ne pouvait entendre. ⛔ Les remplissages viennent de l’ENREGISTREMENT, pas d’une nouvelle prise, sinon l’onglet afficherait une mélodie différente de celle à laquelle elle répond.","changelog.a5ea6391fc17":"<strong>Onze archétypes de genre que la recherche avait dû contourner</strong>, portant le jeu de données à <strong>61 genres et 602 modèles</strong>. L’omission la plus lourde de conséquences était la <strong>Techno</strong> : Jeff Mills, Robert Hood, Underground Resistance, Carl Craig, Derrick May, Juan Atkins et Kevin Saunderson avaient été écartés faute d’un endroit légitime où les placer. ⛔ Le moteur ne savait pas non plus écrire le Lowend — des caisses claires sur 1 et 3 ne correspondaient à aucun des placements qu’il connaissait. ⚠ La Techno et le Dominican Dembow sont livrés en <code>confidence: low</code> et disent pourquoi.","changelog.d0cb1f806314":"<strong>Un sélecteur Sobre / Dense sur les quatre générateurs mélodiques.</strong> ⛔ Il module à l’intérieur de ce que chaque modèle a écrit et ne le remplace jamais — <em>« un vamp de rage rendu chargé n’est plus de la rage »</em> — et le milieu de ses trois états est le modèle tel qu’écrit, si bien que chaque graine enregistrée reconstruit toujours son propre beat.","changelog.97da7ec59349":"<strong>L’éditeur de style atteint le vocabulaire des roulements, le placement de la caisse claire, le comportement de la 808 et les familles de progressions.</strong> ⚠ Chaque groupe démarre sur « De la base » : une valeur écrite <em>remplace</em> celle du parent, donc une commande sans état non défini ferait qu’ouvrir la boîte de dialogue suffirait à écraser ce sur quoi le style est fondé.","changelog.0c5372d37a10":"Modifié — le répertoire sonne de nouveau comme ses recherches, 2026-08-15","changelog.58f17233fd10":"<strong>396 modèles d’artistes et de producteurs restaurés aux valeurs qu’indiquent leurs fiches de recherche</strong>, sur instruction du propriétaire : <em>« peu m’importe qu’ils se chevauchent, assurez-vous simplement qu’il n’utilise aucun matériel protégé par le droit d’auteur. »</em> Deux passes par lots les avaient déplacés, toutes deux pour satisfaire des contrôles de distinction par paire. ⚠ Six gardent leur état ultérieur, car ce changement corrigeait quelque chose de musical et le disait.","changelog.0540e2c3eea0":"<strong>Les deux contrôles par paire n’échouent plus sur un chevauchement.</strong> Deux artistes du même courant, sur le même kit, au même tempo <em>devraient</em> parfois tomber sur la même mesure — c’est ce qui fait que chacun sonne comme lui-même plutôt que comme un voisin délibérément désaccordé. Les deux affichent toujours leurs plafonds, et les deux échouent toujours sur une paire identique à <strong>chaque</strong> graine.","changelog.f4e63eedd08b":"<strong>Le garde-fou de nouveauté filtre désormais la ligne de basse</strong>, et c’est ce qui rend cela sûr. ⛔ Il avait exclu toutes les lignes de basse sur un argument vrai pour un rythme sur cinq — <em>« une ligne de basse est verrouillée sur le kick »</em> — alors que <strong>194 modèles livrés écrivent <code>independent_riff</code></strong>. ⚠ La table ne livre toujours que des hachages : une empreinte est un contour, et il n’y a aucun moyen de revenir d’un contour à une note.","changelog.415ba45149dd":"Corrigé — ce que la passe de revue a trouvé dans les quatre jours ci-dessus, 2026-08-16","changelog.9254a5cab370":"Six relecteurs sur une seule branche. Trois ont trouvé le même défaut indépendamment.","changelog.2f8b7a34fe32":"<strong>Le sélecteur Sobre / Dense n’était transmis que par une seule des quatre portes qui le lisent.</strong> Les trois lectures du moteur étaient correctes ; la page ne l’envoyait que sur une. ⛔ Le Mode Morceau arrangeait selon la lecture écrite du modèle alors que chaque boucle à côté répondait en Dense, et relancer une section la faisait revenir plus dépouillée que ses voisines — de façon reproductible, si bien que cela semble délibéré.","changelog.3447f687fc83":"<strong>Cocher une gamme dans l’éditeur de style rendait le style impossible à enregistrer, et ce depuis la livraison de la commande.</strong> <code>session.scales</code> était écrit sans <code>weights</code>, et <strong>599 des 620 fichiers de modèle écrivent cette paire</strong>. Aucun des six relecteurs ne l’a trouvé — le test écrit pour le défaut des roulements l’a attrapé à sa première exécution.","changelog.343ec0c7ac53":"<strong>Cocher n’importe quelle subdivision de roulement rendait le style impossible à enregistrer</strong> pour la même raison, un bloc plus loin. S’il avait passé le lint, le style n’aurait écrit <strong>aucun roulement de charleston</strong>. ⚠ L’e2e passait tout du long et passerait encore, car le mock n’a pas de linter.","changelog.be4f92504204":"<strong>Un style importé pouvait bloquer la DAW</strong> : deux clés pilotant des boucles étaient lues sans bornes, et la génération est synchrone sur le thread depuis lequel l’hôte dessine sa fenêtre.","changelog.e73c794fa7f5":"Corrigé — 2026-08-15","changelog.a20c61b94daf":"<strong>« Tout générer » s’affichait comme un second bouton principal de plein poids à côté de Générer.</strong> Sa classe était appliquée depuis août et <strong>définie nulle part dans <code>src/</code></strong>. Il n’est stylé qu’avec une couleur et un contour intérieur : cette rangée se trouve sous l’éditeur, donc tout ce qui est plus haut prend sa hauteur sur la piste de vélocité.","changelog.c1d850ee5c0a":"<strong>Un remplissage en amont qui échouait jetait la génération qui avait réussi</strong>, si bien qu’un seul refus jetait une contre-mélodie déjà revenue correctement.","changelog.89075c088097":"<strong>Les humeurs <code>live band</code> et <code>one drop</code> de Salaam Remi généraient la même mélodie</strong> pour chaque graine, si bien que cette paire était décorative. La différence écrite est celle qu’un one drop fait réellement : le poids passe sur le temps 3 et la ligne se pose en arrière.","changelog.b89dcb6ed30c":"<strong>Taper « uk » trouvait Bassline au lieu de UK Drill.</strong> Un tag nu de deux lettres marque un coup <em>exact</em> contre le <em>préfixe</em> du nom de UK Drill. Trois autres ont été retirés avant de pouvoir faire de même.","changelog.e34b5632786a":"Ajouté — parcourir par époque, et une désactivation qui survit au projet, 2026-08-15","changelog.ee5867f7128b":"<strong>Quatre pastilles d’époque au-dessus du répertoire : 90s · 2000s · 2010s · 2020s.</strong> Taper fonctionne quand vous savez déjà nommer la chose ; parcourir, c’est ce que vous faites quand vous ne savez pas. ⛔ <strong>Un filtre, pas un tri</strong> : <code>boom-bap</code> va <em>des années 1990 à aujourd’hui</em>, il appartient donc aux quatre décennies à la fois, et un tri le forcerait dans une seule en mentant sur les trois autres. Elles restreignent ce que vous PARCOUREZ, jamais ce que vous pouvez TROUVER.","changelog.20cce385b4bc":"<strong>Un générateur désactivé reste désactivé à la réouverture du projet.</strong> Cela vivait dans l’état de l’interface, si bien que la réouverture réactivait l’interrupteur de la ligne de basse avec le clip toujours enregistré à côté — et la session jouait une basse que le morceau importé ne contient pas.","changelog.b9dd2c70835c":"<strong>Un <code>.mid</code> déposé sur un générateur est réparti entre les générateurs auxquels appartiennent ses voix</strong>, là où le geste de dépôt lisait auparavant tout le fichier dans le seul onglet visé.","changelog.93349a364b1f":"<strong>La boîte de dialogue one-shot et le dé du kit se disputaient une même réponse.</strong> Les deux interrogent une boîte aux lettres qui se vide à la lecture, si bien que la boucle qui interrogeait la première consommait le résultat et que l’autre signalait un succès par-dessus un échec qu’elle n’avait jamais vu.","changelog.aca47e54cbfd":"<strong>Vider un générateur depuis l’onglet Morceau faisait taire tout l’arrangement</strong>, avec la frise toujours à l’écran et Lecture toujours allumé.","changelog.2d60765bc992":"<strong><code>chroma</code> allouait 11,5 Mo par lecture pour les jeter</strong> — sur le thread de l’éditeur de la DAW de quelqu’un. Même réponse, au bit près.","changelog.0eb460ecdc4a":"<strong><code>explorer_midi</code> était une commande du pont que rien n’appelait</strong>, ce que ce projet classe comme un défaut. Retirée avec la lecture d’une seule partie qu’elle servait.","changelog.e21415352325":"Ajouté — un échantillon devient des notes, 2026-08-14","changelog.1cb3d917d3aa":"<strong>Faites glisser un fichier audio sur un générateur et il est réparti entre les générateurs auxquels appartiennent ses parties.</strong>","changelog.286f68904eb7":"<strong>La batterie est classée en deux passes.</strong> Le spectre propose — kick sous 150 Hz, caisse claire large bande, charlestons en haut — et la <em>mesure</em> lève l’ambiguïté sur ce qu’il ne peut pas trancher : tout ce qui tombe sur deux et quatre est le backbeat, quel que soit son son, et des coups aigus espacés en triolets forment un seul roulement. ⛔ La deuxième passe ne peut que réattribuer ce que la première a détecté, et c’est la frontière entre un détecteur et un générateur.","changelog.fd25cb74ee0a":"<strong>La basse n’a pas besoin de transcription.</strong> Un passe-bas à 250 Hz, et ce qui survit <em>est</em> la ligne de basse ; le kick s’élimine de lui-même, faute de période stable.","changelog.b79f5af7a4a1":"<strong>Les accords reviennent sous forme de progression, pas de voicing</strong>, et le panneau le dit. ⛔ La transcription polyphonique d’un mix complet est un problème de ML, le ML est interdit ici, et une fonction qui prétend à une extraction parfaite et livre des notes approximatives est pire qu’une fonction qui dit ce qu’elle fait.","changelog.fe6b6349383f":"<strong>Une ligne chantée est laissée de côté.</strong> Séparer l’<em>audio</em> vocal demande du ML ; décider si une <em>ligne de notes</em> extraite a été chantée relève de l’arithmétique. ⚠ Un Auto-Tune dur met en échec trois des quatre mesures à la fois ; le vibrato survit.","changelog.bf43f015b953":"Corrigé — un fichier de projet pouvait entraîner la DAW dans sa chute, 2026-08-14","changelog.d7f36c2594cb":"⛔ <strong>Une signature rythmique transportée dans un projet partagé pouvait faire planter l’hôte.</strong> La métrique arrive de la page et des valeurs fixées persistées, et aucune n’était vérifiée : 25/1 rendait un quatre-vingt-seizième de mesure plus long qu’une noire, et le clamp qui borne la longueur d’une note de batterie <strong>panique</strong> quand son plancher dépasse son plafond. <code>panic = &quot;abort&quot;</code> ne vaut qu’en release, donc dans un build livré, c’est toute la DAW et chaque projet non enregistré qu’elle contient. La métrique est restreinte là où elle entre <em>et</em> bornée là où elle est utilisée, car l’un sans l’autre laisse l’autre porte ouverte. ⚠ Trouvé en lisant le code, pas par un test qui échoue — la suite était verte.","changelog.b0f4be8222cd":"<strong>La prévisualisation du navigateur décodait un fichier qui n’est pas de l’audio</strong> : elle vérifiait qu’un chemin était local, dans la bibliothèque et un fichier, et ne vérifiait jamais l’extension.","changelog.505a5ca6f9a1":"Corrigé — la puce de tempo suit l’humeur, 2026-08-14","changelog.cf21ff1cb729":"Fixer une humeur met à jour les puces immédiatement plutôt qu’au prochain changement d’artiste — la trap est à 140 et son mode <code>dark</code> à 136, si bien que l’affichage indiquait un tempo que le moteur n’allait jamais utiliser. ⛔ La valeur fixée de base avait le même trou, d’une manière qui semblait corrigée : elle relisait bien les puces, mais <em>avant</em> que la valeur n’atteigne le plug-in, si bien qu’elle les remplissait avec la valeur que vous veniez de quitter.","changelog.d9b7864d6aea":"Ajouté — un artiste génère dans chaque genre où il travaille, 2026-08-14","changelog.a3d424256825":"<strong>« Drake, mais en R&amp;B ».</strong> Le répertoire a toujours listé un artiste sous chaque genre où il travaille — <strong>529 des 534</strong> modèles d’artistes et de producteurs nomment un genre dont ils n’héritent pas — et Générer a toujours répondu dans celui dont il hérite. Une puce <strong>Générer en</strong> choisit lequel : les propres blocs de l’artiste sur la fondation d’un autre genre, si bien que 2Pac sous boom-bap, c’est <em>2Pac sur du boom-bap</em> plutôt que l’un ou l’autre seul.","changelog.0a39f9a2654c":"⚠ Enregistré avec le projet, comme l’humeur — rouvrir sur le genre propre à l’artiste produirait silencieusement un autre morceau à partir de la même graine. ⛔ Pas un mélange de deux genres : fusionner deux bases donne de la bouillie plutôt que deux modes.","changelog.5484dab868bd":"Ajouté — le son a son propre éditeur, 2026-08-14","changelog.94523aee9a25":"<strong>Chaque pad a désormais un éditeur, pas seulement chaque note.</strong> Les <strong>notes</strong> avaient un éditeur et le <strong>son</strong> non. Un pad porte désormais une <strong>ADSR</strong> graphique (sustain en dB, relevé sur la référence), le <strong>volume</strong>, le <strong>panoramique</strong>, la <strong>transposition</strong>, l’<strong>accord fin</strong>, une bascule <strong>normaliser</strong>, le <strong>découpage début/fin</strong> sur la forme d’onde et les <strong>fondus d’entrée/sortie</strong> — tout cela par pad, persisté, et réécouté à mesure qu’on tourne les boutons. ⛔ Cela atteint aussi les voix livrées, pas seulement les échantillons que vous avez remplacés. ⚠ Un pad que personne n’a modifié est identique au bit près à ce qu’il était : une enveloppe identité n’est pas stockée du tout, si bien que le thread audio saute le calcul.","changelog.cce1ec869482":"<strong>Deux commandes que montre la référence sont délibérément absentes</strong>, et le panneau ne dit rien plutôt que de dessiner quelque chose qui ne peut pas fonctionner.","changelog.4b17bad89480":"<strong>Le navigateur peut jouer un fichier à son propre niveau, ou exactement tel qu’il est.</strong> L’écoute se situe sous la pleine échelle pour qu’un one-shot joué sur un motif en cours ne sature pas — raisonnable, et un mensonge dès que ce que vous faites, c’est juger le volume d’un échantillon.","changelog.398db3f04b48":"<strong>Placer un échantillon sur un pad ouvre l’éditeur de ce pad</strong>, par les trois chemins.","changelog.6765e374d806":"<strong>Le binaire de test le plus long du projet tourne en 1,70 seconde au lieu de 1 300,91.</strong> Il relisait 609 fichiers JSON et résolvait à nouveau les 590 modèles <strong>à chaque appel</strong>, une fois par génération, sur sept tests. La même fonction utilitaire existait dans quinze binaires du moteur.","changelog.79803c0d1988":"<strong>Une modification de pad ne peut plus vous coûter tout le projet.</strong> Cinq des nouveaux champs par pad étaient bornés à zéro par le bas et jamais plafonnés, si bien qu’une valeur non finie atteignait la session enregistrée — où elle s’écrivait <code>null</code>, s’enregistrait proprement, puis échouait au chargement, ramenant avec elle la graine, les clips modifiés, l’arrangement, les dossiers d’échantillons et les one-shots à leurs valeurs par défaut.","changelog.82d7ba79435d":"<strong>Un projet rouvert joue désormais les modifications de pad qu’il affiche.</strong> Façonner une voix <em>intégrée</em> restaurait correctement les boutons et n’en informait jamais le moteur audio, si bien que le stem exporté portait l’enveloppe et la prévisualisation non.","changelog.1a72d30e7569":"<strong>Un morceau généré avec un genre fixé l’utilise désormais</strong> : la valeur fixée atteignait une section relancée, et pas le morceau lui-même.","changelog.3b327e41cadd":"<strong>Découper un échantillon ne produit plus de clic</strong>, et le Release façonne désormais la queue d’une piste de batterie au lieu de n’y rien faire.","changelog.79fab545a936":"<strong>Une enveloppe partielle ne fait plus perdre tout le bloc</strong>, ce qui refusait un projet écrit par un build plus ancien avec <code>missing field attackMs</code>.","changelog.308a6a7f8aa6":"Ajouté — le navigateur à l’échelle d’une bibliothèque, et un historique qui survit à la session, 2026-08-13","changelog.99f4a587028c":"<strong>L’arborescence d’échantillons dessine une fenêtre, pas le dossier.</strong> 2 000 lignes par dossier, plusieurs ouverts à la fois, six éléments chacune, à l’intérieur de listes imbriquées qu’un composant fabriquait en s’appelant lui-même. C’est désormais une seule séquence plate, et seules les lignes à l’écran existent — un dossier de 2 000 fichiers s’ouvre en moins de 300 ms.","changelog.118279c360c1":"<strong>Tapez pour filtrer l’arborescence.</strong> ⚠ Le filtre dit ce qu’il a cherché : le plug-in lit un dossier par appel, donc le filtre atteint les dossiers que vous avez ouverts et pas au-delà.","changelog.c74f7d9b9f46":"<strong>Un dossier de bibliothèque absent le signale</strong>, là où la racine d’un disque débranché s’affichait comme un dossier ordinaire qui refusait de s’ouvrir.","changelog.62d394953cc6":"<strong>Chaque génération que vous avez faite, consultable et persistée.</strong> ◀/▶ répondent à « revenir d’un cran » et ne servent à rien pour « trouver celle-là parmi quatre-vingts ». Plafonné <strong>par style</strong>, car un plafond global laisserait une soirée passée sur un artiste évincer les prises pour lesquelles vous êtes revenu.","changelog.d004a114800f":"<strong>Écoutez un <code>.mid</code> depuis le navigateur</strong>, via un instrument <strong>neutre</strong> pour qu’il sonne pareil quel que soit l’artiste sélectionné.","changelog.be3f0d023b9a":"<strong>La recherche dans le répertoire coûte moins de la moitié de ce qu’elle coûtait.</strong> Le champ note 590 entrées à chaque frappe, et renormalisait la requête une fois par entrée, renormalisait les neuf champs consultables et découpait chacun en mots deux fois. 5,5 ms par frappe avant, 2,9 ms après, classement inchangé.","changelog.547ba1349053":"<strong>La version autonome écrit son journal dans un fichier en release.</strong> Le rapporteur de plantages attrapait les <em>fautes matérielles</em> ; une <strong>panique</strong> partait vers un stderr qu’un build <code>windows_subsystem = &quot;windows&quot;</code> n’a pas — si bien que l’échec le plus probablement à l’origine du plantage ouvert et non reproduit était celui qui ne laissait aucune trace.","changelog.1dfc33ad2e89":"<strong>Ouvrir un <code>.mid</code> l’inscrit dans l’historique du navigateur.</strong> Il était inscrit depuis une prévisualisation d’échantillon et depuis le <em>dépôt</em> dans une partie, mais pas depuis le clic qui l’ouvre — si bien que quelqu’un qui avait cliqué sur vingt boucles et en avait importé une voyait un historique d’une seule.","changelog.b2294b88f311":"<strong>Le mock IPC tire une nouvelle graine à chaque Générer sans valeur fixée</strong>, comme le fait le moteur. Il répondait le littéral <code>424242</code> à chaque fois, ce qu’aucun test n’a remarqué jusqu’à ce qu’un historique indexé sur <code>(part, seed)</code> transforme trois appuis en une seule prise.","changelog.931244f782e4":"Ajouté — chaque piste de batterie se déplie en piste de hauteur, 2026-08-13","changelog.07f98c226e98":"<strong>N’importe quelle piste peut s’ouvrir en rangées de hauteur</strong> — la fondamentale de la piste, trois demi-tons au-dessus et trois en dessous — si bien que la hauteur d’un coup est quelque chose que vous pouvez voir et faire glisser plutôt qu’une valeur que la grille jetait. La 808 l’a demandé ; le mécanisme est le même pour les 33, donc aucune n’en est exemptée.","changelog.04591dfc7ca3":"<strong>La course est illimitée tandis que la rangée reste haute de sept.</strong> Faire glisser au-delà du haut fait défiler la fenêtre de cette piste au lieu de s’arrêter, et chaque piste garde son propre décalage.","changelog.ab9329495924":"<strong><code>sub</code> et <code>subLow</code> étiquettent leurs rangées par des notes ; toutes les autres pistes en demi-tons</strong>, car là, le décalage est une transposition d’échantillon, et appeler un shaker « D#2 » serait un affichage qui ment.","changelog.a600b5a40e8c":"<strong>Les coups hors de la fenêtre sont marqués, pas cachés</strong>, si bien qu’une 808 qui glisse ne peut jamais être audible et invisible.","changelog.7a1adb84f977":"<strong>Un glissement de hauteur est une seule étape d’annulation</strong> : la fenêtre suit le doigt mais la note se pose au relâchement, sinon un glissement aurait coûté un Ctrl+Z par demi-ton.","changelog.768b595223be":"<strong>Faites glisser la forme d’onde de prévisualisation pour naviguer</strong>, ce qui permet de chercher un transitoire sans cliquer vingt fois.","changelog.055c12f8042f":"<strong>Une partie tenue ne s’effondre plus sur un vamp.</strong> Les deux styles tenus écrivaient une note par accord, si bien qu’un modèle dont l’harmonie repose sur un seul accord recevait une note pour tout le clip — deux modèles atteignaient 959 et 963 contre-mélodies distinctes sur 1 000 pour un plancher de 0,98, et <code>mobb-deep</code> mesurait <strong>8 lignes de basse distinctes sur 1 000 graines</strong>. Une plage tenue de plus de deux mesures se réarticule désormais sur une phrase tirée par plage.","changelog.fc0cebf8ea13":"<strong>La ligne de basse de KRS-One est de nouveau la sienne.</strong> Lui et le Wu-Tang Clan avaient été placés sur le même rythme et écrivaient la même ligne de basse sur 42 graines sur 200 : <code>mirror_kick</code> prend ses attaques sur le kick et 62 modèles boom-bap le partagent, si bien qu’un modèle sans opinion propre écrit comme le voisin qui partage son kick. Celle de KRS-One dit désormais ce que la recherche a toujours dit — reggae : le glissé dub, la septième bémol, et une basse qui joue avant le un.","changelog.5ce722b37761":"<strong><code>country-train</code> écrit 73 beats distincts sur 200 graines, contre 24</strong>, et <code>rapsody</code> passe de 136 à 199.","changelog.b395a0b52253":"Ajouté — la grille de batterie devient un éditeur, 2026-08-11","changelog.f102e9a48f1f":"<strong>Faites glisser un cadre pour sélectionner.</strong> Shift-glisser sélectionne chaque cellule à l’intérieur du rectangle, pas seulement celles que le pointeur a traversées.","changelog.73e932010c9a":"<strong>Copiez, collez, clonez et supprimez une sélection.</strong> Un triolet copié se recolle en triolet : le presse-papiers garde le vrai timing des notes plutôt que de les caler sur la grille.","changelog.91eb18c0cd6e":"<strong>Clic droit et glisser pour effacer</strong>, annulé par un seul <code>Ctrl+Z</code>. Un clic droit qui ne bouge pas ouvre toujours la palette du roll.","changelog.879ec004b17a":"<strong>Les noms des pistes sont de nouveau lisibles</strong> — ils s’affichaient sous forme d’une seule lettre. Un cadenas verrouillé reste visible quoi que fasse le pointeur, car un verrou que vous ne voyez pas est un verrou que vous oubliez avoir mis.","changelog.f9921d6b3fab":"Ajouté — le panneau des raccourcis clavier, 2026-08-11","changelog.d9b9605194c9":"<strong>Il a désormais un bouton</strong>, à côté de Paramètres et À propos. Il n’était accessible qu’en appuyant sur <code>?</code> ou <code>F1</code> — un panneau dont le seul rôle est de vous dire ce que font les touches, trouvable seulement si vous connaissiez déjà une touche. Il tient aussi sur un seul écran, et les gestes propres à la grille de batterie sont documentés pour la première fois, dans les dix-huit langues.","changelog.62dcea291c83":"Corrigé — 2026-08-11","changelog.ec59fc38e138":"<strong>Chaque note est visible quand un clip est généré, verticalement comme horizontalement.</strong> Le roll dimensionne désormais ses rangées selon le registre propre au clip et le centre, au lieu de le coller en haut avec l’espace restant en dessous.","changelog.1cb0980e60e7":"<strong>L’accolade de boucle se redimensionne par ses bords.</strong> La prise attrapait la <em>première</em> poignée à portée plutôt que la plus proche, si bien que le bord droit d’une boucle courte ne pouvait pas être saisi du tout — et toute la règle affichait un curseur de redimensionnement, ce qui rendait invisible la seule bande qui redimensionne.","changelog.78dcc84c55af":"<strong>Les dix dernières listes déroulantes natives ont disparu</strong> ; elles étaient dessinées par l’OS par rapport à la fenêtre plutôt qu’au champ.","changelog.3aae90a5883e":"<strong>Dix défauts trouvés en relisant ce qui précède</strong>, chacun corrigé avec un test vu en échec d’abord. Quatre étaient dans le collage de la grille, tous dus au fait de le mesurer en ticks alors que la grille raisonne en colonnes : un coup humanisé en avance disparaissait quand il était collé sur la première cellule, une figure clairsemée collée sur une zone dense gardait les coups en trop de la zone dense, et un collage pouvait faire revenir une piste que vous aviez réassignée ailleurs.","changelog.ba30e336f27a":"Ajouté — 32 nouveaux genres, 2026-08-10","changelog.eee977220c4e":"<strong>La liste des genres passe de 20 à 52</strong> — dark plugg, Detroit bounce, Jersey club, ATL swag rap, UK underground, EDM rage, digicore, jump-up DnB, neurofunk, jungle, pop DnB, UK garage, house, dance pop, pop 2020s, country pop, country shuffle, neo-soul, funk, future bass, afrobeats, amapiano, dancehall, reggaeton, baile funk, afroswing, Memphis rap, G-funk, lo-fi hip hop, sexy drill, hyphy et crunk.","changelog.42f059fbabae":"Chacun écrit sa propre batterie, ses accords, sa mélodie, sa contre-mélodie et sa ligne de basse — aucun n’hérite d’une partie en bloc — et chacun arrive avec trois humeurs, si bien que choisir un genre donne trois morceaux différents plutôt qu’un seul. Chacun est mesuré par rapport au reste du répertoire.","changelog.10d9e1d4972b":"Corrigé — une note pouvait tenir au-delà de la fin du motif, 2026-08-10","changelog.bbb3fb833dc4":"Une caisse claire ghost décalée en retard, ou un tambourin sur la dernière subdivision, pouvait porter sa longueur au-delà du motif — si bien que le clip que vous faisiez glisser contenait une note pour laquelle la mesure n’avait pas de place. Les quatre autres générateurs avaient toujours coupé ; le kit, jamais.","changelog.e9fa1c28ce6f":"Corrigé — les lignes de basse pouvaient sortir de la tonalité, 2026-08-10","changelog.37090d443d59":"<strong>Une note de basse chromatique atterrit désormais quelque part.</strong> Les notes de passage sont écrites comme un intervalle par rapport à l’<em>accord</em>, et sur un accord ordinaire cet intervalle peut sortir de la tonalité — si bien que la basse jouait une note venue de nulle part qui ne menait nulle part. Elle approche désormais la note qu’elle précède, comme un bassiste qui marche vers un changement d’accord. Les septièmes bémol en walking et les blue notes sont conservées : c’est l’idiome, pas le bug.","changelog.2d6b36e508b4":"<strong>Une basse ne joue plus au-dessus des accords qu’elle soutient</strong>, et quatre modèles dont la basse doublait leur propre 808 note pour note jouent désormais une vraie deuxième partie.","changelog.d0b5a7643bda":"Corrigé — le plug-in pouvait être livré avec une liste de genres périmée, 2026-08-10","changelog.9411b413d18e":"Le jeu de données est compilé dans le binaire et rien ne disait au système de build de le surveiller, si bien qu’un plug-in compilé après la modification d’un modèle pouvait continuer de servir le répertoire avec lequel il avait été compilé, sans que rien nulle part ne le signale.","changelog.77caf45cd87d":"Corrigé — l’explorateur de fichiers ne pouvait pas ouvrir un sous-dossier, et cela cassait aussi quatre autres choses, 2026-08-10","changelog.b5ed0979ba9d":"<strong>Vous pouvez de nouveau naviguer dans les sous-dossiers, à n’importe quelle profondeur.</strong> Ouvrir un dossier de bibliothèque fonctionnait ; ouvrir quoi que ce soit <em>à l’intérieur</em> était refusé, car le <code>canonicalize</code> de Windows renvoie des chemins commençant par <code>\\\\?\\</code> et la vérification qui refuse les chemins réseau prenait ce <code>\\\\</code> initial pour l’un d’eux. <strong>Le même refus cassait silencieusement le lecteur de prévisualisation, la forme d’onde, la lecture des <code>.mid</code> et le dépôt d’un échantillon sur un pad de batterie</strong> — qui passent tous par le même garde-fou. Les vrais chemins UNC sont toujours refusés.","changelog.ade18cd195aa":"<strong>Le navigateur peut utiliser tout le panneau</strong>, alors qu’il était plafonné à environ la moitié de la hauteur, quelle que soit la profondeur de vos dossiers.","changelog.1b52bf9f1edf":"Sécurité — un chemin fourni par la page pouvait faire s’authentifier le plug-in auprès d’un inconnu, 2026-08-10","changelog.b99ed6cfdb4b":"**Étoiler un fichier vérifiait la bibliothèque <em>avant</em> de vérifier s’il s’agissait d’un chemin réseau**, et c’est la vérification de la bibliothèque qui touche le disque. Sous Windows, ce n’est pas une lecture — c’est une session SMB sortante qui transmet vos identifiants Windows. Un seul message depuis la propre web view du plug-in suffisait. Le garde-fou vit désormais à l’intérieur même de la vérification de confinement, si bien qu’aucune commande future ne peut le réintroduire.","changelog.c11b4781c6b1":"<strong>Un fichier de projet partagé pouvait faire pointer la bibliothèque d’échantillons sur tout votre disque.</strong> Les dossiers de bibliothèque voyagent dans les fichiers de projet et seuls les chemins <em>réseau</em> étaient refusés, si bien qu’un projet pouvait transporter <code>C:\\Users</code> et accorder discrètement l’accès à tout ce qui lit des fichiers dans votre bibliothèque.","changelog.436b592f6cec":"<strong>Un fichier MIDI malformé pouvait tuer votre DAW.</strong> Un fichier déclarant une signature rythmique extrême à un tick par temps poussait le lecteur d’arrangement au-delà de la fin de son propre espace de ticks ; dans un build release, cela fait tomber l’hôte avec votre session non enregistrée.","changelog.4c1f2cf3c0a6":"Corrigé — trois façons dont votre travail pouvait disparaître, 2026-08-10","changelog.4c212624c7d8":"<strong>Un projet comptant plus de huit dossiers d’échantillons perdait ceux en trop.</strong> La limite sur ce que vous pouvez <em>ajouter</em> s’appliquait aussi au <em>chargement</em>, et la liste tronquée était réécrite directement par-dessus votre projet. Une limite sur ce que vous pouvez ajouter n’est pas une autorisation de supprimer ce que vous aviez déjà.","changelog.880491ce97f6":"<strong>Un morceau importé n’était jamais enregistré.</strong> Faire glisser un fichier MIDI sur l’onglet Morceau remplissait la frise, et rien ne demandait au projet de le stocker.","changelog.8e4f72c4b2d3":"<strong>Annuler supprimait un morceau importé.</strong> Un import n’appartient à aucun artiste, et le garde-fou qui empêche l’arrangement d’un artiste de fuir dans celui d’un autre l’interprétait comme une incohérence : une frappe après l’import, Ctrl+Z l’effaçait et Ctrl+Y ne pouvait pas le ramener.","changelog.cdb3914ece4a":"Ajouté — une vraie arborescence de fichiers, des onglets de dossiers, des favoris étoilés, et du MIDI qui sait ce qu’il est, 2026-08-10","changelog.8f46d9bab3fb":"<strong>Le navigateur est une vraie arborescence</strong>, qui se souvient de ce que vous avez laissé ouvert quand vous passez d’un dossier à l’autre, avec jusqu’à huit dossiers de bibliothèque sous forme d’onglets.","changelog.d384c27e9841":"<strong>Votre bibliothèque survit à la fermeture de l’application.</strong> Elle n’était auparavant enregistrée que dans le <em>projet</em>, si bien qu’elle revenait avec un <code>.als</code> et jamais avec la version autonome.","changelog.0985960cb1d0":"<strong>Favoris étoilés.</strong> Cliquez sur l’un d’eux et l’arborescence ouvre chaque dossier entre la racine et ce fichier — ou, si son dossier ne fait plus partie de vos huit onglets, ouvre plutôt l’emplacement du fichier dans l’Explorateur ou le Finder.","changelog.6fdc895ea960":"<strong>Le clavier parcourt l’arborescence.</strong> <code>↑</code>/<code>↓</code> passent d’une ligne à l’autre, <code>→</code> ouvre un dossier et <code>←</code> le ferme — et sur un <em>fichier</em>, ces mêmes touches le jouent en avant et en arrière. Un dossier n’a rien à écouter et un échantillon rien à déplier, donc ce que vous vouliez dire n’est jamais ambigu.","changelog.60837102da5c":"<strong>Les fichiers <code>.mid</code> sont affichés</strong> et honnêtement tenus à l’écart de l’audio : le pad en refuse un avant que vous ne le lâchiez plutôt que d’échouer après coup.","changelog.b1043457ecb3":"Ajouté — déposez un fichier MIDI et il détermine ce qu’il contient, 2026-08-10","changelog.fd88ab1f798a":"Faites glisser un <code>.mid</code> sur un générateur et ses notes y atterrissent, ou déposez-le sur l’onglet Morceau et prenez les parties que vous voulez — tout le fichier arrive comme un arrangement et rien n’écrase ce que vous avez tant que vous ne l’avez pas choisi. Un fichier en couches est séparé en Basse, Mélodie, Contre-mélodie, Accords et Batterie, et <strong>chaque partie dit pourquoi elle a été routée là</strong> — « sur le canal de batterie GM », « voix la plus grave », « d’après le nom du fichier » — si bien qu’une mauvaise supposition se redirige en un clic.","changelog.e560b4cd27a4":"<strong>Il a appris sur de vrais fichiers, pas sur des suppositions.</strong> Quatre exports de packs d’échantillons ont cassé la première version trois fois sur trois : les packs mettent la batterie sur le <strong>canal 0</strong>, pas sur le canal de batterie GM, donc la batterie est reconnue à sa forme — une poignée de hauteurs, frappées de nombreuses fois, courtes. Les notes mélodiques tenues se chevauchent constamment, donc les accords sont des notes frappées <em>ensemble</em> plutôt que simplement superposées. Et <strong>la note MIDI d’une 808 dit quelle touche déclenche l’échantillon, pas à quel point il sonne grave</strong>, si bien qu’une ligne de basse se trouve couramment dans le registre de la mélodie — c’est pourquoi le nom du fichier lui-même est jugé plus fiable que toute mesure.","changelog.08e81ba37df8":"Ajouté — des pads de batterie sur la scène, une seule case pour trouver n’importe quel artiste, et une fenêtre qui se comporte enfin bien, 2026-08-09","changelog.5a8e71fc3e5d":"<strong>Huit pads de batterie en haut de la scène</strong>, chacun portant tout sur sa face : le nom de la piste, ce qui s’y trouve, un point vert ou rouge selon que vous l’entendez ou non, Lecture pour l’écouter seul, un bouton aléatoire pour le relancer, et un ✕ pour remettre le son intégré. Deux pads peuvent partager une piste pour superposer une caisse claire, et la disposition est mémorisée <strong>par artiste</strong>.","changelog.7a967cc608c0":"<strong>Une liste déroulante combinée au lieu d’un champ de recherche, d’une rangée de puces et d’une liste de cinq cents lignes.</strong> Tapez pour filtrer parmi les artistes, les genres, les alias et les fautes de frappe. Arrêtez-vous à mi-chemin et cliquez ailleurs : elle prend la meilleure correspondance, si bien que vous ne pouvez pas vous retrouver sans rien de choisi. « Flux original » est épinglé en haut, quoi qu’il soit sélectionné.","changelog.cca505068909":"<strong>Les interrupteurs de mute des générateurs sont passés sur les onglets</strong>, car ils formaient une seconde rangée portant les six mêmes mots — si bien que trouver celui qui faisait taire Batterie demandait de lire « Batterie » deux fois.","changelog.635de9290198":"<strong>Tout le clip est visible quand il est généré</strong>, quelle que soit sa longueur.","changelog.34647eb32c75":"Corrigé — 2026-08-09","changelog.cb746382c26e":"⛔ <strong>Le plug-in tournait sans gestion du DPI alors que WebView2 en avait une.</strong> Sur un écran à 150 %, Windows étirait la fenêtre de moitié en plus tandis que la page s’affichait en pixels réels, si bien que l’interface couvrait les deux tiers de sa fenêtre et que le contenu ne suivait pas quand on la faisait glisser. Un seul décalage, deux symptômes.","changelog.1c0e1181baae":"<strong>La fenêtre peut être déplacée, redimensionnée et agrandie</strong>, et ne rétrécit pas en dessous de la taille pour laquelle l’application a été conçue.","changelog.395cd7a6da0c":"<strong>Les échantillons copiés d’un style sont rechargés.</strong> Le consentement et la copie fonctionnaient tous les deux ; rien ne les lisait jamais, si bien que la promesse de la case à cocher était fausse alors que le build la livrait.","changelog.cab98edaf117":"<strong>« Frappe unique » ne supprime plus la note qu’il désigne</strong> — il ramène un roulement à une seule frappe.","changelog.535170bf7968":"<strong>Double-cliquer sur la version autonome fonctionne.</strong> Elle fournit sa propre taille de période audio au lieu de dépendre d’une option de ligne de commande.","changelog.06c7109c2a8c":"Ajouté — chaque artiste a des humeurs, vous pouvez construire et entraîner votre propre style, et rien ne copie vos échantillons sans demander, 2026-08-09","changelog.a4377a96815d":"<strong>Chaque artiste et chaque genre ont désormais des humeurs.</strong> Douze genres n’en avaient aucune, et chacun en propose désormais trois — <em>dusty / jazzy / hard</em> pour le boom bap, <em>shuffle / ballad / barnburner</em> pour la country. Appuyer sur Générer parcourt la palette d’un artiste au lieu de renvoyer un seul son avec une graine différente : <strong>96 paires (artiste, humeur)</strong>, contre 33.","changelog.89a78f654f4d":"<strong>Flux original — construisez votre propre style.</strong> Nommez-le, fondez-le sur n’importe quel artiste ou genre, réglez la plage de tempo, le swing, les densités et les gammes, et enregistrez. Il génère, verrouille, relance et exporte exactement comme un style livré, car il <em>en est</em> un — héritant de tout ce que vous n’avez pas changé, y compris des améliorations que la base reçoit plus tard.","changelog.ce63a23ea1c7":"<strong>Entraînez un flux à partir des prises que vous gardez.</strong> À trente prises, Entraîner ajuste un style à ce que vous avez gardé et refuse d’en enregistrer un qui se répète. <strong>Il n’y a aucun apprentissage automatique là-dedans</strong> : il mesure vos prises et réécrit les chiffres, et l’application reste entièrement hors ligne.","changelog.5f1d99513891":"<strong>Les puces de genre disaient qu’on ne pouvait pas cliquer dessus.</strong> La rangée Genres affichait un curseur « sens interdit » sur des commandes qui fonctionnaient parfaitement, et ce depuis le tout premier dessin de la mise en page.","changelog.f5f2401fda2d":"<strong>L’entraînement aurait pu figer votre DAW.</strong> La vérification qu’un style entraîné ne se répète pas lançait des milliers de générations sur le thread depuis lequel votre hôte dessine sa fenêtre.","changelog.7de627bf6f0a":"Ajouté — la mélodie cesse de citer les autres, chaque genre a sa propre voix, et les charlestons parlent, 2026-08-08","changelog.c0ae9370557e":"<strong>⛔ Un garde-fou de nouveauté</strong>, pour qu’une mélodie générée ne soit pas un hook qui appartient déjà à quelqu’un. Chaque mélodie et contre-mélodie est comparée à une table intégrée de contours connus avant que vous ne l’entendiez. <strong>Rien dans la table n’est une mélodie</strong> : elle contient des empreintes à sens unique de <em>contours</em>, et il n’y a aucun moyen de revenir de l’une d’elles à une note. Transposer un hook ne le masque pas.","changelog.30b1c2284c32":"<strong>Chaque genre a désormais sa propre mélodie, sa propre contre-mélodie et ses propres accords</strong>, au lieu que cinq retombent sur une valeur par défaut partagée. Six genres sans 808 ont reçu une vraie ligne de basse.","changelog.030f3251348a":"<strong>⛔ Fills de charleston.</strong> C’est au charleston que la trap, la drill et le plugg font leur discours : une figure de fin de phrase qui casse le flux — un roulement, un bégaiement, une rafale de triolets, une rampe, ou un <strong>trou</strong>, le charleston qui s’arrête net.","changelog.d453628fda56":"<strong>⛔ Verrouillez un élément de batterie pour qu’une relance ne puisse pas y toucher</strong>, et <strong>solo sur chaque piste de batterie</strong>. Une piste que vous avez mise en mute reste muette pendant un solo.","changelog.28b35f4817da":"<strong>⛔ Une bibliothèque de motifs qui survit au projet</strong> — enregistrés comme des notes, sans kit. Chacun est son propre fichier, si bien qu’un enregistrement raté coûte une boucle plutôt que l’étagère.","changelog.f3ac9ded3a5f":"<strong>⛔ Chaque prise que vous avez faite pendant cette session</strong>, qui ramène toute la configuration : artiste, humeur, graine, mesures et valeurs fixées.","changelog.1e86a4e5892e":"Quatre snapshots de référence ont bougé, chaque diff lu avant la régénération : la trap et la UK drill écrivent désormais un fill de charleston ; <code>ny-drill</code>, <code>liquid-dnb</code>, <code>country-train</code> et <code>boom-bap</code> jouent leurs propres lignes de basse au lieu d’en hériter ; et un charleston fermé posé sur un charleston ouvert a disparu, ce qui change la vélocité de chaque charleston suivant, car <code>humanize</code> parcourt une piste dans l’ordre des notes.","changelog.bff5ca6b89e9":"Corrigé — ce que la revue a trouvé, 2026-08-09","changelog.5267b9a16e83":"Quinze constats ont survécu à une vérification indépendante. Les pires d’abord :","changelog.0c5c4cec0863":"<strong>⛔⛔ Ouvrir la bibliothèque de motifs pouvait faire tomber toute la DAW</strong>, en divisant par une longueur de clip calculée à partir des propres chiffres du fichier enregistré — une paire malchanceuse divisait par zéro, et le plug-in s’interrompt au lieu de dérouler la pile.","changelog.4c20acd804e4":"<strong>⛔⛔ Enregistrer un motif pouvait supprimer silencieusement un autre motif</strong> : « Take 1 » et « Take-1 » devenaient le même nom de fichier.","changelog.89c7905e0b4b":"<strong>⛔⛔ Une piste verrouillée pouvait disparaître du projet enregistré</strong>, le clip étant reconstruit à partir de la graine à la réouverture — et pouvait porter des notes au-delà de la fin d’un clip plus court, si bien que la grille dessinait quatre mesures propres pendant que l’export jouait des coups dans les mesures cinq à huit.","changelog.96f10a153c71":"<strong>⛔ Le Mode Morceau n’exécutait jamais le garde-fou de nouveauté</strong>, celui-ci étant installé sur le chemin qu’emprunte l’onglet Mélodie alors que le Mode Morceau appelle directement les générateurs. Un test vérifie le câblage plutôt que le résultat, car avec le répertoire livré, les sorties filtrées et non filtrées sont identiques et le test évident ne pouvait pas échouer.","changelog.f4b2d931a43d":"<strong>⛔ Un fill de charleston ajouté à la main tombait 40 ticks trop tôt</strong>, en se servant de la fenêtre que la grille utilise pour décider à quelle cellule appartient une note <em>humanisée</em> — juste pour la lecture, faux pour l’écriture.","changelog.0830687ca248":"⚠ Deux contrôles signalaient un succès sur moins que ce qu’ils prétendaient : la liste des pistes avait dérivé à 21 des 37 du moteur, et le test du solo <em>exigeait</em> que les parties mélodiques deviennent muettes — c’est ainsi que ce comportement avait survécu à la revue.","changelog.4e59efdbda65":"Ajouté — le navigateur d’échantillons que vous pouvez vraiment utiliser, et des clips qui ressemblent à des clips, 2026-08-07","changelog.3ac5714f8a97":"<strong>⛔ Le navigateur d’échantillons est à l’écran.</strong> Ajoutez vos dossiers une fois et ils reviennent avec le projet ; cliquez sur un échantillon pour voir sa forme d’onde et <strong>faites-le glisser directement sur une piste de batterie</strong>. Tout ce qui se trouve derrière avait été livré à la session précédente sans aucun moyen d’y accéder.","changelog.e158007006c0":"<strong>Un lecteur d’écoute sous le navigateur</strong> — cliquez n’importe où dans la forme d’onde pour lire à partir de là.","changelog.2c629c57d407":"<strong>⛔ Un clip de l’arrangement ressemble à un clip</strong>, en dessinant ses propres notes au lieu d’un nom sur une boîte ombrée, si bien que deux clips de la même partie ne se ressemblent plus, et chacun peut être glissé seul dans votre DAW.","changelog.ef9a103aedc5":"<strong>⛔ Les clips se redimensionnent</strong> : faites glisser le bord droit et cette rangée boucle sur moins de mesures à l’intérieur de sa section, sans déplacer la section ni aucune autre partie.","changelog.84e02b004ba3":"<strong>⛔ La vue d’arrangement est disposée comme une DAW.</strong> Les noms de pistes flottaient au-dessus des clips, si bien qu’à la mesure 1, le mot « BATTERIE » recouvrait le premier clip de chaque rangée.","changelog.0b3d5bf7e564":"Corrigé — ce que trois revues ont trouvé, 2026-08-07","changelog.b35639f57cb2":"<strong>⛔ Les notes plus longues d’un clip redimensionné débordaient sur sa propre répétition suivante</strong>, si bien qu’une DAW les coupait net contre la note qui avait déjà été refrappée.","changelog.0c66c5b6f618":"<strong>⛔ Les charlestons perdaient toutes leurs ghost notes hors du 4/4</strong> — en 6/8, en 12/8 et dans toute métrique en x/16, tout le flux sortait à une seule vélocité plate.","changelog.6af16dde009c":"<strong>⛔ Les percussions réglées sur « contretemps » devenaient complètement muettes</strong> dans les métriques en x/16 et x/32.","changelog.e476442a0ddc":"<strong>Un clip redimensionné dessinait des notes qu’il ne joue pas</strong>, montrant tout le motif comprimé dans chaque répétition.","changelog.4f5db5bbdf0a":"<strong>Relancer une section, ou copier, coller ou faire glisser un clip, jetait la longueur de boucle que vous lui aviez donnée.</strong>","changelog.5878d98d269b":"<strong>La ligne de basse pouvait encore refléter le mauvais kick</strong> si vous changiez les mesures, fixiez un tempo ou changiez d’humeur entre la génération de la batterie et celle de la basse.","changelog.6e929e8afe20":"Corrigé — le lecteur d’écoute, 2026-08-07","changelog.b2864d845e0f":"<strong>⛔ L’écoute d’un échantillon était muette chaque fois que l’interrupteur Audio était désactivé.</strong> Lecture s’allumait, le lecteur disait qu’il jouait, et la tête de lecture restait figée à 0:00. Désactiver l’audio signifie « envoie le MIDI à mon propre sampler, ne le double pas » — cela n’a jamais été censé empêcher le navigateur de jouer le fichier sur lequel vous venez de cliquer.","changelog.b9168982fff3":"<strong>Cliquer sur une forme d’onde en pause déplaçait la tête de lecture puis s’annulait</strong> une demi-seconde plus tard, et appuyer sur Lecture laissait la tête de lecture immobile jusqu’à une demi-seconde alors que l’échantillon sonnait déjà.","changelog.86b2b194f286":"Corrigé — 2026-08-07","changelog.9163da2a1dd7":"<strong>⛔ Toute la vue d’arrangement s’affichait sans style</strong>, et ce depuis son écriture : chaque couleur qu’elle demandait était un nom que cette application ne définit pas, si bien que les clips n’avaient pas de remplissage, que les lignes de la grille étaient invisibles et que la tête de lecture était une bande transparente.","changelog.3a92a8640214":"<strong>La ligne de basse tombait sur des kicks que la batterie ne jouait pas.</strong> Une basse qui reflète le kick — la plupart du répertoire trap et drill — copiait un motif de kick reconstruit à partir de la mauvaise graine : en boom-bap, 13 notes de basse sur 13 tombaient auparavant sur un vrai kick, et avec le flux de travail ordinaire, c’était tombé à 9 ; en UK drill, à 1 sur 14.","changelog.6683ee09105f":"<strong>Les percussions réglées sur « contretemps » jouaient pile sur le temps</strong> dans chaque métrique en x/8 — la couche censée se placer entre les pulsations les doublait.","changelog.81d18857bf68":"<strong>Six voix de batterie étaient livrées sans aucun moyen de les entendre.</strong> Ride, crash, tom, shaker et cowbell étaient dans le kit, et aucun artiste n’avait jamais été écrit pour en jouer une.","changelog.7644b0a943fa":"Ajouté — un vrai kit de batterie, un navigateur d’échantillons, et un kit par genre, 2026-08-07","changelog.ff8354926c13":"<strong>⛔ Votre batterie a désormais plus de cinq pistes</strong> — seize voix de percussion, et celles qu’un artiste utilise font partie de cet artiste. Quinze modèles livrés avaient déjà été <em>écrits</em> avec un bloc de percussions que rien n’avait jamais lu, si bien que la UK drill réclamait un woodblock depuis le jour de son écriture et n’obtenait que du silence.","changelog.90dc63284666":"<strong>⛔ Chaque genre a son propre kit.</strong> Onze familles, chacune avec son propre accordage, son propre haut du spectre et sa propre saturation. Le plafond du boom-bap est de 8 kHz, car c’est ce que pouvait échantillonner une SP-1200, et ce haut manquant <em>est</em> le son. Huit artistes nommaient le kit qu’ils voulaient depuis des mois, et tous jouaient des échantillons trap.","changelog.2b625ec90b28":"<strong>La piste 808 s’appelle désormais Sub</strong>, car c’est la basse accordée qui glisse, pas la grosse caisse. Les projets enregistrés s’ouvrent exactement comme avant.","changelog.704ed387ab2f":"<strong>⛔ Générer fait varier la prise sans changer le morceau.</strong> Appuyez sur Générer sur la batterie, passez à la mélodie, appuyez de nouveau : vous obtenez une mélodie différente écrite sur la <em>même</em> tonalité et la même progression. Avant, le deuxième appui tirait une harmonie sans rapport et les deux parties n’avaient jamais été écrites l’une par rapport à l’autre.","changelog.ff4a09ab118e":"<strong>Une accolade de boucle que vous aviez fait glisser était ignorée dès qu’un second générateur était activé</strong> — ce qui est le cas par défaut. Elle fonctionnait avec une partie en lecture et ne faisait silencieusement rien avec deux.","changelog.41b8497a15e0":"<strong>Lecture et Stop étaient allumés ou éteints aux mauvais moments.</strong> Générez la batterie, cliquez sur Mélodie, et Lecture s’éteignait alors que la batterie était armée et aurait sonné.","changelog.ab49c439eefd":"<strong>L’affichage de position comptait le mauvais clip</strong> : quatre mesures de batterie à côté de huit de mélodie affichaient 1.1 à 5.1 sur huit mesures de temps réel.","changelog.649c3a0d7720":"<strong>La boucle se réactivait après la réouverture de la fenêtre du plug-in</strong>, quel que soit le réglage choisi.","changelog.ded642647f5b":"Ajouté — jouez les générateurs ensemble, et les 808 glissent, 2026-08-06","changelog.9e2b80b85108":"<strong>Jouez plusieurs générateurs à la fois, ou n’importe lequel seul.</strong> Une planification ne contient qu’un seul clip, donc les parties sont fusionnées en un seul avant elle — c’est pourquoi cela ne pouvait pas se faire en appuyant sur Lecture dans chaque onglet tour à tour.","changelog.b6951a486c5e":"<strong>⛔ Le plug-in joue sans que la DAW tourne.</strong> Écouter un beat ne demande plus d’armer une piste et de lancer tout le projet. Démarrer le transport de la DAW reprend aussitôt la main, si bien que les deux ne peuvent jamais jouer en même temps.","changelog.f10831f4b7f5":"<strong>⛔ Le bouton Boucle fonctionne.</strong> Il était enfoncé et désactivé en permanence, avec une infobulle affirmant que la lecture bouclait toujours — ce qui n’était même pas vrai à moins qu’une accolade n’ait été tirée.","changelog.8d2084738b75":"<strong>⛔ Les glissements de 808 sont audibles.</strong> Les générateurs écrivent des glissements depuis longtemps et le MIDI les a toujours portés, mais chaque WAV rendu les jouait comme des notes plates. La hauteur voyage désormais, tenant la note de départ pendant la première moitié et glissant sur la seconde — et le même code sert la prévisualisation, l’export et le glisser-déposer, si bien qu’un stem sonne comme le <code>.mid</code> à côté de lui.","changelog.f9fa438e3093":"Corrigé — les pistes de batterie, le panneau KIT, et un panneau droit trop court, 2026-08-06","changelog.e9469a9c1fda":"<strong>⛔ « Toutes les pistes » pour l’audio de la batterie était étiqueté à l’inverse de ce qu’il dit.</strong> Il donnait un fichier par piste, tandis qu’une deuxième entrée appelée « En un seul clip » donnait le mix. Il y a désormais une entrée par piste, et <strong>« Toutes les pistes », ce sont toutes les pistes mixées dans un seul fichier</strong>.","changelog.ab3f925aaf69":"<strong>⛔ Le panneau KIT a cessé de se dessiner par-dessus le panneau PISTES.</strong> Dans une fenêtre basse, la section KIT se réduisait à rien tandis que son contenu gardait toute sa hauteur, si bien que son texte se peignait sur le panneau du dessous en une traînée illisible.","changelog.b8b2c0b5ce11":"Corrigé — la fenêtre de l’éditeur se dimensionne correctement, 2026-08-06","changelog.91804d15bbeb":"<strong>⛔ La bande noire autour de l’interface a disparu.</strong> La fenêtre de l’éditeur était dimensionnée d’après une échelle d’affichage lue à un autre moment que le reste de la géométrie, si bien que l’application finissait par n’occuper que les deux tiers de la fenêtre qui l’encadrait.","changelog.0e393d0c7690":"<strong>⛔ Le bouton de taille propose deux tailles, pas quatre.</strong> L’échelle d’affichage était relue à chaque appui et change sous les pieds de l’éditeur — elle indique 100 % tant que le système de fenêtres n’a pas été informé que le processus gère le DPI, ce qui arrive <em>après</em> le dimensionnement de l’éditeur — si bien que chacun des deux préréglages désignait discrètement deux fenêtres différentes.","changelog.8c4d3b4461cd":"<strong>⛔ Le panneau Pistes ne disparaît plus à la taille de fenêtre par défaut.</strong> Le panneau s’ouvre à 1440 px et la page se met en page à exactement 1440 px, si bien que le panneau n’avait aucune marge : il disparaissait entièrement à toutes les tailles sauf celle dont le zoom tombait exactement sur 1.","changelog.f3d631ac4ef8":"<strong>⛔ Le menu de glisser-déposer par piste n’est plus coupé en deux</strong>, si bien que les pistes de batterie du bas peuvent enfin être glissées vers l’extérieur.","changelog.65a1a2828214":"Corrigé — six défauts trouvés en faisant tourner le plug-in dans Ableton, 2026-08-06","changelog.ae0a642482e3":"<strong>⛔ Générer génère vraiment désormais.</strong> Appuyer plusieurs fois sur Générer renvoyait indéfiniment le <em>même beat</em>, ce qui donnait l’impression que le produit contenait une boucle par artiste : la graine choisie par le moteur était recopiée dans le champ de graine et renvoyée à l’appui suivant. Le champ distingue désormais une graine que vous avez choisie d’une graine que le moteur a tirée.","changelog.132f99a15823":"<strong>⛔ L’audio déposé ne joue plus au mauvais tempo.</strong> Un <code>.wav</code> glissé ne portait aucun tempo, si bien qu’Ableton le warpait au jugé — une boucle à 140 BPM jouait à 96 dans un projet à 120.","changelog.afcec78896e3":"<strong>Le panneau Pistes s’ouvre de lui-même</strong> la première fois qu’une session génère : il se souvenait d’avoir été replié d’un rechargement à l’autre, et il contient le seul moyen de faire sortir un motif.","changelog.5029b5a24655":"<strong>⛔ Les commandes ont cessé de chevaucher la piste de vélocité.</strong> En ligne depuis des mois : la rangée Générer/graine/mesures flottait au-dessus de l’éditeur, si bien qu’un plafond de vélocité placé dessous ne pouvait pas du tout être déplacé.","changelog.6b02e0d363a4":"Ajouté","changelog.b62d9b57e008":"<strong>Faites glisser une partie directement hors du plug-in et sur une piste de DAW.</strong> Chaque partie a une poignée <strong>MIDI</strong> et une poignée <strong>Audio</strong> ; avec <strong>Par piste</strong> activé, la partie de batterie devient une poignée par piste. Les fichiers portent le nom qu’un producteur leur donnerait — <code>trap - Snare - 140 BPM - C# Minor</code>. ⚠ MIDI et Audio proposent des listes différentes, délibérément : une piste que le kit ne peut pas jouer se glisse en MIDI, car les notes sont réelles, mais pas en audio, qui rendrait du silence.","changelog.4de5200c76df":"<strong>Tout l’arrangement se glisse vers l’extérieur en audio</strong>, en affichant sa progression et en s’arrêtant dès que le geste est abandonné — c’était la pièce manquante, pas le rendu.","changelog.39b376291b8b":"<strong>Les clips peuvent être déplacés dans l’arrangement</strong>, là où réorganiser voulait dire copier, coller, puis revenir supprimer l’original.","changelog.f94f8922bef2":"<strong>La grille de batterie est un éditeur</strong>, alors qu’elle était en lecture seule et que son propre en-tête le disait. ⚠ Les modifications portent sur des <strong>ticks, jamais sur des cellules</strong> : une cellule a déjà jeté l’endroit où un coup se situait à l’intérieur de la double croche, ce qui est exactement ce dont est fait un nolet.","changelog.eebab717e7db":"<strong>Exportez les parties séparément</strong>, avec le même nommage et les mêmes octets que le glisser-déposer — une boucle que vous glissez et la même boucle que vous exportez doivent être le même fichier.","changelog.f1cc8234d750":"<strong>Votre propre one-shot sur n’importe quelle partie</strong>, stocké sous forme de <strong>chemin</strong> ; un fichier qui a été déplacé est signalé plutôt que de revenir silencieusement en arrière.","changelog.adbfdc511003":"<strong>Les coups de batterie bougent en hauteur</strong> sur une étendue que chaque artiste écrit — la rage en parcourt huit, Drake deux, <code>country-train</code> aucune, car un beat train ne fait pas varier la hauteur de sa caisse claire.","changelog.c68e2faaa335":"<strong>La génération propose 4 ou 8 mesures.</strong> Deux, c’est fini — il n’y a pas assez de place en deux mesures pour les fills et les turnarounds qu’écrivent les modèles, si bien que tous les artistes sonnaient pareil. ⚠ Un projet enregistré à deux mesures s’ouvre toujours à deux mesures.","changelog.992aa08533ad":"<strong>Le piano roll porte un pointeur simple</strong>, pas un <code>+</code> : un réticule, c’est ce que porte un outil de dessin, et cliquer sur une grille vide sélectionne plutôt que de dessiner.","changelog.0b87415f26cb":"Corrigé — une revue de code xhigh de ce qui précède, 2026-08-06","changelog.a5979ff4f5ab":"Quinze défauts vérifiés, dont quatre auraient livré quelque chose de cassé.","changelog.059b3952ef8a":"<strong>⛔ Faire glisser un clip dans l’arrangement pouvait en supprimer un autre.</strong> Une section contient un clip par partie, donc faire glisser deux clips de la même partie faisait que le second écrasait le premier une fois les deux soulevés — disparu, sans que rien à l’écran ne le dise.","changelog.e6019aec8c0d":"<strong>⛔ Les puces de glisser-déposer Audio disparaissaient si vous aviez déjà replié le panneau KIT</strong>, qui était la seule chose à charger le kit — si bien que Pistes décidait que rien ne pouvait être joué et cachait chaque poignée Audio, définitivement, pendant qu’Exporter continuait de proposer l’audio.","changelog.4513b1c417f8":"<strong>⛔ Une partie de batterie ne pouvait plus être glissée vers l’extérieur en un seul fichier</strong>, car les boutons étaient devenus des ouvreurs de menu et un ouvreur de menu ne peut pas être glissé.","changelog.2eabac1a208f":"<strong>⛔ L’audio déposé jouait au mauvais tempo en 6/8, 9/8, 12/8 et 7/8</strong> : le chunk de tempo comptait les temps d’une mesure avec le numérateur, alors que l’audio se mesure en noires. C’est le même défaut que ce chunk avait été ajouté pour corriger, revenu par le sélecteur de métrique.","changelog.4c29aba1855d":"<strong>Un clip découpé glissé en « Toutes les pistes » écrivait des fichiers muets</strong> — huit déposés dans la DAW, dont sept ne contenaient rien.","changelog.4f7838402f37":"Vérifié","changelog.02dc39a2cae1":"<strong>⛔ La source de glisser-déposer macOS est désormais vérifiée par un compilateur, depuis Windows.</strong> C’est le seul fichier qu’aucun build local ne compile, et il avait <strong>quatre erreurs et deux échecs de lint</strong> — que le runner macOS de la CI aurait tous trouvés, un push à la fois. <code>cargo check --target aarch64-apple-darwin</code> vérifie les types pour macOS sans chaîne d’outils Apple, car seule l’<em>édition de liens</em> en a besoin. ⚠ Cela ne prouve toujours rien sur le comportement.","changelog.ffd42ed2f7ee":"<strong>Les glisser-déposer macOS et Linux ne figent plus l’hôte.</strong> Les deux démarraient un glisser-déposer puis bloquaient la boucle d’événements même qui devait le faire tourner — dix minutes de DAW figée et aucun fichier déposé. Windows n’a jamais été touché ; son glisser-déposer est réellement modal, ce qui a rendu l’erreur facile à commettre deux fois.","changelog.061558cb7b58":"<strong>Le plug-in passe les deux validateurs automatisés pour la première fois</strong> — <code>pluginval</code> à la sévérité maximale sur le VST3 et <code>clap-validator</code> sur le CLAP : 33 réussis, 10 ignorés, 1 échoué, l’échec étant la propre division par zéro du validateur.","changelog.1a78eb82eb61":"<strong>Linux est vérifié localement</strong>, dans Docker.","changelog.11350441bdbc":"<strong>Chaque artiste écrivait le même roulement de caisse claire</strong>, construit à partir d’une rampe codée en dur qui ne lisait ni le modèle ni la graine : <strong>six des dix artistes trap phares produisaient un roulement identique à l’octet près</strong>, et chaque modèle n’atteignait qu’un à quatre roulements distincts sur quarante graines.","changelog.c2fd00b3b92c":"<strong>UK drill, NY drill et Pop Smoke n’écrivaient qu’un seul motif de kick, à jamais</strong>, une grammaire explicite de quatre mesures qui ne touchait jamais la graine. ⚠ Chaque nouvelle variante reste à l’intérieur du tresillo que décrit la recherche.","changelog.bf5ae982968d":"<strong>Une 808 pouvait sonner à travers tout un fill</strong> : la liste des coupures ne contenait que le backbeat, si bien qu’un kick sur le temps où commence un fill laissait la 808 tenir sur tout le roulement — exactement ce contre quoi la drill se définit.","changelog.0948365cea7b":"<strong>Deux modèles frères étaient trop proches pour être distingués</strong> : <code>pop-smoke</code> différait de <code>ny-drill</code> de 0,05 sur quatre nombres et produisait un beat identique sur 16 graines sur 200. Les collisions de beats dans tout le répertoire sont désormais à <strong>zéro</strong>.","changelog.732bec7f510f":"<strong>Un morceau exporté n’arrive plus comme un seul instrument jouant tout à la fois.</strong> Chaque partie mélodique était sur le canal MIDI 0, et beaucoup d’hôtes séparent un SMF importé par <strong>canal</strong> plutôt que par piste.","changelog.2aebbfe45729":"<strong>L’harmonie ne sature plus.</strong> Les voicings étaient choisis au coût minimum strict, ce qui faisait d’un voicing une pure fonction de l’accord : <code>rage</code> produisait <strong>8 progressions distinctes sur 1 000 graines</strong> alors que sa mélodie en produisait 823.","changelog.c44613bc0e19":"<strong>Mode Morceau : choisissez un artiste, appuyez sur Générer, et obtenez un arrangement complet.</strong> Le moteur tire l’une des formes de morceau propres à l’artiste et construit un clip par partie et par section. Les sections du même type partagent un clip, car le couplet 1 et le couplet 2 sont le même beat.","changelog.a6592c5774d6":"<strong>Transitions</strong> — beats qui décrochent avant un hook, le changement de la seconde moitié, le fondu de l’outro. Chacune est une propriété de <em>l’emplacement d’une section</em> plutôt que de ses notes, et chacune est écrite dans le fichier exporté plutôt que simplement dessinée.","changelog.5829c0281641":"<strong>Un morceau se joue</strong>, et le pavage vit désormais à un seul endroit que lisent à la fois le lecteur et l’exporteur — si bien que <strong>ce que vous entendez et ce que vous exportez sortent du même calcul</strong>.","changelog.c57be389be35":"<strong>Relancez une seule section</strong> sans toucher au reste. Une partie Accords ou Batterie verrouillée est rendue comme l’harmonie et le kit sur lesquels écrire.","changelog.032c26527262":"<strong>Un arrangement modifié est enregistré avec le projet</strong>, alors qu’avant, arranger tout un morceau puis le rouvrir faisait tout perdre.","changelog.1d66ba0727df":"⚠ <strong>Les stems sont du MIDI, pas de l’audio</strong> : écrire quatre <code>.wav</code> muets et les appeler stems serait pire que de ne pas les proposer.","changelog.61e0a7809c2d":"<strong>Chaque générateur garde son propre clip.</strong> Les cinq partageaient un seul emplacement, si bien que générer une ligne de basse détruisait la mélodie qui s’y trouvait.","changelog.383945d46625":"<strong>Tout générer remplit chaque partie à partir d’une seule graine</strong>, ce qui fait des cinq un morceau plutôt que cinq boucles dans la même tonalité.","changelog.a16dc6673cf2":"<strong>Les générateurs mélodiques produisent un son</strong>, alors que le kit de prévisualisation ne portait que des percussions et que quatre d’entre eux rendaient du silence.","changelog.8a132c8da61f":"Le Mode Morceau a traversé quatre revues avant d’être livré, chaque constat avec un test vu en échec d’abord : <strong>l’annulation atteint désormais le fichier de projet</strong> ; <strong>annuler à travers un changement d’artiste ne ressuscite plus le morceau de l’artiste précédent</strong> ; <strong>les verrous et la boucle suivent leur section quand vous clonez</strong>, alors qu’un cadenas se dessinait sur la mauvaise section et qu’une relance régénérait justement les clips qu’elle disait fixés ; et <strong>relancer respecte l’enregistrement auquel la section appartient</strong>.","changelog.696a4b7c3c6f":"<strong>Un piano roll, et les quatre parties mélodiques sont enfin visibles.</strong> Elles étaient générées via le pont et atterrissaient sur la piste de l’hôte sans jamais apparaître à l’écran. Canvas plutôt que DOM, car un roll fait 128 rangées de haut et l’approche de la grille de batterie donnerait ~15 000 éléments avant une seule note — avec les notes publiées sous forme de liste visuellement masquée, pour que l’éditeur soit accessible à un lecteur d’écran et vérifiable par un test. Sélection, redimensionnement, transformations et piste de vélocité au niveau standard d’Ableton et de FL, et <strong>le jeu de gammes passe de 12 à 41</strong>. ⚠ Un clip modifié est enregistré avec le projet : le plug-in stocke la <em>requête</em>, car le moteur est déterministe, et dès que vous déplacez une note, ce n’est plus vrai.","changelog.326ba70fe140":"<strong>Le plug-in produit un son</strong>, rendu par segments découpés à chaque note-on pour qu’un coup tombe sur son échantillon exact plutôt que d’être quantifié à la limite du bloc — jusqu’à 11 ms à 512 échantillons, soit une triple croche à 140 BPM.","changelog.e6b17ec4bff4":"<strong>Les cinq générateurs sont accessibles dans le plug-in.</strong> Mélodie, contre-mélodie et ligne de basse étaient dans le moteur depuis le début, et le pont les refusait avec « pas encore implémenté » — le refus se trouvait dans le pont plutôt que dans ce sur quoi il rapportait.","changelog.4765927194b2":"<strong>La crate de l’application de bureau a disparu.</strong> <code>src-tauri/</code> — le shell, l’icône de la zone de notification, le système de mise à jour, le rapporteur de plantages et le chemin audio — est supprimé. Le produit a été retiré le 2026-07-29 ; la crate lui avait survécu parce qu’elle générait <code>ipc-audio-types.ts</code> et contenait le seul sampler de ce projet, et le sampler a d’abord été porté dans le plug-in, ce qui rend cette suppression sûre plutôt que destructrice. Deux choses corrigées au passage, toutes deux cassées dans le plug-in livré plutôt que simplement mortes : <strong>Paramètres et À propos étaient inaccessibles</strong>, la barre de titre ayant été leur seul point d’entrée, et le <strong>volet À propos affichait un tiret cadratin pour la version</strong>.","changelog.c7c7dc30d37e":"<strong>Le plug-in n’établit aucune connexion sortante, quelle qu’elle soit.</strong> Pas un changement de formulation : la liste d’autorisation de la chaîne d’approvisionnement contenait <code>reqwest</code>, <code>hyper</code>, <code>hyper_rustls</code> et <code>hyper_util</code>, tous justifiés par le système de mise à jour, et elle est désormais <strong>vide</strong> — 187 crates liées sans aucun client HTTP parmi elles. Six exemptions RUSTSEC ne correspondaient plus à rien et ont aussi été supprimées ; une exclusion qui ne correspond à rien est une permission permanente pour qu’un avis revienne sans être remarqué.","changelog.3c9e09d2a535":"<strong>Une machine sans WebView2 n’entraîne plus la DAW dans sa chute.</strong> Ouvrir l’éditeur sans runtime WebView2 — ou avec un dossier temporaire en lecture seule, ou avec le profil de navigateur du plug-in déjà tenu par un autre environnement WebView2, ce que fait la version autonome ouverte à côté d’une DAW — paniquait dans le propre callback d’ouverture d’éditeur de l’hôte. Les builds release s’interrompent sur une panique, donc l’hôte ne pouvait pas l’attraper et la session partait avec. L’éditeur s’ouvre désormais vide et dit pourquoi. Deux paniques apparentées ont suivi le même chemin : le gestionnaire de protocole personnalisé, qui s’exécutait depuis un cadre de pile d’où une panique ne peut même pas se dérouler, répond désormais 500.","changelog.6daf228152f8":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-07-29\">2026-07-29</time></span>","changelog.cc6bcb5b7f8b":"Ajouté — annulation/rétablissement illimités, et la barrière de licence","changelog.8566f666d778":"<strong>Annulation/rétablissement illimités</strong> (FMM-U01). Chaque changement de session — artiste, graine, mesures, valeurs fixées, synchronisation automatique et chaque génération — recule avec <code>Ctrl</code>/<code>Cmd</code>+<code>Z</code> et avance avec <code>Ctrl</code>/<code>Cmd</code>+<code>Shift</code>+<code>Z</code> ou <code>Ctrl</code>+<code>Y</code>. Aucune limite de profondeur : une entrée, c’est une poignée de scalaires plus une référence <em>partagée</em> à un <code>Pattern</code>, car un motif est dérivé de sa graine plutôt que stocké, si bien que cent étapes sur une même génération coûtent un seul motif. Une série de modifications d’une même commande en moins de 600 ms se fond en une seule étape ; deux générations ne fusionnent jamais, aussi rapide que soit la relance. Enregistré par un abonnement au store plutôt que par des appels propres à chaque action, si bien qu’une action future ne peut pas oublier de s’inscrire — le même argument que faisait déjà l’enregistrement de session. Armé <em>après</em> la restauration du projet, si bien que <code>Ctrl</code>+<code>Z</code> ne peut pas reculer au-delà de la session que l’hôte a rendue à un plug-in vide.","changelog.31f95ffe2fd4":"<strong>Barrière de licence au premier lancement.</strong> L’accord est compilé depuis <code>EULA.md</code> et affiché avant tout le reste ; rien ne génère, ne joue, n’exporte ni n’enregistre tant qu’il n’est pas accepté. <strong>Accepter reste désactivé tant que le texte n’a pas été défilé jusqu’au bout</strong>, car « vous ne pouvez pas l’utiliser avant de l’avoir lu » est l’exigence, et un bouton actif ne demande à personne de lire quoi que ce soit. ⛔ Appliqué à la frontière RPC du plug-in, pas dans l’interface — une page rechargée, contournée ou pilotée depuis les devtools ne peut toujours pas générer — et par une <em>liste d’autorisation</em>, si bien qu’une nouvelle commande doit être ajoutée délibérément pour être accessible avant l’acceptation. <strong>Refuser laisse le plug-in inerte plutôt que de fermer la DAW</strong>, ce qu’un plug-in ne doit jamais faire ; l’accord peut être rouvert et accepté à tout moment, et tout fonctionne immédiatement après. L’acceptation est stockée par utilisateur, à côté des préréglages — jamais dans le fichier de projet, ce qui demanderait à un collaborateur de réaccepter parce qu’il a ouvert votre morceau.","changelog.eaa77cffa60d":"<strong>La version autonome porte l’icône de l’application sous Windows</strong>, avec les chaînes de produit, d’entreprise et de copyright, via un nouveau <code>plugin/build.rs</code>. Un compilateur de ressources manquant produit un avertissement plutôt que de faire échouer le build.","changelog.56cc4a00bc11":"<strong>Un site de documentation</strong> sous <code>docs/</code> : ce que fait le plug-in, comment il suit l’hôte, les graines, les préréglages, les raccourcis et la confidentialité, avec une recherche et un court journal des versions.","changelog.79779a61c76b":"<strong>La version autonome Windows ouvrait une fenêtre vide</strong> (TASK-P16). Le <code>open_blocking</code> de <code>baseview</code> pompe avec <code>GetMessageW(&amp;mut msg, hwnd, …)</code> — un <code>hwnd</code> non NULL, qui ne récupère que les messages de cette fenêtre et de ses enfants et <strong>ne récupère jamais aucun message de thread</strong>. WebView2 est COM/STA et livre ses complétions précisément sous cette forme, via une fenêtre de messages appartenant à COM, si bien que le gestionnaire de protocole personnalisé n’était jamais appelé, que la navigation ne se terminait jamais et que la page restait sur <code>about:blank</code>. L’adaptateur vendorisé vide désormais la file depuis <code>on_frame</code>, <strong>désactivé sauf si le processus le demande</strong> — <code>plugin/src/bin/standalone.rs</code> est le seul appelant et une DAW ne l’exécute jamais, si bien que la file d’un hôte n’est jamais touchée. ⛔ Il ignore les messages appartenant à la fenêtre de l’éditeur et à ses enfants : les distribuer ferait réentrer la procédure de fenêtre de baseview alors qu’elle détient déjà un emprunt <code>RefCell</code>, ce qui panique dans un cadre <code>extern &quot;system&quot;</code> et interrompt le processus. Vérifié en photographiant la fenêtre, pas par un build vert.","changelog.2589337da507":"<strong>Aucun téléchargement avant la <code>v1.0.0</code>.</strong> Les versions de bureau <code>v0.1.0</code> et <code>v0.2.0</code> ont été retirées de GitHub (converties en brouillons ; fichiers intacts), et le site de documentation ne propose aucun lien de téléchargement.","changelog.0ce86044cfae":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-07-29\">2026-07-29</time></span>","changelog.39dc456bb806":"Ajouté — la génération mélodique, et des humeurs qui la multiplient","changelog.54cbe30a27b8":"<strong>Générateur de mélodie</strong> (TASK-035, FR-005). Structures de phrase (boucle de riff, question/réponse, appel/réponse, long arc), préférence pour les notes de l’accord sur les temps forts, notes de couleur, distributions d’intervalles et de contours, sauts d’octave, variation de fin, et les procédés propres à chaque genre : le motif staccato de deux à trois notes de la rage, les attaques calquées sur la caisse claire et le voicing doublé de la drill, les mesures en croches droites et le silence délibéré. Les hauteurs sont choisies comme <strong>degrés de la gamme</strong> et ne deviennent qu’ensuite des notes MIDI, si bien que rester dans la tonalité est structurel plutôt qu’obtenu par filtrage.","changelog.ded02e33501e":"<strong>Générateur de contre-mélodie</strong> (TASK-036, FR-006). Écho à l’octave, écho de cloche, arpège, réponse en lick et nappe tenue, placés dans les trous de la mélodie par construction plutôt que par filtrage après coup.","changelog.eca3ea3c0cbd":"<strong>Humeurs</strong> (TASK-040V, moitié moteur). Un modèle peut écrire des <code>modes</code> nommés — la trap est livrée avec dark, bounce, melodic et minimal — chacun étant un forçage partiel fusionné dans le modèle <em>avant</em> la génération, si bien que chaque générateur respecte une humeur sans savoir que les humeurs existent. Les humeurs s’héritent via <code>extends</code>, si bien qu’un artiste ne propose que les humeurs de sa propre lignée.","changelog.547190faa689":"<strong>Des préréglages que possède le plug-in</strong> (TASK-P13, moitié session). Six préréglages d’usine compilés dans le binaire, les préréglages utilisateur dans le dossier de données par utilisateur de la plateforme, et un volet dans le panneau droit. Aucun préréglage d’usine ne fixe de tempo — cela écraserait celui de votre DAW au chargement.","changelog.65770bb90ada":"<strong>L’éditeur Linux</strong> (TASK-P12). La fenêtre du plug-in s’ouvre désormais sous Linux via X11 et WebKitGTK, vérifiée en la photographiant sous Xvfb plutôt que par un build vert.","changelog.b0300de13023":"<strong>Une mélodie répétée ne se heurte plus aux accords sur lesquels elle se répète.</strong> Un riff suit désormais la progression, en gardant son propre contour et son propre rythme.","changelog.247d12fdb7be":"<strong>La contre-mélodie n’est plus muette environ la moitié du temps.</strong> Un écho à l’octave est retardé, car une copie à l’octave sans retard est un doublage.","changelog.313e41270887":"<strong>Les nappes tenues font sonner plus que la fondamentale de l’accord</strong>, et choisissent leur octave.","changelog.8395c17cc35d":"<strong><code>echoOffset: &quot;1/8&quot;</code> est lu.</strong> L’analyseur de valeurs de notes connaissait <code>&quot;8th&quot;</code> et <code>&quot;16T&quot;</code> et ignorait silencieusement la troisième graphie qu’utilise le jeu de données.","changelog.be33f8017295":"<strong>Le champ de graine affiche une graine entière.</strong> Il faisait 12 caractères de large pour un <code>u64</code> de 20 chiffres, si bien qu’une graine longue était tronquée — et une graine que vous ne pouvez pas lire est une graine que vous ne pouvez pas retaper.","changelog.e93ad35a782f":"Modifié — Freally MIDI Master devient un plug-in","changelog.e77df776964c":"Décidé le 2026-07-28. Pas pour le format en soi : un plug-in reçoit le tempo, la signature rythmique et la tête de lecture de l’hôte, si bien qu’un motif généré atterrit dans le morceau que vous êtes vraiment en train d’écrire plutôt qu’au tempo auquel l’artiste est écrit. <code>docs/product-roadmap.md</code> consigne la décision, ce qui a survécu et ce qui n’a pas survécu.","changelog.1edfdd003cdf":"<strong>Nouvelle crate <code>plugin/</code></strong> sur <code>nih-plug</code>, qui exporte du <strong>CLAP</strong>. VST3 et AU en sont projetés par <code>clap-wrapper</code> au moment du packaging.","changelog.bf25160e0d26":"<strong>La crate <code>engine</code> est inchangée</strong>, et c’était tout l’intérêt de la garder libre de types du shell. Pas de FFI ni de C++.","changelog.a9420b95b887":"<strong>Synchronisation au tempo de l’hôte</strong>, avec la priorité <strong>valeur fixée par l’utilisateur &gt; hôte &gt; modèle</strong>. La trap écrite à 140 génère à 92 dans un projet à 92 BPM ; un tempo fixé l’emporte sur l’hôte ; un hôte qui n’a pas encore communiqué son tempo laisse au modèle sa propre valeur.","changelog.e33f68653f46":"<strong>Les notes sont émises sur la piste de l’hôte</strong>, en remplacement du glisser-déposer.","changelog.a8f70eb81ba2":"<strong>La session est enregistrée avec le projet.</strong> L’artiste, la graine, les valeurs fixées, les mesures et la taille de la fenêtre passent par les propres appels d’état de l’hôte — il n’y a pas de fichier de paramètres ni de chemin à trouver, et une session appartient à un <em>morceau</em> plutôt qu’à une machine. Les notes ne sont pas enregistrées ; les entrées qui les produisent le sont, car le moteur est déterministe et un fichier de projet ne devrait pas porter de notes régénérables.","changelog.105c98ac6345":"<strong>La fenêtre a trois échelles</strong> (petite, moyenne, grande) sur un bouton de la barre de transport. La mise en page reste en 1440x900 à toutes les échelles — la fenêtre est dessinée plus petite, plutôt que d’en montrer moins — si bien que les panneaux du kit et de la session ne disparaissent jamais simplement parce que la fenêtre a rétréci.","changelog.7e09563eaf78":"<strong>Vérifié dans Ableton Live 12 (VST3) et FL Studio (CLAP).</strong> FL est le premier hôte à charger le <code>.clap</code> lui-même plutôt que la projection.","changelog.824480676fdb":"<strong>Les versions portent désormais le plug-in</strong>, sous la forme d’un zip par plateforme contenant à la fois le <code>.clap</code> et le <code>.vst3</code>, validé par <code>clap-validator</code> avant la publication du brouillon et refusé par <code>verify-downloads.yml</code> si l’un des formats manque.","changelog.2b3dec8da18b":"Supprimé — l’application de bureau est retirée","changelog.2e83aecc5538":"Freally MIDI Master est désormais livré comme <strong>plug-in</strong>. Les versions à partir d’ici portent le CLAP et le VST3 et rien d’autre ; les installateurs Windows, macOS et Linux ne sont plus compilés.","changelog.a99e41cef5bf":"<strong>Si vous êtes sur la v0.2.0 :</strong> rien de ce que vous avez installé ne cesse de fonctionner, et rien n’est désinstallé. Votre copie cessera simplement de trouver des mises à jour, car il n’y en aura pas — le canal de mise à jour se tait plutôt que de casser. Pour continuer, installez le plug-in de cette version et chargez-le dans votre DAW, là où vivent la synchronisation du tempo, la tonalité de l’hôte et les notes sur la piste. C’est toute la raison du changement : l’application de bureau ne pouvait pas savoir quel morceau vous écriviez.","changelog.0743cfc41115":"Problème connu","changelog.4565e7c201a6":"<strong>Un fichier de projet corrompu peut faire planter l’hôte.</strong> Le chargeur d’état CLAP de <code>nih-plug</code> lit un préfixe de longueur directement dans une allocation sans aucun contrôle de cohérence, si bien qu’un état malformé interrompt le processus au lieu d’échouer à se charger. C’est un bug en amont, le fork maintenu le porte à l’identique, et il faut un fork patché pour le corriger. Le <code>state-invalid-random</code> de <code>clap-validator</code> est exclu nommément d’ici là.","changelog.8b8422eaf91b":"<strong>L’interface a été reprise telle quelle.</strong> <code>src/lib/ipc.ts</code> a toujours été l’unique point de jonction et a gagné une troisième branche ; l’application React, les 18 catalogues de langues et les design tokens sont ceux que livrait l’application de bureau.","changelog.f31c4f9a96b4":"<strong>Puces de session</strong> — BPM, tonalité, gamme et swing, modifiables dans le panneau droit. Vide signifie que l’artiste décide ; une valeur signifie que c’est vous. Dans un hôte, la puce de tempo suit la DAW et le dit.","changelog.4c7bcf4c5c18":"<strong>Le générateur d’accords</strong> (FR-004) : familles de progressions, empilement diatonique de tierces pour que chaque hauteur soit dans la tonalité par construction, accords d’emprunt, accords sus et le drop de la note du milieu propre à la drill, voicings serrés et ouverts, et cellules syncopées de 3 à 5 temps.","changelog.4a720cb1c31f":"<strong><code>scripts/assert-plugin-bundled.mjs</code></strong> — refuse un binaire de plug-in dont l’interface ou le jeu de données n’a pas été embarqué, car cet échec se présente sinon comme une fenêtre vide sans erreur.","changelog.1394f31a74f1":"<strong><code>npm run plugin:standalone</code></strong> — le plug-in dans sa propre fenêtre, sans DAW. <strong><code>npm run plugin:install</code></strong> crée un lien symbolique dans le dossier CLAP, si bien qu’une recompilation est active sans copie.","changelog.d4a08bd89830":"<strong><code>vst3-sys</code> est sous GPLv3</strong> et l’export VST3 de nih-plug le lie — ce qui aurait mis ce produit propriétaire en infraction. Attrapé par <code>cargo deny</code>. Le VST3 vient désormais de <code>clap-wrapper</code> (MIT). Le propre SDK VST3 de Steinberg est passé sous MIT en novembre 2025 ; nih-plug ne l’utilise pas.","changelog.3c8bb13f96c1":"<strong>Le message d’erreur de génération n’a jamais été visible.</strong> <code>.stage__error</code> n’avait aucune règle CSS et se trouvait derrière la couche FX, qui est en <code>position: absolute; inset: 0</code> sur toute la scène.","changelog.e28adf2882ae":"<strong>Un tempo fixé est borné</strong> aux 20–999 d’Ableton Live à la frontière IPC, et le champ BPM n’accepte que des chiffres — <code>&lt;input type=&quot;number&quot;&gt;</code> accepte <code>e</code>, <code>E</code>, <code>+</code> et <code>-</code>, donc « 1e5 » était un tempo légal.","changelog.584e92185850":"<code>.github/workflows/{ci,release}.yml</code> échouaient à <code>format:check</code> sur <code>main</code>.","changelog.a2daa7b868f3":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-07-25\">2026-07-25</time></span>","changelog.a85f00dcce8a":"Phase 1 : l’application fait des beats. Cherchez un artiste, appuyez sur Générer, écoutez, et faites-le glisser dans une DAW.","changelog.e382399a54df":"Le jeu de données de styles est intégré à l’application et chargé au démarrage : chaque modèle est analysé, son héritage résolu et validé avant la première image, et le répertoire est servi à l’interface par les nouvelles commandes <code>roster_summary</code> et <code>resolve_model</code>. Un modèle invalide est ignoré et signalé plutôt que de servir de raison pour refuser de démarrer.","changelog.e2d9c9671a0f":"L’humaniseur : swing MPC (de 50 % droit à 66 % ternaire), niveaux de vélocité pour les accents, les coups principaux et les ghost notes, jitter de timing par piste en millisecondes, et une force de quantification qui décide quelle part de ce jitter survit. Le swing déforme toute la ligne de temps, si bien que les roulements écrits à des résolutions plus fines voyagent avec le temps auquel ils appartiennent.","changelog.a6d5ebac7ba4":"Le cœur du générateur de batterie : la grammaire du kick (ancrages, densité, syncope, penchant tresillo, l’espace avant la caisse claire, formes explicites sur plusieurs mesures) et le placement de la caisse claire — half-time sur le 3, le backbeat sur 2 et 4, le 3-puis-4 sur deux mesures de la drill, et le train beat country — avec des caisses claires ghost et un clap superposé. La trap sort avec sa caisse claire sur le temps 3 ; la forme de kick sur deux mesures écrite pour la UK drill se reproduit exactement à chaque graine.","changelog.24a70872e862":"Le moteur de charleston : subdivision de base (croches, doubles croches ou groupement tresillo), densité de remplissage, charlestons ouverts qui ferment le charleston en dessous d’eux, une seconde couche avec pitch bend et la montée sur une boucle. Les temps et les croches à contretemps portent l’accent ; les doubles croches entre eux remplissent discrètement.","changelog.22fd6d81f370":"Le vocabulaire des roulements : roulements de charleston par changement de subdivision (de la double croche à la quadruple croche, grilles de triolets comprises), roulements placés en fin de phrase, avant la caisse claire et avant le premier temps, rampes de vélocité dans les deux sens, rafales, trous et clusters décalés — plus des échelles de roulements de caisse claire avec variantes montée-et-arrêt et double couche, le riser de 8 mesures et le cluster bégayé.","changelog.18c3919ac052":"La piste 808 : elle suit le kick dans la proportion où le modèle les verrouille, tient en legato d’une note à la suivante, prend sa fondamentale dans la tonalité de la session, et glisse selon les intervalles que liste le modèle — écrits comme les notes qui se chevauchent qu’un sampler lit comme un portamento. La 808 de la UK drill s’arrête sous la caisse claire ; celle de la trap sonne à travers.","changelog.50975022f50f":"Des fills aux frontières de phrase : une petite variation toutes les deux mesures, une plus grande toutes les huit, et un fill sur la dernière mesure pour qu’une boucle mène quelque part au lieu de s’arrêter net. Les fills prennent la fin de leur mesure et laissent intacts le backbeat — et les ghost notes.","changelog.ee8737dc4dcf":"Douze archétypes de genre de plus : Chicago et NY drill, plugg et pluggnb, jerk, phonk, west-coast club, boom bap, R&amp;B des années 2000, liquid drum &amp; bass, le train beat country et la pop des années 2000 — quinze en tout, chacun avec un test qui vérifie la grammaire qui en fait ce genre. Les modèles peuvent désormais dire que leur 808 est staccato plutôt que legato, qu’ils n’ont pas de 808 du tout, et que leurs fills relancent sur le clap.","changelog.0015d2f49d55":"Snapshots de déterminisme de référence : une graine, un modèle et une session fixés produisent désormais un JSON de motif et un MIDI identiques à l’octet près, figés par des snapshots commités. C’est ce qui fait de la promesse de la puce de graine — collez une graine, obtenez le même beat — une garantie plutôt qu’une intention.","changelog.8ce8ea96f2f6":"La génération et l’export sont accessibles depuis l’application : <code>generate_pattern</code> fait passer un modèle de style par le générateur de batterie et l’humaniseur et renvoie le motif, et <code>export_midi</code> l’écrit dans le dossier de session sous forme de fichier MIDI de type 0. Une requête peut fixer le tempo, la tonalité, la gamme, le swing, le nombre de mesures ou le feeling half-time ; tout ce qu’elle laisse de côté relève du choix propre au modèle, et omettre la graine en tire une nouvelle qui reproduit exactement le résultat.","changelog.599338a80b32":"Dix modèles d’artistes phares sur les bases de genre — Metro Boomin, Southside, Pierre Bourne, OsamaSon, Nettspend, Summrs, Pop Smoke, Travis Scott, Future et Drake — chacun avec des alias pour la recherche, et un test vérifiant que chacun génère quelque chose que son genre parent ne génère pas.","changelog.b4c20dcbec08":"<strong>L’application fait des beats.</strong> Cherchez un artiste, appuyez sur Générer, et le motif apparaît dans la grille de batterie ; appuyez sur Lecture et vous l’entendez ; faites-le glisser dans une DAW ou exportez-le dans un dossier. La recherche est approximative et tolérante — « osa » trouve OsamaSon, « drizzy » trouve Drake, et une faute de frappe tombe quand même juste — au clavier seul : ↑↓ pour se déplacer, Entrée pour valider, Échap pour fermer.","changelog.4ffc65702fcb":"Lecture : un moteur audio temps réel avec un kit de prévisualisation synthétisé, un séquencement précis à l’échantillon, la mise en boucle, une tête de lecture qui suit, et un limiteur pour qu’un motif dense ne fasse jamais craquer la sortie. Une machine sans carte son génère et exporte quand même, et dit pourquoi la lecture n’est pas disponible plutôt que d’échouer silencieusement au clic.","changelog.2a7f05d53d42":"La graine est affichée après chaque génération et peut être recollée pour retrouver le même beat.","changelog.e948705bc342":"Une ondulation de génération balaie la grille pendant la construction d’un motif, si bien qu’un beat arrive plutôt que d’apparaître d’un clignement, en s’illuminant le plus fort là où les notes tombent réellement. Activer le réglage système de réduction des animations la remplace par un court fondu enchaîné — immédiatement, sans redémarrage.","changelog.7f96e11b8d6b":"Les Paramètres indiquent désormais quand un modèle de style a été ignoré au démarrage, avec le fichier et la raison. Un modèle ignoré, c’est un artiste manquant, et jusqu’ici seule la console le mentionnait.","changelog.62ce473bf733":"Débrancher une interface audio en cours de session ne laisse plus l’application silencieusement sourde. Elle dit que le périphérique a disparu, en rouvre un d’elle-même dès qu’il y en a un à ouvrir — en réessayant aussi longtemps qu’il le faut — et dit quand il est revenu. La lecture ne redémarre pas d’elle-même ; appuyer sur Lecture fonctionne de nouveau, et c’est cela qui avait cessé de fonctionner.","changelog.1d647238b180":"Un réglage <strong>Réduire les animations</strong> sous Apparence, pour les machines dont le système n’offre pas cette préférence, ou pour quiconque veut tout le reste animé et cette seule chose immobile. Il prend effet dès qu’il est coché.","changelog.1b03300b577b":"Le MIDI exporté porte désormais une armure. C’était le seul champ de session que le fichier ne décrivait pas, si bien qu’un clip arrivait dans un projet sans dire dans quelle tonalité était sa 808. Un mode est écrit comme son majeur ou mineur parallèle, ce qui est tout ce que le format peut dire. <strong>Les snapshots <code>.mid</code> de référence ont été régénérés pour cela</strong> : six octets par fichier, le nouvel événement méta et rien d’autre — le JSON du motif n’est pas touché.","changelog.ef6c13561f1f":"Un glissement de 808 peut désormais atteindre une octave au-dessus de la note de départ au lieu d’être replié dans le registre du modèle. Un glide à l’octave — la signature du phonk — tombait auparavant sur sa propre fondamentale et était jeté.","changelog.eba636f4a895":"La résolution de l’héritage ne copie plus tout le modèle accumulé à chaque étape d’une chaîne, ce qui a fait passer le chargement de 1 000 modèles de 330 ms à 219 ms — dans le budget de démarrage de 300 ms.","changelog.a287a4382167":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-07-22\">2026-07-22</time></span>","changelog.221bea271dc0":"Premier build tagué : la fondation de la Phase 0. Le shell Studio, le moteur de génération pur, le jeu de données des modèles de style et toute l’épine dorsale de CI sont en place ; les générateurs eux-mêmes arrivent en Phase 1, si bien que le transport et Générer sont délibérément désactivés plutôt que de faire semblant de fonctionner.","changelog.44d12397d83d":"Shell Tauri v2 + React + TypeScript sur un workspace Cargo, avec la crate pure <code>engine</code> (pas de types Tauri, pas de réseau, pas d’<code>unsafe</code>).","changelog.22cecd1d88c2":"Disposition Studio : panneau gauche, six onglets de générateurs, scène en grille, panneau droit et transport, chaque panneau pouvant être replié indépendamment et l’état étant persisté.","changelog.6c76ad6437f8":"Thèmes sombre et clair, avec un contraste vérifié selon WCAG 2.1 AA dans les deux.","changelog.654cc0ec749e":"Cœur du moteur : <code>Pattern</code>/<code>Note</code>/<code>Lane</code>/<code>Song</code>, <code>SessionContext</code>, et un RNG ChaCha8 à graine avec dérivation de flux par domaine, si bien que relancer une partie laisse toutes les autres identiques à l’octet près.","changelog.b59482b3b460":"Jeu de données de styles : JSON Schema, fusion profonde de l’héritage avec détection des cycles, lints sémantiques, et les trois premiers archétypes de genre — trap, uk-drill, rage.","changelog.d7edc4251d89":"CLI <code>datasetc</code> — validation, lint, statistiques, couverture.","changelog.3305f4e20d1f":"Rapporteur de plantages selon le standard Havoc : sur option, nettoyé, jamais transmis sans un clic.","changelog.179fa09246b2":"CI sur trois OS, contrôles de la chaîne d’approvisionnement, et la liste noire des dépendances IA/réseau.","changelog.c8dd551642f8":"E2E Playwright contre <code>vite dev</code>, avec l’IPC simulé en un seul point de jonction.","changelog.723cf83ffaea":"Fenêtre sans bordure avec ses propres commandes de réduction / agrandissement / fermeture, un titre centré, et un redimensionnement par glissement sur les huit bords.","changelog.3fb0f4c44595":"Paramètres et À propos, accessibles depuis la barre de titre, avec une option de zone de notification (réduire dans la zone de notification et fermer dans la zone de notification, toutes deux désactivées par défaut).","changelog.a03b8762dc6b":"Rapporteur de bugs et système de mise à jour au standard Havoc.","changelog.671f83dcff8b":"<strong>Dix-huit langues</strong> — l’anglais plus l’arabe, le chinois (simplifié), le néerlandais, le français, l’allemand, le hindi, l’indonésien, l’italien, le japonais, le coréen, le polonais, le portugais (Brésil), le russe, l’espagnol, le turc, l’ukrainien et le vietnamien. Le changement est instantané, persistant, et l’arabe met toute la mise en page en miroir.","changelog.331da1149c6a":"<strong>Noto partout</strong>, intégré : 546 fontes couvrant le CJK, l’arabe, l’hébreu, les écritures indiennes, le thaï, le khmer, le géorgien, l’arménien, l’éthiopien et plus encore, si bien qu’aucune langue ne retombe sur ce que la machine se trouve avoir. Rien n’est récupéré à l’exécution — l’application ne fait toujours aucune requête réseau, à part la vérification des mises à jour.","changelog.6cfc2a93f8cf":"La CI capture l’application en cours d’exécution sur les trois OS, ainsi que la fenêtre Paramètres dans chaque langue, sous forme d’artefacts téléchargeables. La capture macOS est partielle et la tâche le dit (voir Live-To-Do).","changelog.a3c71b90162b":"Limitations connues","changelog.c2fce6ca915a":"Les générateurs, la lecture et l’export audio ne sont pas encore implémentés ; leurs commandes sont désactivées plutôt qu’inertes.","changelog.82af19f3d55a":"Le glisser-déposer natif vers l’extérieur est construit mais <strong>non vérifié avec de vraies DAW</strong> — c’est le point de décision de la Phase 0, et il faut un humain.","changelog.58fced7db00c":"Le menu de la zone de notification (Show / Quit) n’est pas traduit.","changelog.169051a58b53":"Les installateurs ne sont pas signés : attendez-vous à SmartScreen sous Windows et à Gatekeeper sous macOS. Consultez les notes de version pour les étapes propres à chaque plateforme."};
